import { Box, Button, Table, TableBody, TableCell, TableHead, TableRow, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { DataManager } from '../../../../data/DataManager';
import { MachineData } from '../../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { AxisCalibrationWizard } from '../AxisCalibrationWizard';
import { ReturnToStartStep } from './ReturnToStartStep';

/**
 * Step to review the calculated adjustment and apply or try again
 */
export class ReviewAdjustmentStep extends WizardStep {
    getTitle(): string {
        const wizard = this.wizard as AxisCalibrationWizard;
        return `Review ${wizard.state.selectedAxis} Axis Adjustment`;
    }

    nextStep(): WizardStep | null {
        return null; // Final step
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="review-adjustment-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <ReviewAdjustmentStepComponent step={this} />}
            />
        );
    }
}

interface ReviewAdjustmentStepComponentProps {
    step: ReviewAdjustmentStep;
}

function ReviewAdjustmentStepComponent({ step }: ReviewAdjustmentStepComponentProps) {
    const wizard = step.wizard as AxisCalibrationWizard;
    const colors = ConfigurationDataColors.Instance;

    const axisName = wizard.state.selectedAxis;
    const actualDistance = wizard.state.actualDistance;
    const commandedDistance = wizard.state.commandedDistance || 10;

    // Get axis configuration
    const machineData = MachineData.Instance;
    const axis = machineData.axisConfigurations.find(a => a.axisType === axisName);
    if (!axis) return <div>Error: Axis not found</div>;

    // Calculate current and new turns ratios
    // If machine reported moving X inches but actually moved Y inches,
    // we need to adjust turns ratio by the ratio: commanded / actual
    const currentTurnsRatio = axis.overallTurnsRatio;

    // Validate actualDistance is not null
    if (actualDistance === null || actualDistance === 0) {
        return (
            <Box sx={{ p: 3 }}>
                <Typography variant="h6" color="error">
                    Error: Invalid actual distance
                </Typography>
                <Typography variant="body2" sx={{ color: colors.mutedTextColor, mt: 2 }}>
                    Please go back and measure the actual distance traveled.
                </Typography>
            </Box>
        );
    }

    const ratio = commandedDistance / actualDistance;
    const newTurnsRatio = currentTurnsRatio * ratio;

    // Calculate change percentage
    const changePercent = ((newTurnsRatio - currentTurnsRatio) / currentTurnsRatio) * 100;

    const handleApply = async () => {
        try {
            if (!axis) {
                Logger.Instance.logError(LogCategory.System, `Failed to find ${axisName} axis`);
                UserMessageQueue.Instance.addMessage(`❌ Failed to find ${axisName} axis`);
                return;
            }

            // Update axis configuration with new turns ratio
            axis.overallTurnsRatio = newTurnsRatio;

            // Save configuration
            await DataManager.Instance.saveMachineDataIndividual();

            UserMessageQueue.Instance.addMessage(`✓ ${axisName} axis calibration applied successfully`);

            // Complete wizard successfully
            wizard.completeWizard();
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to apply axis calibration:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to apply calibration changes');
        }
    };

    const handleTryAgain = () => {
        // Go to ReturnToStartStep to ask if they want to return to starting position
        wizard.currentStep = new ReturnToStartStep(wizard, step);
        StateManager.propertyChanged(wizard, 'currentStep');
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    const handleCancel = () => {
        wizard.cancelWizard();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Step 4: Review New Turns Ratio
                </Typography>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Here's the new turns ratio calculated for the {axisName} axis based on your measurement.
                </Typography>
            </Box>

            {/* Main content */}
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 3 }}>
                {/* Measurement summary */}
                <Box sx={{
                    p: 3,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    border: `1px solid ${colors.borderColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.mutedTextColor, mb: 2 }}>
                        Measurement Summary:
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 4 }}>
                        <Box>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor }}>
                                Machine Reported
                            </Typography>
                            <Typography variant="h6" sx={{ color: colors.darkTextColor, fontFamily: 'monospace' }}>
                                {commandedDistance.toFixed(4)}"
                            </Typography>
                        </Box>
                        <Box>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor }}>
                                You Measured
                            </Typography>
                            <Typography variant="h6" sx={{ color: colors.darkTextColor, fontFamily: 'monospace' }}>
                                {actualDistance.toFixed(4)}"
                            </Typography>
                        </Box>
                        <Box>
                            <Typography variant="caption" sx={{ color: colors.mutedTextColor }}>
                                Error
                            </Typography>
                            <Typography variant="h6" sx={{
                                color: Math.abs(commandedDistance - actualDistance) > (commandedDistance * 0.01) ? colors.warningColor : colors.successColor,
                                fontFamily: 'monospace',
                                fontWeight: 'bold'
                            }}>
                                {((actualDistance - commandedDistance) / commandedDistance * 100).toFixed(2)}%
                            </Typography>
                        </Box>
                    </Box>
                </Box>

                {/* Comparison table */}
                <Box sx={{
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    border: `1px solid ${colors.borderColor}`,
                    overflow: 'hidden'
                }}>
                    <Table size="small">
                        <TableHead>
                            <TableRow sx={{ backgroundColor: colors.primaryColor }}>
                                <TableCell sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Metric</TableCell>
                                <TableCell align="right" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Current Value</TableCell>
                                <TableCell align="right" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>New Value</TableCell>
                                <TableCell align="right" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>Change</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            <TableRow>
                                <TableCell sx={{ color: colors.darkTextColor }}>Turns Ratio</TableCell>
                                <TableCell align="right" sx={{ color: colors.darkTextColor, fontFamily: 'monospace' }}>
                                    {currentTurnsRatio.toFixed(6)}
                                </TableCell>
                                <TableCell align="right" sx={{
                                    color: colors.primaryColor,
                                    fontFamily: 'monospace',
                                    fontWeight: 'bold'
                                }}>
                                    {newTurnsRatio.toFixed(6)}
                                </TableCell>
                                <TableCell align="right" sx={{
                                    color: changePercent > 0 ? colors.errorColor : colors.successColor,
                                    fontFamily: 'monospace',
                                    fontWeight: 'bold'
                                }}>
                                    {changePercent > 0 ? '+' : ''}{changePercent.toFixed(2)}%
                                </TableCell>
                            </TableRow>
                        </TableBody>
                    </Table>
                </Box>

                {/* Calculation explanation */}
                <Box sx={{
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Calculation:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 1 }}>
                        The turns ratio is adjusted based on your actual movement to make the axis more accurate.
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, fontFamily: 'monospace' }}>
                        New Ratio = ({commandedDistance.toFixed(2)} ÷ {actualDistance.toFixed(4)}) × {currentTurnsRatio.toFixed(6)} = {newTurnsRatio.toFixed(6)}
                    </Typography>
                </Box>

                {/* Warning if large change */}
                {Math.abs(changePercent) > 5 && (
                    <Box sx={{
                        p: 2,
                        backgroundColor: `${colors.warningColor}20`,
                        borderRadius: 1,
                        borderLeft: `4px solid ${colors.warningColor}`
                    }}>
                        <Typography variant="subtitle2" sx={{ color: colors.warningColor, fontWeight: 'bold', mb: 1 }}>
                            ⚠ Large Adjustment Detected
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 1 }}>
                            The calculated adjustment is greater than 5%. This could indicate:
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            • Measurement error - verify your reading
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            • Mechanical issue with the axis
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                            • Initial steps per inch setting was far off
                        </Typography>
                    </Box>
                )}

                {/* Success message if small change */}
                {Math.abs(changePercent) <= 1 && (
                    <Box sx={{
                        p: 2,
                        backgroundColor: `${colors.successColor}20`,
                        borderRadius: 1,
                        borderLeft: `4px solid ${colors.successColor}`
                    }}>
                        <Typography variant="subtitle2" sx={{ color: colors.successColor, fontWeight: 'bold', mb: 1 }}>
                            ✓ Excellent Calibration
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                            The required adjustment is minimal (≤1%), indicating the axis was already well calibrated.
                        </Typography>
                    </Box>
                )}
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button
                        variant="outlined"
                        onClick={handleBack}
                    >
                        Back
                    </Button>
                    <Button
                        variant="outlined"
                        onClick={handleCancel}
                    >
                        Cancel
                    </Button>
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button
                        variant="outlined"
                        onClick={handleTryAgain}
                        sx={{ borderColor: colors.warningColor, color: colors.warningColor }}
                    >
                        Apply and Rerun
                    </Button>
                    <Button
                        variant="contained"
                        onClick={handleApply}
                        sx={{ backgroundColor: colors.successColor }}
                    >
                        Apply Changes
                    </Button>
                </Box>
            </Box>
        </Box>
    );
}
