import {
    Close as CloseIcon,
    Description as FileIcon,
    Build as ToolIcon
} from '@mui/icons-material';
import {
    Box,
    Dialog,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { Job } from '../../../data/Job';

export interface JobInfoHeaderProps {
    jobName: string;
    job: Job | null;
    gcodeContent?: string;
}

export function JobInfoHeader({ jobName, job, gcodeContent }: JobInfoHeaderProps) {
    const colors = ConfigurationDataColors.Instance;
    const toolLibrary = ToolLibrary.Instance;
    const [showToolsDialog, setShowToolsDialog] = useState(false);

    return (
        <>
            <Box sx={{
                display: 'flex',
                alignItems: 'center',
                gap: 2,
                flex: 1
            }}>
                <Typography variant="h6">
                    {jobName}
                </Typography>

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, ml: 'auto' }}>
                    {/* Dimensions */}
                    <Typography variant="h6" color="primary" sx={{ fontWeight: 'bold' }}>
                        {(() => {
                            const extents = job ? job.getToolpathExtents() : null;
                            if (!extents) return '';
                            return `${extents.maxX.toFixed(2)}" × ${extents.maxY.toFixed(2)}"`;
                        })()}
                    </Typography>

                    <Typography variant="h6" color="text.secondary">|</Typography>

                    {/* Z0 Reference */}
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography variant="body2" color="text.secondary">
                            Z0 =
                        </Typography>
                        <Typography variant="h6" sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                            {(() => {
                                const zRef = job ? job.analyzeZReference() : null;
                                return zRef || '';
                            })()}
                        </Typography>
                    </Box>

                    <Typography variant="h6" color="text.secondary">|</Typography>

                    {/* Line Count */}
                    {gcodeContent && (
                        <>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <FileIcon fontSize="small" color="action" />
                                <Typography variant="body2">
                                    <strong>{(() => {
                                        const lines = gcodeContent.split('\n').length;
                                        return `${lines.toLocaleString()} lines`;
                                    })()}</strong>
                                </Typography>
                            </Box>

                            <Typography variant="h6" color="text.secondary">|</Typography>
                        </>
                    )}

                    {/* Tool Count */}
                    <Box
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 1,
                            cursor: 'pointer',
                            '&:hover': {
                                opacity: 0.7
                            }
                        }}
                        onClick={() => setShowToolsDialog(true)}
                    >
                        <ToolIcon fontSize="small" color="action" />
                        <Typography variant="body2">
                            <strong>{(() => {
                                const toolCount = job ? job.getToolNumbers().length : 0;
                                return `${toolCount} tool${toolCount !== 1 ? 's' : ''}`;
                            })()}</strong>
                        </Typography>
                    </Box>
                </Box>
            </Box>

            {/* Tools Dialog */}
            <Dialog
                open={showToolsDialog}
                onClose={() => setShowToolsDialog(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.lightBackgroundColor,
                    borderBottom: `1px solid ${colors.borderColor}`
                }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <ToolIcon />
                        <Typography variant="h6">Required Tools</Typography>
                    </Box>
                    <IconButton onClick={() => setShowToolsDialog(false)} size="small">
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent sx={{ p: 0 }}>
                    <List>
                        {(() => {
                            const toolNumbers = job ? job.getToolNumbers() : [];

                            if (toolNumbers.length === 0) {
                                return (
                                    <ListItem>
                                        <ListItemText
                                            primary="No tools required"
                                            secondary="This G-code does not contain any tool changes"
                                        />
                                    </ListItem>
                                );
                            }

                            return toolNumbers.map((toolNumber, index) => {
                                const tool = toolLibrary.getToolByNumber(toolNumber);

                                return (
                                    <ListItem
                                        key={toolNumber}
                                        sx={{
                                            borderBottom: index < toolNumbers.length - 1 ? `1px solid ${colors.borderColor}` : 'none'
                                        }}
                                    >
                                        <ListItemIcon>
                                            <Box
                                                sx={{
                                                    width: 40,
                                                    height: 40,
                                                    borderRadius: '50%',
                                                    backgroundColor: colors.primaryColor,
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    color: colors.lightTextColor,
                                                    fontWeight: 'bold'
                                                }}
                                            >
                                                T{toolNumber}
                                            </Box>
                                        </ListItemIcon>
                                        <ListItemText
                                            primary={tool ? tool.toolName : `Tool ${toolNumber}`}
                                            secondary={tool ? (
                                                <>
                                                    <Typography component="span" variant="body2" sx={{ display: 'block' }}>
                                                        Diameter: {tool.cuttingDiameter}" | Length: {tool.lengthBelowHolder}"
                                                    </Typography>
                                                    {(tool.toolOffsetX !== 0 || tool.toolOffsetY !== 0) && (
                                                        <Typography component="span" variant="body2" sx={{ display: 'block' }}>
                                                            Offsets: X={tool.toolOffsetX}", Y={tool.toolOffsetY}"
                                                        </Typography>
                                                    )}
                                                </>
                                            ) : (
                                                <Typography component="span" variant="body2" color="error">
                                                    Tool not found in library
                                                </Typography>
                                            )}
                                        />
                                    </ListItem>
                                );
                            });
                        })()}
                    </List>
                </DialogContent>
            </Dialog>
        </>
    );
}
