/**
 * Base class for job execution stages
 * Stages represent discrete units of work in a job execution
 */

import { LogCategory, Logger } from '../utils/Logger';
import { StateManager } from '../utils/statemanager/StateManager';

export enum StageType {
    GCode = 'gcode',
    ToolChange = 'toolChange',
    FixtureChange = 'fixtureChange',
    UserMessage = 'userMessage',
    OptionalStop = 'optionalStop',
    ProgramRestart = 'programRestart',
    TimedAction = 'timedAction'
}

export enum StageStatus {
    Pending = 'pending',
    Active = 'active',
    Completed = 'completed',
    Paused = 'paused',
    Error = 'error',
    Skipped = 'skipped'
}

/**
 * Callback interface for stage completion
 */
export interface StageCallback {
    onComplete: () => Promise<void>;
    onError: (errorMessage: string) => Promise<void>;
    onExecuteLine?: (jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean) => void;
    skipPreview?: boolean; // If true, bypass preview dialogs (used when already in run dialog)
}

/**
 * Base abstract class for all job stages
 */
export abstract class JobStage {
    public stageNumber: number;
    public stageType: StageType;
    private _status: StageStatus = StageStatus.Pending;
    public startTime?: Date;
    public endTime?: Date;
    public errorMessage?: string;
    public startLineIndex: number; // 0-based index into original G-code lines
    public endLineIndex: number;   // 0-based index into original G-code lines
    private _ownerJob?: any; // Reference to parent Job for notifications

    constructor(stageNumber: number, stageType: StageType, startLineIndex: number, endLineIndex: number) {
        this.stageNumber = stageNumber;
        this.stageType = stageType;
        this.startLineIndex = startLineIndex;
        this.endLineIndex = endLineIndex;
    }

    public get status(): StageStatus {
        return this._status;
    }

    public set status(value: StageStatus) {
        this._status = value;
        // Notify parent job of stage change for reactive UI updates
        if (this._ownerJob) {
            StateManager.propertyChanged(this._ownerJob, 'stages');
        }
    }

    /**
     * Set the owner job for this stage (used for StateManager notifications)
     */
    public setOwnerJob(job: any): void {
        this._ownerJob = job;
    }

    /**
     * Execute this stage with callback-based continuation
     * @param callback Callback with onComplete, onError, and optional skipPreview flag
     */
    public async runStage(callback?: StageCallback): Promise<void> {
        try {
            this.status = StageStatus.Active;
            this.startTime = new Date();

            await this.executeStage(callback);

            // Note: Stage status is set by executeStage implementation
            // Stages must call callback.onComplete() or callback.onError() when done
        } catch (error) {
            this.status = StageStatus.Error;
            this.endTime = new Date();
            this.errorMessage = error instanceof Error ? error.message : String(error);
            Logger.Instance.logError(LogCategory.System, `Error in stage ${this.stageNumber}:`, error);

            // Call onError if callback provided
            if (callback) {
                await callback.onError(this.errorMessage);
            }
        }
    }

    /**
     * Abstract method to be implemented by subclasses
     * Must call callback.onComplete() or callback.onError() when stage is done
     * @param callback Callback with onComplete and onError methods
     */
    protected abstract executeStage(callback?: StageCallback): Promise<void>;

    /**
     * Get the stage type name (e.g., "G-Code Block", "Tool Change", "Timed Action")
     */
    public abstract getStageName(): string;

    /**
     * Get display name for this stage
     */
    public abstract getDisplayName(): string;

    /**
     * Get description of this stage for UI display
     */
    public abstract getDescription(): string;

    /**
     * Get structured display data for the stage
     * Returns an array of lines to display in the UI
     */
    public getStageDisplayData(): string[] {
        return [
            this.getDisplayName(),
            this.getDescription()
        ];
    }

    /**
     * Get G-code lines for this stage with context lines before and after
     * Returns object with before/stage/after line arrays
     */
    public getGCodeLinesWithContext(allGCodeLines: string[], contextLineCount: number = 5): {
        beforeLines: string[];
        stageLines: string[];
        afterLines: string[];
    } {
        const beforeStart = Math.max(0, this.startLineIndex - contextLineCount);
        const beforeEnd = this.startLineIndex;
        const afterStart = this.endLineIndex + 1;
        const afterEnd = Math.min(allGCodeLines.length, this.endLineIndex + 1 + contextLineCount);

        return {
            beforeLines: allGCodeLines.slice(beforeStart, beforeEnd),
            stageLines: allGCodeLines.slice(this.startLineIndex, this.endLineIndex + 1),
            afterLines: allGCodeLines.slice(afterStart, afterEnd)
        };
    }

    /**
     * Get the duration of this stage in milliseconds
     */
    public getDuration(): number {
        if (!this.startTime || !this.endTime) return 0;
        return this.endTime.getTime() - this.startTime.getTime();
    }

    /**
     * Reset stage status to pending
     */
    public reset(): void {
        this.status = StageStatus.Pending;
        this.startTime = undefined;
        this.endTime = undefined;
        this.errorMessage = undefined;
    }
}
