import { useState } from 'react';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ViewDataFactory, ViewNames } from '../../utils/ViewDataFactory';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';
import { FloatingWindow } from './FloatingWindow';

export interface ViewerWindowProps {
    onClose: () => void;
}

/**
 * Floating 3D viewer window component
 * Wraps FullSizeCNCViewer in a draggable, resizable floating window
 */
export function ViewerWindow({ onClose }: ViewerWindowProps) {
    const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.FLOATING_VIEWER));
    const machineState = MachineStateData.Instance;
    const machineData = MachineData.Instance;

    return (
        <FloatingWindow
            title="3D Viewer"
            onClose={onClose}
            defaultPosition={{ x: 150, y: 150 }}
            width={800}
            minWidth={600}
            maxWidth={1200}
            defaultHeight={600}
            minHeight={400}
            maxHeight={900}
        >
            <div style={{ width: '100%', height: '100%' }}>
                <FullSizeCNCViewer
                    simulatorViewData={simulatorViewData}
                    machineState={machineState}
                    machineData={machineData}
                    job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
                />
            </div>
        </FloatingWindow>
    );
}
