import { Box, Button, Checkbox, FormControl, FormControlLabel, InputLabel, MenuItem, Select, Typography } from '@mui/material';
import React from 'react';
import { ToolLibrary } from '../../../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { MeasureAllToolsWizard } from '../MeasureAllToolsWizard';
import { MeasuringStep } from './MeasuringStep';

export class SelectToolsStep extends WizardStep {
    constructor(wizard: MeasureAllToolsWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Measure All Tools - Select Tools';
    }

    nextStep(): WizardStep | null {
        return new MeasuringStep(this.wizard as MeasureAllToolsWizard, this);
    }

    backStep(): WizardStep | null {
        return null;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="select-tools-step"
                listenTo={MachineStateData.Instance}
                properties={['currentToolNumber']}
                control={() => <SelectToolsStepComponent step={this} />}
            />
        );
    }
}

interface SelectToolsStepComponentProps {
    step: SelectToolsStep;
}

function SelectToolsStepComponent({ step }: SelectToolsStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineData = MachineData.Instance;
    const machineState = MachineStateData.Instance;
    const toolLibrary = ToolLibrary.Instance;
    const wizard = step.wizard as MeasureAllToolsWizard;

    // Get ATC slots with assigned tools
    const atcToolsWithNumbers = React.useMemo(() => {
        return machineData.atcToolClamps
            .filter(slot => {
                if (slot.clampNumber === null || slot.clampNumber === 0) {
                    return false;
                }
                const tool = toolLibrary.getToolByNumber(slot.clampNumber);
                return tool !== null && tool !== undefined;
            })
            .map(slot => {
                const tool = toolLibrary.getToolByNumber(slot.clampNumber);
                if (!tool) return null;
                return {
                    toolNumber: slot.clampNumber!,
                    toolName: tool.displayName,
                    clampNumber: slot.clampNumber!
                };
            })
            .filter((item): item is NonNullable<typeof item> => item !== null)
            .sort((a, b) => a.toolNumber - b.toolNumber);
    }, [machineData.atcToolClamps, toolLibrary]);

    const [selectedTools, setSelectedTools] = React.useState<Set<number>>(() => {
        return new Set(atcToolsWithNumbers.map(t => t.toolNumber));
    });

    const [currentToolNumber, setCurrentToolNumber] = React.useState<number | null>(
        machineState.currentToolNumber
    );

    const handleToggleTool = (toolNumber: number) => {
        const newSelected = new Set(selectedTools);
        if (newSelected.has(toolNumber)) {
            newSelected.delete(toolNumber);
        } else {
            newSelected.add(toolNumber);
        }
        setSelectedTools(newSelected);
    };

    const handleSelectAll = () => {
        setSelectedTools(new Set(atcToolsWithNumbers.map(t => t.toolNumber)));
    };

    const handleDeselectAll = () => {
        setSelectedTools(new Set());
    };

    const handleNext = async () => {
        // Update wizard state with selections
        wizard.state = {
            ...wizard.state,
            selectedTools: Array.from(selectedTools),
            currentToolNumber
        };
        StateManager.propertyChanged(wizard, 'state');

        // Update current tool in machine state if changed
        if (currentToolNumber !== machineState.currentToolNumber) {
            machineState.currentToolNumber = currentToolNumber ?? 0;
            await machineState.manualSave();
        }

        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Confirm tools to measure. All ATC slots with assigned tools are listed below.
                </Typography>

                <FormControl fullWidth>
                    <InputLabel>Current Tool in Spindle</InputLabel>
                    <Select
                        value={currentToolNumber ?? ''}
                        onChange={(e) => setCurrentToolNumber(e.target.value === '' ? null : Number(e.target.value))}
                        label="Current Tool in Spindle"
                    >
                        <MenuItem value="">No Tool</MenuItem>
                        {toolLibrary.tools
                            .filter(tool => tool.toolNumber !== null)
                            .sort((a, b) => (a.toolNumber ?? 0) - (b.toolNumber ?? 0))
                            .map((tool) => (
                                <MenuItem key={tool.toolNumber} value={tool.toolNumber!}>
                                    T{tool.toolNumber} - {tool.displayName}
                                </MenuItem>
                            ))}
                    </Select>
                </FormControl>

                {atcToolsWithNumbers.length === 0 ? (
                    <Typography variant="body2" sx={{ color: colors.mutedTextColor }}>
                        No ATC slots have assigned tool numbers.
                    </Typography>
                ) : (
                    <>
                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                            <Button
                                size="small"
                                onClick={handleSelectAll}
                                disabled={selectedTools.size === atcToolsWithNumbers.length}
                            >
                                Select All
                            </Button>
                            <Button
                                size="small"
                                onClick={handleDeselectAll}
                                disabled={selectedTools.size === 0}
                            >
                                Deselect All
                            </Button>
                        </Box>

                        <Box
                            sx={{
                                backgroundColor: colors.lightBackgroundColor,
                                borderRadius: 1,
                                padding: 2,
                                border: `1px solid ${colors.borderColor}`,
                                maxHeight: '400px',
                                overflowY: 'auto'
                            }}
                        >
                            {atcToolsWithNumbers.map((toolInfo) => (
                                <FormControlLabel
                                    key={toolInfo.toolNumber}
                                    control={
                                        <Checkbox
                                            checked={selectedTools.has(toolInfo.toolNumber)}
                                            onChange={() => handleToggleTool(toolInfo.toolNumber)}
                                        />
                                    }
                                    label={`T${toolInfo.toolNumber} - ${toolInfo.toolName} (Slot ${toolInfo.clampNumber})`}
                                    sx={{ display: 'block', mb: 0.5 }}
                                />
                            ))}
                        </Box>
                    </>
                )}
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="text"
                    onClick={() => wizard.cancelWizard()}
                >
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleNext}
                    disabled={selectedTools.size === 0}
                >
                    Start Measuring {selectedTools.size} Tool{selectedTools.size !== 1 ? 's' : ''}
                </Button>
            </Box>
        </Box>
    );
}
