import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Box } from './Box';

export interface GantryProps {
  simulatorView: SimulatorView;
  machineData: MachineData;
  machineState: MachineStateData;
}

export function Gantry({
  simulatorView,
  machineData,
  machineState
}: GantryProps) {
  // Get configuration colors and state
  const colors = ConfigurationDataColors.Instance;
  const configState = ConfigurationState.Instance;

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['gantry'] },
        { object: ConfigurationState.Instance, properties: ['proposedSpindlePosition', 'currentMachinePoint'] },
        { object: configState, properties: ['isSpindleDragging'] },
        { object: colors, properties: ['gantryTransparency', 'gantryColor', 'gantryPostColor', 'zCarriageColor', 'zCarriagePlateColor', 'zScrewColor'] },
        { object: machineData, properties: ['spindleDiameter', 'zPlateSideExtension', 'zCarriagePlateHeight', 'zCarriagePlateDepth', 'zCarriagePlateVerticalOffset', 'zCarriageHorizontalOffset', 'zCarriageWidth', 'zCarriageVerticalOffset', 'zPlateDepth'] }
      ]}
      control={() => {
        // Calculate opacity once for reuse on all gantry elements
        const gantryOpacity = (ConfigurationState.Instance.proposedSpindlePosition || configState.isSpindleDragging)
          ? colors.gantryTransparency  // Use base transparency when proposed position exists or spindle is selected
          : (simulatorView.gantry === ViewStyle.SemiTransparent ? colors.gantryTransparency : 1);

        // Create unique key based on viewStyle and opacity for React re-rendering
        const baseKey = `gantry-${ViewStyle[simulatorView.gantry]}-${gantryOpacity}-${Date.now()}`;

        // Get current spindle position and convert to simulator coordinates
        // Use proposedSpindlePosition if it exists (during drag), otherwise use currentMachinePoint
        const currentPosition = ConfigurationState.Instance.proposedSpindlePosition || ConfigurationState.Instance.currentMachinePoint;
        const simulatorPosition = CoordinateUtil.toSimulator(currentPosition);

        // Calculate gantry Y position: spindle Y position + spindle center offset (matches C# implementation)
        // The offset should position the FRONT of the gantry beam, not the center
        // So we need to add half the gantry beam width to position the center correctly
        const currentGantryPosition = simulatorPosition.y + machineData.spindleCenterOffset + (machineData.gantryBarWidth / 2);

        // Convert gantry Y position from simulator to machine coordinates for geometry calculations
        const gantryYMachine = CoordinateUtil.toMachineZero(new CNCPoint(0, currentGantryPosition, 0, CoordinateType.Simulator)).y;

        // Get geometry boxes for gantry components (in machine coordinates)
        const gantryBarBox = CoordinateUtil.getGantryBarBox(gantryYMachine, machineState);
        const leftPostBox = CoordinateUtil.getLeftGantryPostBox(gantryYMachine, machineState);
        const rightPostBox = CoordinateUtil.getRightGantryPostBox(gantryYMachine, machineState);

        // Convert box centers to simulator coordinates for rendering
        const gantryBarPosition = CoordinateUtil.toSimulator(
          new CNCPoint(gantryBarBox.centerX, gantryBarBox.centerY, gantryBarBox.z + gantryBarBox.height / 2, CoordinateType.MachineZero)
        );
        const leftPostPosition = CoordinateUtil.toSimulator(
          new CNCPoint(leftPostBox.centerX, leftPostBox.centerY, leftPostBox.z + leftPostBox.height / 2, CoordinateType.MachineZero)
        );
        const rightPostPosition = CoordinateUtil.toSimulator(
          new CNCPoint(rightPostBox.centerX, rightPostBox.centerY, rightPostBox.z + rightPostBox.height / 2, CoordinateType.MachineZero)
        );

        // Get spindle X/Y position in machine coordinates for Z-carriage components
        const spindleXYMachine = CoordinateUtil.toMachineZero(currentPosition);

        // Get Z-carriage body box (moves with spindle X/Y, Z position from gantry)
        const zCarriageBox = CoordinateUtil.getZCarriageBox(spindleXYMachine, gantryYMachine, machineState);

        // Get Z-carriage plate box (moves with spindle X/Y, fixed Z from gantry)
        const zCarriagePlateBox = CoordinateUtil.getZCarriagePlateBox(spindleXYMachine, gantryYMachine, machineState);

        // Convert Z-carriage boxes centers to simulator coordinates for rendering
        const zCarriagePosition = CoordinateUtil.toSimulator(
          new CNCPoint(zCarriageBox.centerX, zCarriageBox.centerY, zCarriageBox.z + zCarriageBox.height / 2, CoordinateType.MachineZero)
        );
        const zCarriagePlatePosition = CoordinateUtil.toSimulator(
          new CNCPoint(zCarriagePlateBox.centerX, zCarriagePlateBox.centerY, zCarriagePlateBox.z + zCarriagePlateBox.height / 2, CoordinateType.MachineZero)
        );

        // Calculate Z-screw (cylinder from bottom to top of Z-carriage plate, Y centered on Z-plate)
        const zScrewRadius = (machineData.zPlateDepth * 0.50) / 2;
        const zScrewBottomZ = zCarriagePlateBox.z;
        const zScrewTopZ = zCarriagePlateBox.z + zCarriagePlateBox.height;
        const zScrewHeight = zScrewTopZ - zScrewBottomZ;
        const zScrewCenterZ = zScrewBottomZ + (zScrewHeight / 2);

        // Z-screw Y position: spindle Y position + spindle radius + half Z-plate depth (center of Z-plate)
        const spindleRadius = machineData.spindleDiameter / 2;
        const zPlateDepth = machineData.zPlateDepth;
        const zScrewYMachine = spindleXYMachine.y + spindleRadius + (zPlateDepth / 2);

        const zScrewPosition = CoordinateUtil.toSimulator(
          new CNCPoint(spindleXYMachine.x, zScrewYMachine, zScrewCenterZ, CoordinateType.MachineZero)
        );

        return (
          <group key={baseKey}>
            {/* Z-Screw - cylinder from bottom to top of Z-carriage plate, Y centered on Z-plate */}
            <mesh position={[zScrewPosition.x, zScrewPosition.y, zScrewPosition.z]} rotation={[Math.PI / 2, 0, 0]}>
              <cylinderGeometry args={[zScrewRadius, zScrewRadius, zScrewHeight, 32]} />
              <meshStandardMaterial
                color={colors.zScrewColor}
                opacity={gantryOpacity}
                transparent={gantryOpacity < 1}
              />
            </mesh>

            {/* Z-Carriage Body - moves with spindle X/Y, straddles gantry */}
            <Box
              position={[zCarriagePosition.x, zCarriagePosition.y, zCarriagePosition.z]}
              size={[zCarriageBox.width, zCarriageBox.length, zCarriageBox.height]}
              color={colors.zCarriageColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />

            {/* Z-Carriage Plate - moves with spindle X/Y but fixed Z from gantry */}
            <Box
              position={[zCarriagePlatePosition.x, zCarriagePlatePosition.y, zCarriagePlatePosition.z]}
              size={[zCarriagePlateBox.width, zCarriagePlateBox.length, zCarriagePlateBox.height]}
              color={colors.zCarriagePlateColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />

            {/* Main gantry bar (horizontal) */}
            <Box
              position={[gantryBarPosition.x, gantryBarPosition.y, gantryBarPosition.z]}
              size={[gantryBarBox.width, gantryBarBox.length, gantryBarBox.height]}
              color={colors.gantryColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />

            {/* Left support post */}
            <Box
              position={[leftPostPosition.x, leftPostPosition.y, leftPostPosition.z]}
              size={[leftPostBox.width, leftPostBox.length, leftPostBox.height]}
              color={colors.gantryPostColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />

            {/* Right support post */}
            <Box
              position={[rightPostPosition.x, rightPostPosition.y, rightPostPosition.z]}
              size={[rightPostBox.width, rightPostBox.length, rightPostBox.height]}
              color={colors.gantryPostColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />
          </group>
        );
      }}
    />
  );
};
