import { Box, Button } from '@mui/material';
import { ActionData } from '../../data/ActionData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IOStateData } from '../../data/IOStateData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserActionData } from '../../data/UserActionData';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { UserActionRegistry } from '../../utils/userActions';

/**
 * Props for MachineActionsPanel component
 */
interface MachineActionsPanelProps {
    /** Optional callbacks for custom material/clamp editor handling */
    onEditMaterial?: () => void;
    onEditClamps?: () => void;
    /** Minimum width of the panel (default: '200px') */
    minWidth?: string;
    /** Gap between action items (default: 0.5) */
    gap?: number;
    /** Show specific actions (default: all true) */
    showActions?: {
        homeMachine?: boolean;
        changeFixture?: boolean;
        rememberPoint?: boolean;
        editMaterial?: boolean;
        editClamps?: boolean;
        changeTool?: boolean;
    };
}

/**
 * Reusable panel for common machine setup actions
 * Displays links for actions from the home page action list
 * Actions handle their own dialogs via ModalManager
 * 
 * @example
 * <MachineActionsPanel />
 * 
 * @example
 * // With custom material/clamp editor callbacks
 * <MachineActionsPanel
 *   onEditMaterial={() => // console.log('Edit material')}
 *   onEditClamps={() => // console.log('Edit clamps')}
 * />
 */
export function MachineActionsPanel({
    onEditMaterial,
    onEditClamps,
    minWidth = '200px',
    gap = 0.5,
    showActions = {}
}: MachineActionsPanelProps) {
    const registry = UserActionRegistry.Instance;

    return (
        <ObserveMultiProperties
            key="machine-actions-panel-home-page"
            listenTo={[
                { object: ActionData.Instance, properties: ['allActions', 'isInitialized'] },
                { object: UserActionData.Instance, properties: ['homePageActionIds'] }
            ]}
            control={() => {
                const actionData = ActionData.Instance;
                const userActionData = UserActionData.Instance;

                // Don't render until actions are loaded
                if (!actionData.isInitialized) {
                    return null;
                }

                // Get actions for home page
                const homePageActionIds = userActionData.homePageActionIds;
                const actions = homePageActionIds
                    .map(id => actionData.getAction(id))
                    .filter((action): action is NonNullable<typeof action> => action !== undefined);

                return (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap, minWidth }}>
                        {actions.map((action) => {
                            return (
                                <ObserveMultiProperties
                                    key={`action-${action.id}`}
                                    listenTo={[
                                        { object: ConfigurationState.Instance, properties: ['isHomed', 'isJobRunning'] },
                                        { object: MachineStateData.Instance, properties: ['currentFixture', 'currentToolNumber'] },
                                        { object: IOStateData.Instance, properties: ['outputs'] }
                                    ]}
                                    control={() => {
                                        const isAvailable = action.isAvailable ? action.isAvailable() : true;

                                        return (
                                            <Button
                                                fullWidth
                                                variant="outlined"
                                                disabled={!isAvailable}
                                                sx={{
                                                    justifyContent: 'flex-start',
                                                    gap: 1.5,
                                                    py: 1.5,
                                                    px: 2,
                                                    minHeight: 44, // Touch-friendly minimum height
                                                    textTransform: 'none',
                                                    borderColor: 'divider',
                                                    color: 'inherit',
                                                    '&:hover': {
                                                        backgroundColor: 'action.hover',
                                                        borderColor: 'primary.main',
                                                    },
                                                }}
                                                onClick={() => isAvailable && registry.executeAction(action.id)}
                                            >
                                                {action.renderButton(true)}
                                            </Button>
                                        );
                                    }}
                                />
                            );
                        })}
                    </Box>
                );
            }}
        />
    );
}
