import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Machine Bed Tool Measurement Point Position
 * Conditional validation - only validates when machine bed tool measurement is enabled
 * Auto-validates that X,Y position is not at or very near 0,0
 */
export class MachineBedToolMeasurementPositionChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Machine Bed Tool Measurement Position',
            'Configure X, Y position for machine bed tool measurement point (must not be at 0,0)'
        );

        // Listen to MachineData changes that affect this checklist item
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['machineBedToolMeasurementPointEnabled', 'machineBedToolMeasurementPointX', 'machineBedToolMeasurementPointY']);
    }

    public shouldInclude(): boolean {
        return MachineData.Instance.machineBedToolMeasurementPointEnabled;
    }

    public needsManualConfirmation(): boolean {
        return false; // Auto-validation only
    }

    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // If machine bed tool measurement is not enabled, this item is N/A (considered complete)
        if (!machine.machineBedToolMeasurementPointEnabled) {
            return true;
        }

        // If enabled, validate that X,Y position is not at or very near 0,0
        const x = machine.machineBedToolMeasurementPointX;
        const y = machine.machineBedToolMeasurementPointY;

        // Check if both coordinates are significantly different from 0 (tolerance of 0.001)
        const tolerance = 0.001;
        const isNearZero = Math.abs(x) < tolerance && Math.abs(y) < tolerance;

        return !isNearZero;
    }

    public clone(): MachineBedToolMeasurementPositionChecklistItem {
        const cloned = new MachineBedToolMeasurementPositionChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
