import React from 'react';
import { StateManager } from './statemanager/StateManager';

/**
 * Generic modal interface
 */
export interface Modal {
  id: string;
  render(): React.ReactNode;
  onClose?(): void;
  priority?: number; // Higher priority modals show on top
}

/**
 * Generic modal manager singleton
 * Manages all modals in the application with priority support
 */
export class ModalManager {
  private static _instance: ModalManager;
  private _activeModals: Modal[] = [];

  public static get Instance(): ModalManager {
    if (!ModalManager._instance) {
      ModalManager._instance = new ModalManager();
    }
    return ModalManager._instance;
  }

  /**
   * Get all active modals sorted by priority (highest first)
   */
  public get activeModals(): Modal[] {
    return [...this._activeModals].sort((a, b) => (b.priority || 0) - (a.priority || 0));
  }

  /**
   * Get the top-most modal (highest priority)
   */
  public get topModal(): Modal | null {
    const sorted = this.activeModals;
    return sorted.length > 0 ? sorted[0] : null;
  }

  /**
   * Show a modal
   */
  public showModal(modal: Modal): void {
    // Remove existing modal with same ID if it exists
    this.closeModal(modal.id);

    // Add new modal
    this._activeModals.push(modal);

    // Notify observers
    StateManager.propertyChanged(this, 'activeModals');
  }

  /**
   * Close a specific modal by ID
   */
  public closeModal(id: string): void {
    const index = this._activeModals.findIndex(modal => modal.id === id);
    if (index >= 0) {
      const modal = this._activeModals[index];
      this._activeModals.splice(index, 1);
      
      // Call onClose callback if provided
      if (modal.onClose) {
        modal.onClose();
      }

      // Notify observers
      StateManager.propertyChanged(this, 'activeModals');
    }
  }

  /**
   * Close all modals
   */
  public closeAllModals(): void {
    const modalsToClose = [...this._activeModals];
    this._activeModals = [];

    // Call onClose callbacks
    modalsToClose.forEach(modal => {
      if (modal.onClose) {
        modal.onClose();
      }
    });

    // Notify observers
    StateManager.propertyChanged(this, 'activeModals');
  }

  /**
   * Check if a specific modal is active
   */
  public isModalActive(id: string): boolean {
    return this._activeModals.some(modal => modal.id === id);
  }
}
