import { Build as ToolIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { ToolSelectionDialog } from '../../components/Common/ToolSelectionDialog';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ModalManager } from '../ModalManager';
import { IUserAction } from './IUserAction';

export class ChangeToolUserAction implements IUserAction {
    public readonly id = 'home_page_change_tool';
    public readonly category = 'Machine Actions';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <ToolIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Change Tool
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <ToolIcon />
                    <Typography>Change Tool</Typography>
                </Box>
            );
        }
    }

    public run(): void {
        const modalId = 'tool-selection-dialog';
        ModalManager.Instance.showModal({
            id: modalId,
            render: () => <ToolSelectionDialog open onClose={() => ModalManager.Instance.closeModal(modalId)} />
        });
    }
}
