import { Close as CloseIcon, Straighten as MeasureIcon, BuildCircle as ReplaceToolIcon, Build as ToolIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, Typography } from '@mui/material';
import { useState } from 'react';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { Machine } from '../../machine/Machine';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { UserActionRegistry } from '../../utils/userActions/UserActionRegistry';
import { AxisCoordinateDisplay } from '../Common/AxisCoordinateDisplay';
import { MachineActionsPanel } from '../Common/MachineActionsPanel';
import { MessageViewer } from '../Common/MessageViewer';
import { SafeModeControl } from '../Common/SafeModeControl';
import { ClampEditorForm } from '../Views/ClampEditorForm';
import { MaterialEditor } from '../Views/MaterialEditor';

/**
 * Right sidebar containing Safe Mode, Coordinates, Messages, and Actions
 * Displayed to the right of the 1200px main content area
 */
export function RightSidebar() {
    const colors = ConfigurationDataColors.Instance;
    const machineState = MachineStateData.Instance;
    const [materialEditorOpen, setMaterialEditorOpen] = useState(false);
    const [clampEditorOpen, setClampEditorOpen] = useState(false);

    const handleReset = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.Reset();

            // Clear the requiresReset flag after successful reset (setter notifies observers)
            ConfigurationState.Instance.requiresReset = false;
        } catch (error) {
            console.error('Failed to trigger reset:', error);
        }
    };

    const handleEStop = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.EStop();
        } catch (error) {
            console.error('Failed to trigger E-stop:', error);
        }
    };

    const handleStop = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.Stop();
        } catch (error) {
            console.error('Failed to trigger stop:', error);
        }
    };

    const handleCancelCycle = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.CancelCycle();
        } catch (error) {
            console.error('Failed to cancel cycle:', error);
        }
    };

    const handleHomeMachine = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.HomeMachine();
        } catch (error) {
            console.error('Failed to home machine:', error);
        }
    };

    return (
        <Box
            sx={{
                width: '100%',
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: colors.lightBackgroundColor,
                borderLeft: `1px solid ${colors.borderColor}`,
                overflow: 'hidden',
            }}
        >
            {/* Machine Control Buttons - State-based dynamic buttons */}
            <Box sx={{ display: 'flex', gap: 2, px: 2, pt: 2, flexShrink: 0 }}>
                <ObserveMultiProperties
                    key="control-buttons-state"
                    listenTo={[
                        { object: ConfigurationState.Instance, properties: ['isJobRunning', 'isHomed', 'requiresReset'] }
                    ]}
                    control={() => {
                        const configState = ConfigurationState.Instance;
                        const isJobRunning = configState.isJobRunning;
                        const isHomed = configState.isHomed;
                        const requiresReset = configState.requiresReset;

                        // Determine which buttons to show based on state priority:
                        // 1. If reset needed: Reset + EStop
                        // 2. If job running: Cancel Cycle + EStop
                        // 3. If not homed: Home Machine + EStop
                        // 4. Otherwise: Stop + EStop

                        let primaryButton: { label: string; onClick: () => void; color: string } | null = null;

                        if (requiresReset) {
                            primaryButton = {
                                label: 'Reset',
                                onClick: handleReset,
                                color: colors.errorColor
                            };
                        } else if (isJobRunning) {
                            primaryButton = {
                                label: 'Cancel Cycle',
                                onClick: handleCancelCycle,
                                color: colors.darkBackgroundColor
                            };
                        } else if (!isHomed) {
                            primaryButton = {
                                label: 'Home Machine',
                                onClick: handleHomeMachine,
                                color: colors.successColor
                            };
                        } else {
                            // Default state: Stop + EStop
                            primaryButton = {
                                label: 'Stop',
                                onClick: handleStop,
                                color: colors.darkBackgroundColor
                            };
                        }

                        return (
                            <>
                                {primaryButton && (
                                    <Button
                                        variant="contained"
                                        sx={{
                                            flex: 1,
                                            height: '60px',
                                            fontSize: '1.25rem',
                                            fontWeight: 'bold',
                                            backgroundColor: requiresReset ? colors.lightTextColor : primaryButton.color,
                                            color: requiresReset ? colors.errorColor : colors.lightTextColor,
                                            border: requiresReset ? `3px solid ${colors.errorColor}` : 'none',
                                            '&:hover': {
                                                backgroundColor: requiresReset ? colors.lightTextColor : primaryButton.color,
                                                opacity: 0.9,
                                            }
                                        }}
                                        onClick={primaryButton.onClick}
                                    >
                                        {primaryButton.label}
                                    </Button>
                                )}
                                <Button
                                    variant="contained"
                                    sx={{
                                        flex: 1,
                                        height: '60px',
                                        fontSize: '1.25rem',
                                        fontWeight: 'bold',
                                        backgroundColor: colors.errorColor,
                                        color: colors.lightTextColor,
                                        '&:hover': {
                                            backgroundColor: colors.errorColor,
                                            opacity: 0.9,
                                        }
                                    }}
                                    onClick={handleEStop}
                                >
                                    EStop
                                </Button>
                            </>
                        );
                    }}
                />
            </Box>
            {/* Current Tool Section */}
            <ObserveMultiProperties
                key="current-tool-display"
                listenTo={[
                    { object: machineState, properties: ['currentToolNumber'] },
                    { object: ConfigurationState.Instance, properties: ['isHomed'] }
                ]}
                control={() => {
                    const colors = ConfigurationDataColors.Instance;
                    const toolLibrary = ToolLibrary.Instance;
                    const currentToolNumber = machineState.currentToolNumber;
                    const tool = toolLibrary.tools.find(t => t.toolNumber === currentToolNumber);
                    const toolLabel = tool ? `T${(tool.toolNumber ?? 0).toString().padStart(2, '0')} - ${tool.displayName}` : 'No Tool Loaded';
                    const isHomed = ConfigurationState.Instance.isHomed;

                    const handleChangeTool = async () => {
                        const action = await UserActionRegistry.Instance.getAction('home_page_change_tool');
                        if (action) {
                            action.run();
                        }
                    };

                    const handleReplaceToolBit = async () => {
                        const action = await UserActionRegistry.Instance.getAction('replace_tool_wizard');
                        if (action) {
                            action.run();
                        }
                    };

                    const handleMeasureTool = async () => {
                        const action = await UserActionRegistry.Instance.getAction('tool_management_measure_tool');
                        if (action) {
                            action.run();
                        }
                    };

                    return (
                        <Box sx={{
                            mx: 2,
                            mt: 2,
                            p: 2,
                            borderRadius: 1,
                            backgroundColor: colors.lightBackgroundColor,
                            border: `2px solid ${colors.primaryColor}`
                        }}>
                            <Box sx={{ display: 'flex', alignItems: 'baseline', mb: 2, gap: 1 }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: colors.primaryColor, flexShrink: 0 }}>
                                    Current Tool:
                                </Typography>
                                <Typography variant="body1" sx={{ fontWeight: 'bold', fontFamily: 'monospace' }}>
                                    {toolLabel}
                                </Typography>
                            </Box>
                            <Box sx={{ display: 'flex', gap: 1 }}>
                                <Button
                                    variant="outlined"
                                    size="small"
                                    startIcon={<ToolIcon />}
                                    onClick={handleChangeTool}
                                    disabled={!isHomed}
                                    sx={{
                                        flex: 1,
                                        textTransform: 'none',
                                        borderColor: colors.primaryColor,
                                        color: colors.primaryColor,
                                        '&:hover': {
                                            borderColor: colors.primaryColor,
                                            backgroundColor: `${colors.primaryColor}15`
                                        }
                                    }}
                                >
                                    Change
                                </Button>
                                <Button
                                    variant="outlined"
                                    size="small"
                                    startIcon={<ReplaceToolIcon />}
                                    onClick={handleReplaceToolBit}
                                    disabled={!isHomed}
                                    sx={{
                                        flex: 1,
                                        textTransform: 'none',
                                        borderColor: colors.primaryColor,
                                        color: colors.primaryColor,
                                        '&:hover': {
                                            borderColor: colors.primaryColor,
                                            backgroundColor: `${colors.primaryColor}15`
                                        }
                                    }}
                                >
                                    Replace
                                </Button>
                                <Button
                                    variant="outlined"
                                    size="small"
                                    startIcon={<MeasureIcon />}
                                    onClick={handleMeasureTool}
                                    disabled={!isHomed}
                                    sx={{
                                        flex: 1,
                                        textTransform: 'none',
                                        borderColor: colors.primaryColor,
                                        color: colors.primaryColor,
                                        '&:hover': {
                                            borderColor: colors.primaryColor,
                                            backgroundColor: `${colors.primaryColor}15`
                                        }
                                    }}
                                >
                                    Measure
                                </Button>
                            </Box>
                        </Box>
                    );
                }}
            />
            {/* Top Section: Coordinates and Actions side by side */}
            <Box sx={{ display: 'flex', gap: 2, px: 2, pt: 2, flexShrink: 0 }}>
                {/* Coordinates */}
                <Box sx={{ flex: 1 }}>
                    <AxisCoordinateDisplay
                        axes={['X', 'Y', 'Z', 'A']}
                        showButtons={true}
                        showSpeedToggle={true}
                        showCoordinateTypeToggle={true}
                        instanceKey="right-sidebar-axis-display"
                    />
                </Box>

                {/* Actions Panel */}
                <Box sx={{ flexShrink: 0 }}>
                    <MachineActionsPanel
                        onEditMaterial={() => setMaterialEditorOpen(true)}
                        onEditClamps={() => setClampEditorOpen(true)}
                    />
                </Box>
            </Box>

            {/* Safe Mode Control */}
            <Box sx={{ px: 2, pt: 2, flexShrink: 0 }}>
                <SafeModeControl />
            </Box>

            {/* Messages - Scrollable */}
            <Box sx={{ flex: 1, minHeight: 0, overflow: 'hidden', mx: 2, my: 2 }}>
                <MessageViewer />
            </Box>

            {/* Material Editor Dialog */}
            <MaterialEditor
                open={materialEditorOpen}
                onClose={() => setMaterialEditorOpen(false)}
                machineState={machineState}
            />

            {/* Clamp Editor Dialog */}
            <Dialog
                open={clampEditorOpen}
                onClose={() => setClampEditorOpen(false)}
                maxWidth="lg"
                fullWidth
                PaperProps={{
                    sx: { height: '80vh' }
                }}
            >
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}>
                    Clamp Setup
                    <IconButton
                        onClick={() => setClampEditorOpen(false)}
                        sx={{
                            color: colors.lightTextColor,
                            '&:hover': {
                                backgroundColor: colors.lightOverlay
                            }
                        }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent sx={{ height: 'calc(100% - 120px)', overflow: 'auto' }}>
                    <ClampEditorForm
                        onSaveToLibrary={() => {
                            // Save to library implementation
                        }}
                        onLoadFromLibrary={() => {
                            // Load from library implementation
                        }}
                        height="100%"
                    />
                </DialogContent>
                <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                    <Button
                        onClick={() => setClampEditorOpen(false)}
                        variant="contained"
                        sx={{
                            backgroundColor: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: colors.primaryColor,
                                filter: 'brightness(0.9)'
                            }
                        }}
                    >
                        Done
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}
