import { Error as ErrorIcon, ExpandMore as ExpandMoreIcon, Warning as WarningIcon } from '@mui/icons-material';
import { Box, Collapse, Link, Tooltip, Typography } from '@mui/material';
import { useState } from 'react';
import { SystemIcons } from '../../SystemIcons';
import { IPLCElement, PLCValidationIssue, ValidationSeverity } from '../../centroid/plc/data/IPLCElement';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface PLCValidationIndicatorProps {
    /** The PLC element to validate and monitor */
    element: IPLCElement;
    /** Optional: Show count of issues instead of just icon */
    showCount?: boolean;
    /** Optional: Custom styling */
    sx?: any;
}

/**
 * Get human-readable location hierarchy for a validation issue
 * Returns an array of location parts from top to bottom (stage → block → statement)
 */
function getIssueLocationParts(issue: PLCValidationIssue): string[] {
    const element = issue.element;
    const elementType = element.getElementType();
    const parts: string[] = [];

    if (elementType === 'program') {
        const programType = (element as any).getProgramType?.() || 'Unknown';
        parts.push(programType === 0 ? 'System Default PLC' : 'System PLC');
        return parts;
    }

    if (elementType === 'stage') {
        const stageName = (element as any).name || 'Unknown Stage';
        parts.push(`Stage: ${stageName}`);
        return parts;
    }

    if (elementType === 'block') {
        const blockName = (element as any).name || 'Unknown Block';
        const parent = element.getParentElement();
        const stageName = parent && 'name' in parent ? (parent as any).name : 'Unknown Stage';
        parts.push(`Stage: ${stageName}`);
        parts.push(`Block: ${blockName}`);
        return parts;
    }

    if (elementType === 'statement' || elementType === 'condition' || elementType === 'condition-group' || elementType === 'predicate') {
        // Walk up to find block and stage
        let currentElement: IPLCElement | undefined = element;
        const hierarchy: string[] = [];

        while (currentElement) {
            const type = currentElement.getElementType();

            if (type === 'statement') {
                const statementType = (currentElement as any).constructor?.name || 'Statement';
                hierarchy.unshift(statementType);
            } else if (type === 'block') {
                const blockName = (currentElement as any).name || 'Unknown Block';
                hierarchy.unshift(`Block: ${blockName}`);
            } else if (type === 'stage') {
                const stageName = (currentElement as any).name || 'Unknown Stage';
                hierarchy.unshift(`Stage: ${stageName}`);
                break; // Stop at stage level
            }

            currentElement = currentElement.getParentElement();
        }

        return hierarchy;
    }

    return ['Unknown Location'];
}

/**
 * Parse location parts from message and return clean message and location parts
 * Extracts [xxx] prefixes from the message and treats them as location context
 */
function parseMessageAndLocation(message: string): { cleanMessage: string; contextParts: string[] } {
    const contextParts: string[] = [];
    let cleanMessage = message;

    // Extract all [xxx] parts from the beginning of the message
    const bracketRegex = /^\[([^\]]+)\]\s*/;
    let match = cleanMessage.match(bracketRegex);

    while (match) {
        contextParts.push(match[1]);
        cleanMessage = cleanMessage.substring(match[0].length);
        match = cleanMessage.match(bracketRegex);
    }

    return { cleanMessage, contextParts };
}

/**
 * ValidationIssueItem component - displays a single validation issue with expandable location
 */
function ValidationIssueItem({ issue, index }: { issue: PLCValidationIssue; index: number }) {
    const [expanded, setExpanded] = useState(false);
    const { cleanMessage, contextParts } = parseMessageAndLocation(issue.message);
    const colors = ConfigurationDataColors.Instance;

    // Use parsed context parts from message if available, otherwise fall back to element hierarchy
    const locationParts = contextParts.length > 0 ? contextParts : getIssueLocationParts(issue);
    const isError = issue.severity === ValidationSeverity.Error;

    return (
        <Box
            sx={{
                mb: 1,
                p: 1.5,
                border: `1px solid ${isError ? colors.errorColor : colors.warningColor}`,
                borderRadius: 1,
                backgroundColor: isError ? `${colors.errorColor}20` : `${colors.warningColor}20`
            }}
        >
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                <Box sx={{ color: isError ? colors.errorColor : colors.warningColor, mt: 0.25, flexShrink: 0 }}>
                    {isError ? <ErrorIcon fontSize="small" /> : <WarningIcon fontSize="small" />}
                </Box>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography
                        variant="body2"
                        sx={{
                            color: colors.darkTextColor,
                            fontWeight: 500,
                            mb: 0.5,
                            wordBreak: 'break-word'
                        }}
                    >
                        {cleanMessage}
                    </Typography>
                    {locationParts.length > 0 && (
                        <>
                            <Link
                                component="button"
                                variant="caption"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    e.preventDefault();
                                    setExpanded(!expanded);
                                }}
                                sx={{
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    gap: 0.5,
                                    color: colors.mutedTextColor,
                                    textDecoration: 'none',
                                    cursor: 'pointer',
                                    fontSize: '0.75rem',
                                    '&:hover': {
                                        color: colors.darkTextColor,
                                        textDecoration: 'underline'
                                    }
                                }}
                            >
                                <ExpandMoreIcon
                                    fontSize="small"
                                    sx={{
                                        transform: expanded ? 'rotate(180deg)' : 'rotate(0deg)',
                                        transition: 'transform 0.2s',
                                        fontSize: '1rem'
                                    }}
                                />
                                {expanded ? 'Hide' : 'Show'} location ({locationParts.length})
                            </Link>
                            <Collapse in={expanded}>
                                <Box sx={{ mt: 1, pl: 1.5, borderLeft: `2px solid ${colors.borderColor}` }}>
                                    {locationParts.map((part, idx) => (
                                        <Typography
                                            key={idx}
                                            variant="caption"
                                            sx={{
                                                display: 'block',
                                                color: colors.mutedTextColor,
                                                pl: idx * 1.5,
                                                py: 0.25,
                                                fontFamily: 'monospace',
                                                fontSize: '0.7rem'
                                            }}
                                        >
                                            {idx + 1}. {part}
                                        </Typography>
                                    ))}
                                </Box>
                            </Collapse>
                        </>
                    )}
                </Box>
            </Box>
        </Box>
    );
}

/**
 * PLCValidationIndicator Component
 * 
 * Displays validation status for a PLC element with reactive updates.
 * Shows a red warning triangle icon when validation issues exist, with a tooltip
 * listing all issues. Optionally displays the count of issues.
 * 
 * Features:
 * - Reactive updates via ObserveState listening to the element
 * - Red warning triangle icon for visibility
 * - Tooltip showing all validation messages
 * - Optional count display for aggregate views
 * - Configurable styling
 * 
 * Usage:
 * ```tsx
 * // Simple indicator on a statement
 * <PLCValidationIndicator element={statement} />
 * 
 * // With count for block/stage headers
 * <PLCValidationIndicator element={block} showCount={true} />
 * ```
 */
export function PLCValidationIndicator(props: PLCValidationIndicatorProps) {
    const { element, showCount = false, sx = {} } = props;

    return (
        <ObserveState
            key={`validation-${element.getElementId()}`}
            listenTo={element}
            control={() => {
                const colors = ConfigurationDataColors.Instance;
                const issues = element.getValidationIssues();

                if (issues.length === 0) {
                    return null;
                }

                // Determine if we have errors and/or warnings
                const hasErrors = issues.some(issue => issue.severity === ValidationSeverity.Error);
                const hasWarnings = issues.some(issue => issue.severity === ValidationSeverity.Warning);
                const errors = issues.filter(issue => issue.severity === ValidationSeverity.Error);
                const warnings = issues.filter(issue => issue.severity === ValidationSeverity.Warning);
                const errorCount = errors.length;
                const warningCount = warnings.length;

                // Build tooltip content for errors
                const buildTooltipContent = (issueList: PLCValidationIssue[], title: string) => (
                    <Box sx={{
                        maxWidth: 500,
                        minWidth: 350,
                        backgroundColor: colors.lightTextColor,
                        borderRadius: 1,
                        boxShadow: `0 4px 20px ${colors.shadowColor}`
                    }}>
                        <Box sx={{
                            p: 2,
                            borderBottom: `1px solid ${colors.borderColor}`,
                            backgroundColor: colors.lightBackgroundColor
                        }}>
                            <Typography
                                variant="subtitle2"
                                sx={{
                                    fontWeight: 600,
                                    fontSize: '0.9rem',
                                    color: colors.darkTextColor
                                }}
                            >
                                {title} ({issueList.length})
                            </Typography>
                        </Box>
                        <Box sx={{
                            p: 2,
                            maxHeight: 400,
                            overflowY: 'auto',
                            '&::-webkit-scrollbar': {
                                width: '8px'
                            },
                            '&::-webkit-scrollbar-track': {
                                backgroundColor: colors.lightBackgroundColor,
                                borderRadius: '4px'
                            },
                            '&::-webkit-scrollbar-thumb': {
                                backgroundColor: colors.secondaryBorderColor,
                                borderRadius: '4px',
                                '&:hover': {
                                    backgroundColor: colors.mutedTextColor
                                }
                            }
                        }}>
                            {issueList.map((issue, index) => (
                                <ValidationIssueItem key={index} issue={issue} index={index} />
                            ))}
                        </Box>
                    </Box>
                );

                return (
                    <Box
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 0.5,
                            ...sx
                        }}
                    >
                        {hasErrors && (
                            <Tooltip
                                title={buildTooltipContent(errors, 'Errors')}
                                arrow
                                placement="top"
                                disableInteractive={false}
                                componentsProps={{
                                    tooltip: {
                                        sx: {
                                            backgroundColor: 'transparent',
                                            padding: 0,
                                            maxWidth: 'none',
                                            pointerEvents: 'auto'
                                        }
                                    },
                                    arrow: {
                                        sx: {
                                            color: colors.lightTextColor
                                        }
                                    }
                                }}
                            >
                                <Box sx={{ color: colors.errorColor, display: 'flex', alignItems: 'center', gap: 0.5, cursor: 'help' }}>
                                    {SystemIcons.warning}
                                    {showCount && (
                                        <Typography
                                            variant="caption"
                                            sx={{
                                                fontWeight: 'bold',
                                                color: colors.errorColor
                                            }}
                                        >
                                            {errorCount}
                                        </Typography>
                                    )}
                                </Box>
                            </Tooltip>
                        )}
                        {hasWarnings && (
                            <Tooltip
                                title={buildTooltipContent(warnings, 'Warnings')}
                                arrow
                                placement="top"
                                disableInteractive={false}
                                componentsProps={{
                                    tooltip: {
                                        sx: {
                                            backgroundColor: 'transparent',
                                            padding: 0,
                                            maxWidth: 'none',
                                            pointerEvents: 'auto'
                                        }
                                    },
                                    arrow: {
                                        sx: {
                                            color: colors.lightTextColor
                                        }
                                    }
                                }}
                            >
                                <Box sx={{ color: colors.warningColor, display: 'flex', alignItems: 'center', gap: 0.5, cursor: 'help' }}>
                                    {SystemIcons.warning}
                                    {showCount && (
                                        <Typography
                                            variant="caption"
                                            sx={{
                                                fontWeight: 'bold',
                                                color: colors.warningColor
                                            }}
                                        >
                                            {warningCount}
                                        </Typography>
                                    )}
                                </Box>
                            </Tooltip>
                        )}
                    </Box>
                );
            }}
        />
    );
}

/**
 * Get the total count of validation issues for an element and all its children
 * This is useful for displaying aggregate counts at block and stage levels
 */
export function getValidationIssueCount(element: IPLCElement): number {
    return element.getValidationIssues().length;
}
