import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { ConfirmDimensionsStep } from "./steps/ConfirmDimensionsStep";

export interface SurfaceSpoilboardState {
    selectedToolNumber: number;
    spindleSpeed: number;
    stepover: number;
    amountToRemove: number;
    cornerX: number;
    cornerY: number;
    cornerZ: number;
    spoilboardWidth: number;
    spoilboardLength: number;
    isRunning: boolean;
}

export class SurfaceSpoilboardWizard extends Wizard<SurfaceSpoilboardState> {
    constructor() {
        const initialState: SurfaceSpoilboardState = {
            selectedToolNumber: 0,
            spindleSpeed: 18000,
            stepover: 0.5,
            amountToRemove: 0.02,
            cornerX: 0,
            cornerY: 0,
            cornerZ: 0,
            spoilboardWidth: 0,
            spoilboardLength: 0,
            isRunning: false
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose
            '80%', // width
            '85%'  // height
        );

        // Create the first step with proper wizard reference
        const firstStep = new ConfirmDimensionsStep(this, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    static show(): void {
        const wizard = new SurfaceSpoilboardWizard();
        WizardManager.Instance.start(wizard);
    }
}
