import {
    Box,
    CircularProgress,
    Paper,
    Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ConfigurationState } from '../data/ConfigurationState';
import { ObserveState } from '../utils/statemanager/ObserveState';

/**
 * ConnectionOverlay displays over the UI when server connection is lost
 * Only shows when isConnected is false (lost connectivity to server)
 * Uses ObserveState to reactively show/hide based on ConfigurationState.isConnected
 */
export function ConnectionOverlay() {
    return (
        <ObserveState
            key="connection-overlay-observer"
            listenTo={ConfigurationState.Instance}
            properties={['isConnected']}
            control={() => {
                const configState = ConfigurationState.Instance;
                const colors = ConfigurationDataColors.Instance;

                // Only show overlay when we've lost connectivity to the server
                if (configState.isConnected) {
                    return null;
                }

                // Show overlay when disconnected from server
                return (
                    <Box
                        sx={{
                            position: 'fixed',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            backgroundColor: colors.darkOverlay,
                            zIndex: 9999, // Above everything else
                            padding: 3
                        }}
                    >
                        <Paper
                            elevation={8}
                            sx={{
                                padding: 6,
                                borderRadius: 4,
                                textAlign: 'center',
                                maxWidth: 500,
                                width: '100%',
                                backgroundColor: colors.darkBackgroundColor,
                                color: colors.lightTextColor,
                                border: `2px solid ${colors.errorColor}`
                            }}
                        >
                            {/* Warning Icon/Title */}
                            <Typography
                                variant="h3"
                                component="h1"
                                gutterBottom
                                sx={{
                                    color: colors.errorColor,
                                    fontWeight: 'bold',
                                    marginBottom: 3
                                }}
                            >
                                Connection Lost
                            </Typography>

                            {/* Loading Spinner */}
                            <CircularProgress
                                size={60}
                                sx={{
                                    color: colors.errorColor,
                                    marginBottom: 3
                                }}
                            />

                            {/* Connection Status */}
                            <Typography
                                variant="h6"
                                sx={{
                                    color: colors.lightTextColor,
                                    marginBottom: 1
                                }}
                            >
                                Waiting for Connection...
                            </Typography>

                            <Typography
                                variant="body2"
                                sx={{
                                    color: colors.mutedTextColor,
                                    marginBottom: 2
                                }}
                            >
                                The connection to the server has been lost.
                                <br />
                                Attempting to reconnect...
                            </Typography>

                            {/* Info Box */}
                            <Box
                                sx={{
                                    backgroundColor: `${colors.lightTextColor}1A`,
                                    borderRadius: 2,
                                    padding: 2,
                                    marginTop: 3
                                }}
                            >
                                <Typography
                                    variant="caption"
                                    sx={{
                                        color: colors.mutedTextColor,
                                        fontStyle: 'italic'
                                    }}
                                >
                                    Please check:
                                    <br />
                                    • Network connection to server
                                    <br />
                                    • CNC server software is running
                                    <br />
                                    • SignalR connection is active
                                </Typography>
                            </Box>
                        </Paper>
                    </Box>
                );
            }}
        />
    );
}
