import { Grid, Typography } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function BaseSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-width"
                    listenTo={machine}
                    properties={['baseWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Base Width"
                            value={machine.baseWidth}
                            onChange={(value) => machine.baseWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-length"
                    listenTo={machine}
                    properties={['baseLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Base Length"
                            value={machine.baseLength}
                            onChange={(value) => machine.baseLength = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-height"
                    listenTo={machine}
                    properties={['baseHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Base Height"
                            value={machine.baseHeight}
                            onChange={(value) => machine.baseHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Machine Base Position from Machine Zero */}
            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>
                    Machine Base Position (Machine Zero Coordinates)
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    X, Y, and Z coordinates of the machine base corner in Machine Zero coordinate system
                </Typography>
            </Grid>

            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-corner-x"
                    listenTo={machine}
                    properties={['machineBaseTopCornerFromMachineZeroX']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Machine Base X"
                            value={machine.machineBaseTopCornerFromMachineZeroX}
                            onChange={(value) => machine.machineBaseTopCornerFromMachineZeroX = value}
                            margin="normal"
                            precision={1}
                            helperText="X coordinate of machine base corner"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-corner-y"
                    listenTo={machine}
                    properties={['machineBaseTopCornerFromMachineZeroY']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Machine Base Y"
                            value={machine.machineBaseTopCornerFromMachineZeroY}
                            onChange={(value) => machine.machineBaseTopCornerFromMachineZeroY = value}
                            margin="normal"
                            precision={1}
                            helperText="Y coordinate of machine base corner"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="base-corner-z"
                    listenTo={machine}
                    properties={['machineBaseTopCornerFromMachineZeroZ']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Machine Base Z"
                            value={machine.machineBaseTopCornerFromMachineZeroZ}
                            onChange={(value) => machine.machineBaseTopCornerFromMachineZeroZ = value}
                            margin="normal"
                            precision={1}
                            helperText="Z coordinate of machine base corner"
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
