import { AxisType } from "../../../data/Machine/AxisType";
import { MachineData } from "../../../data/Machine/MachineData";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { StartingPositionStep } from "./steps/StartingPositionStep";

/**
 * State for the axis calibration wizard
 */
export interface AxisCalibrationState {
    selectedAxis: AxisType | null;
    startingPosition: number;
    commandedDistance: number;
    actualDistance: number | null;
    currentStepsPerInch: number;
    newStepsPerInch: number | null;
}

/**
 * Wizard for calibrating X, Y, or Z axis steps per inch
 * Guides user through measuring actual travel distance and calculating corrections
 */
export class AxisCalibrationWizard extends Wizard<AxisCalibrationState> {
    constructor(axis: AxisType) {
        // Get current steps per inch for the selected axis
        const axisConfig = MachineData.Instance.axisConfigurations.find(a => a.axisType === axis);
        const currentStepsPerInch = axisConfig
            ? axisConfig.stepsPerRevolution * axisConfig.overallTurnsRatio
            : 0;

        const initialState: AxisCalibrationState = {
            selectedAxis: axis,
            startingPosition: 0,
            commandedDistance: 10, // Default 10 inch test distance
            actualDistance: null,
            currentStepsPerInch,
            newStepsPerInch: null
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during calibration
            '80%', // width
            '85%' // height
        );

        // Always start with StartingPositionStep - axis must be pre-selected
        if (!axis) {
            throw new Error('AxisCalibrationWizard requires a pre-selected axis');
        }
        const firstStep = new StartingPositionStep(this, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    /**
     * Override closeWizard to clean up any state
     */
    closeWizard(): void {
        super.closeWizard();
    }

    /**
     * Show the axis calibration wizard
     * @param axis Required axis to calibrate (X, Y, or Z)
     */
    static show(axis: AxisType): void {
        const wizard = new AxisCalibrationWizard(axis);
        WizardManager.Instance.start(wizard);
    }
}
