import { Box, Slider, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

interface SpindleSpeedControlProps {
    /**
     * Current spindle speed override percentage (10-200)
     */
    value: number;
    
    /**
     * Callback when spindle speed changes
     */
    onChange: (value: number) => void;
    
    /**
     * Whether the control is disabled
     */
    disabled?: boolean;
}

/**
 * Spindle speed control component with vertical slider
 * Allows adjustment of spindle speed override from 10% to 200%
 */
export function SpindleSpeedControl({ value, onChange, disabled = false }: SpindleSpeedControlProps) {
    const colors = ConfigurationDataColors.Instance;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', height: '100%' }}>
            <Typography variant="caption" gutterBottom fontWeight="bold" sx={{ mb: 1 }}>
                Spindle Speed
            </Typography>
            <Typography variant="h6" fontWeight="bold" sx={{ color: colors.primaryColor, mb: 2 }}>
                {value}%
            </Typography>
            <Slider
                orientation="vertical"
                value={value}
                onChange={(_, newValue) => onChange(newValue as number)}
                min={10}
                max={200}
                step={5}
                marks={[
                    { value: 50, label: '' },
                    { value: 100, label: '' },
                    { value: 150, label: '' },
                    { value: 200, label: '' }
                ]}
                valueLabelDisplay="auto"
                disabled={disabled}
                sx={{
                    flex: 1,
                    minHeight: 200,
                    '& .MuiSlider-thumb': {
                        backgroundColor: colors.primaryColor
                    },
                    '& .MuiSlider-track': {
                        backgroundColor: colors.primaryColor
                    },
                    '& .MuiSlider-rail': {
                        backgroundColor: colors.borderColor
                    }
                }}
            />
        </Box>
    );
}
