import { Box, Button, Typography } from '@mui/material';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { DraggableDialog } from './DraggableDialog';

interface SetWorkZeroDialogProps {
    onClose: () => void;
}

/**
 * Dialog content for Go to Work Zero functionality
 * Quick navigation buttons to work zero position at various Z heights
 */
export function SetWorkZeroDialog({ onClose }: SetWorkZeroDialogProps) {
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    const handleGoToWorkZero = (x: number, y: number, z: number) => {
        // Create work coordinate point with offsets (includes tool length)
        const workPoint = new CNCPoint(x, y, z, CoordinateType.WorkZeroWithOffsets);

        // Convert to machine coordinates for the move action
        const machinePoint = CoordinateUtil.toMachineZero(workPoint);

        // Add move action to queue
        const moveAction = MoveAction.fromCNCPoint(machinePoint, MoveType.Coordinates);
        ActionBus.Instance.addAction(moveAction);
    };

    return (
        <DraggableDialog
            open={true}
            onClose={onClose}
            title="Go to Work Zero"
            maxWidth="md"
            fullWidth
        >
            {/* Content */}
            <Box sx={{ flex: 1, p: 3, overflow: 'auto' }}>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <Typography variant="body1" color="text.secondary">
                        Navigate to work zero position (X=0, Y=0) at different Z heights:
                    </Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                        {/* Go to XY - Z Max */}
                        <Button
                            variant="contained"
                            onClick={() => {
                                const zMax = CoordinateUtil.getZMax(CoordinateType.WorkZero);
                                handleGoToWorkZero(0, 0, zMax);
                            }}
                            sx={{
                                justifyContent: 'flex-start',
                                py: 2,
                                fontSize: '1rem',
                                backgroundColor: colors.primaryColor,
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9
                                }
                            }}
                        >
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '100%' }}>
                                <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                    Go to XY - Z Max (Safe Height)
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.9 }}>
                                    Position at maximum Z height
                                </Typography>
                            </Box>
                        </Button>

                        {/* Go to XY, Z+1 */}
                        <Button
                            variant="contained"
                            onClick={() => handleGoToWorkZero(0, 0, 1)}
                            sx={{
                                justifyContent: 'flex-start',
                                py: 2,
                                fontSize: '1rem',
                                backgroundColor: colors.primaryColor,
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9
                                }
                            }}
                        >
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '100%' }}>
                                <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                    Go to XY, Z+1.0
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.9 }}>
                                    Position 1 inch above work zero
                                </Typography>
                            </Box>
                        </Button>

                        {/* Go to XY, Z+0.5 */}
                        <Button
                            variant="contained"
                            onClick={() => handleGoToWorkZero(0, 0, 0.5)}
                            sx={{
                                justifyContent: 'flex-start',
                                py: 2,
                                fontSize: '1rem',
                                backgroundColor: colors.primaryColor,
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9
                                }
                            }}
                        >
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '100%' }}>
                                <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                    Go to XY, Z+0.5
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.9 }}>
                                    Position 0.5 inches above work zero
                                </Typography>
                            </Box>
                        </Button>

                        {/* Go to XY, Z+0.1 */}
                        <Button
                            variant="contained"
                            onClick={() => handleGoToWorkZero(0, 0, 0.1)}
                            sx={{
                                justifyContent: 'flex-start',
                                py: 2,
                                fontSize: '1rem',
                                backgroundColor: colors.primaryColor,
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9
                                }
                            }}
                        >
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '100%' }}>
                                <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                    Go to XY, Z+0.1
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.9 }}>
                                    Position 0.1 inches above work zero
                                </Typography>
                            </Box>
                        </Button>

                        {/* Go to XYZ (exact work zero) */}
                        <Button
                            variant="contained"
                            onClick={() => handleGoToWorkZero(0, 0, 0)}
                            sx={{
                                justifyContent: 'flex-start',
                                py: 2,
                                fontSize: '1rem',
                                backgroundColor: colors.warningColor,
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: colors.warningColor,
                                    opacity: 0.9
                                }
                            }}
                        >
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '100%' }}>
                                <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                    Go to XYZ (Work Zero)
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.9 }}>
                                    ⚠️ Move to exact work zero position - use with caution
                                </Typography>
                            </Box>
                        </Button>
                    </Box>
                </Box>
            </Box>

            {/* Done Button */}
            <Box sx={{
                borderTop: `1px solid ${colors.borderColor}`,
                p: 2,
                display: 'flex',
                justifyContent: 'flex-end'
            }}>
                <Button
                    variant="contained"
                    onClick={onClose}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Done
                </Button>
            </Box>
        </DraggableDialog>
    );
}
