import { HomeWork as UnhomeIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../Logger';
import { IUserAction } from './IUserAction';

export class UnhomeMachineUserAction implements IUserAction {
    public readonly id = 'unhome_machine';
    public readonly category = 'Machine Actions';
    public readonly isDefaultHomeAction = false;

    public isAvailable(): boolean {
        // Unhome Machine is always available
        return true;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <UnhomeIcon sx={{ fontSize: 18, color: 'warning.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Unhome Machine
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <UnhomeIcon />
                    <Typography>Unhome Machine</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        try {
            const machine = Machine.getInstance();
            await machine.system.MachineUnhomed();
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to unhome machine:', error);
        }
    }
}
