import { StateManager } from '../../utils/statemanager/StateManager';
import { ConfigurationData } from '../ConfigurationData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item to verify test mode (G-code preview) is turned off
 * This ensures the machine is ready for production use without preview dialogs
 */
export class TestModeOffChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Turn Off Test Mode',
            'Disable G-Code preview for production use'
        );

        // Listen to ConfigurationData previewGCode changes
        StateManager.addObserver(
            ConfigurationData.Instance,
            () => {
                // Notify that this item's completion status may have changed
                StateManager.propertyChanged(this, 'manuallyConfirmed');
            },
            ['previewGCode'],
            'TestModeOffChecklistItem'
        );
    }

    /**
     * This item does not require manual confirmation - auto-clears when disabled
     */
    public needsManualConfirmation(): boolean {
        return false;
    }

    /**
     * Check if G-code preview (test mode) is disabled
     */
    public completionCheck(): boolean {
        return !ConfigurationData.Instance.previewGCode;
    }

    /**
     * Create a deep copy of this checklist item
     */
    public clone(): SetupChecklistItem {
        const cloned = new TestModeOffChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
