import { BufferGeometry, BufferAttribute } from 'three';
import { LinePoint } from './LinePoint';

/**
 * Creates simple line geometry for CNC toolpaths
 */
export class ToolpathGeometry extends BufferGeometry {
  private points: LinePoint[] = [];

  /**
   * Add line points to build the line geometry
   */
  public addPoints(linePoints: LinePoint[]): void {
    this.points = [...linePoints];
    this.buildGeometry();
  }

  /**
   * Clear all points and rebuild
   */
  public clear(): void {
    this.points = [];
    this.buildGeometry();
  }

  /**
   * Build line geometry from line points
   */
  private buildGeometry(): void {
    if (this.points.length < 2) {
      // Not enough points to create geometry
      this.setIndex(new BufferAttribute(new Uint16Array([]), 1));
      this.setAttribute('position', new BufferAttribute(new Float32Array([]), 3));
      this.setAttribute('color', new BufferAttribute(new Float32Array([]), 3));
      return;
    }

    const positions: number[] = [];
    const colors: number[] = [];

    // Create line segments between consecutive points
    for (let i = 0; i < this.points.length - 1; i++) {
      const startPoint = this.points[i];
      const endPoint = this.points[i + 1];
      
      // Add start position
      positions.push(startPoint.position.x, startPoint.position.y, startPoint.position.z);
      colors.push(startPoint.color.r, startPoint.color.g, startPoint.color.b);
      
      // Add end position
      positions.push(endPoint.position.x, endPoint.position.y, endPoint.position.z);
      colors.push(endPoint.color.r, endPoint.color.g, endPoint.color.b);
    }

    // Set geometry attributes
    this.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
    this.setAttribute('color', new BufferAttribute(new Float32Array(colors), 3));

    this.computeBoundingSphere();
  }
}
