import { StateManager } from './statemanager/StateManager';

/**
 * Log levels for different types of messages
 */
export enum LogLevel {
  Debug = 'debug',
  Info = 'info',
  Error = 'error'
}

/**
 * Common log categories used throughout the application
 */
export enum LogCategory {
  System = 'System',
  DataManager = 'DataManager',
  StateManager = 'StateManager',
  UserInterface = 'UserInterface',
  ThreeJS = 'ThreeJS',
  Collision = 'Collision',
  Coordinates = 'Coordinates',
  Tools = 'Tools',
  Materials = 'Materials',
  Fixtures = 'Fixtures',
  Clamps = 'Clamps',
  Machine = 'Machine',
  Network = 'Network',
  FileSystem = 'FileSystem',
  Validation = 'Validation'
}

/**
 * A single log entry
 */
export interface LogEntry {
  id: string;
  timestamp: Date;
  level: LogLevel;
  category: string;
  message: string;
}

/**
 * Configuration for logging behavior
 */
export interface LogConfiguration {
  enabledLevels: Set<LogLevel>;
  enabledCategories: Set<string>;
  outputToConsole: boolean;
  maxLogEntries: number;
}

/**
 * Centralized logging system for HavenCNC
 * Provides structured logging with categories, levels, and filtering
 */
export class Logger {
  private static _instance: Logger;
  private _logEntries: LogEntry[] = [];
  private _configuration: LogConfiguration;
  private _usedCategories: Set<string> = new Set();

  private constructor() {
    this._configuration = {
      enabledLevels: new Set([LogLevel.Info, LogLevel.Error]), // Debug disabled by default
      enabledCategories: new Set(Object.values(LogCategory)),
      outputToConsole: false, // Console output disabled by default
      maxLogEntries: 1500
    };

    // Initialize with predefined categories
    Object.values(LogCategory).forEach(category => {
      this._usedCategories.add(category);
    });
  }

  public static get Instance(): Logger {
    if (!Logger._instance) {
      Logger._instance = new Logger();
    }
    return Logger._instance;
  }

  /**
   * Get current log configuration
   */
  public get configuration(): LogConfiguration {
    return {
      enabledLevels: new Set(this._configuration.enabledLevels),
      enabledCategories: new Set(this._configuration.enabledCategories),
      outputToConsole: this._configuration.outputToConsole,
      maxLogEntries: this._configuration.maxLogEntries
    };
  }

  /**
   * Update log configuration
   */
  public updateConfiguration(config: Partial<LogConfiguration>): void {
    if (config.enabledLevels) {
      this._configuration.enabledLevels = new Set(config.enabledLevels);
    }
    if (config.enabledCategories) {
      this._configuration.enabledCategories = new Set(config.enabledCategories);
    }
    if (config.outputToConsole !== undefined) {
      this._configuration.outputToConsole = config.outputToConsole;
    }
    if (config.maxLogEntries !== undefined) {
      this._configuration.maxLogEntries = config.maxLogEntries;
    }

    StateManager.propertyChanged(this, 'configuration');
  }

  /**
   * Get all log entries
   */
  public get logEntries(): LogEntry[] {
    return [...this._logEntries];
  }

  /**
   * Get all categories that have been used in logging
   */
  public get usedCategories(): string[] {
    return Array.from(this._usedCategories).sort();
  }

  /**
   * Clear all log entries
   */
  public clearLogs(): void {
    this._logEntries = [];
    StateManager.propertyChanged(this, 'logEntries');
  }

  /**
   * Log an info message
   */
  public log(category: string, ...messages: any[]): void {
    this.addLogEntry(LogLevel.Info, category, messages);
  }

  /**
   * Log a debug message
   */
  public logDebug(category: string, ...messages: any[]): void {
    this.addLogEntry(LogLevel.Debug, category, messages);
  }

  /**
   * Log an error message
   */
  public logError(category: string, ...messages: any[]): void {
    this.addLogEntry(LogLevel.Error, category, messages);
  }

  /**
   * Add a log entry with the specified level
   */
  private addLogEntry(level: LogLevel, category: string, messages: any[]): void {
    // Track this category
    this._usedCategories.add(category);

    // Check if this level and category are enabled
    if (!this._configuration.enabledLevels.has(level) ||
      !this._configuration.enabledCategories.has(category)) {
      return;
    }

    // Format the message like // //// console.log
    const message = messages.map(msg => {
      if (typeof msg === 'string') {
        return msg;
      } else if (typeof msg === 'object') {
        try {
          return JSON.stringify(msg, null, 2);
        } catch {
          return String(msg);
        }
      } else {
        return String(msg);
      }
    }).join(' ');

    const logEntry: LogEntry = {
      id: `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date(),
      level,
      category,
      message
    };

    // Add to memory store
    this._logEntries.push(logEntry);

    // Maintain max entries limit
    if (this._logEntries.length > this._configuration.maxLogEntries) {
      this._logEntries = this._logEntries.slice(-this._configuration.maxLogEntries);
    }

    // Output to console if enabled
    if (this._configuration.outputToConsole) {
      const timestamp = logEntry.timestamp.toISOString();
      const prefix = `[${timestamp}] [${level.toUpperCase()}] [${category}]`;

      switch (level) {
        case LogLevel.Debug:
          console.debug(prefix, ...messages);
          break;
        case LogLevel.Info:
          // //// console.log(prefix, ...messages);
          break;
        case LogLevel.Error:
          console.error(prefix, ...messages);
          break;
      }
    }

    // Notify observers
    //  StateManager.propertyChanged(this, 'logEntries');
  }

  /**
   * Get filtered log entries
   */
  public getFilteredLogEntries(filters?: {
    levels?: LogLevel[];
    categories?: string[];
    searchText?: string;
  }): LogEntry[] {
    let filtered = this._logEntries;

    if (filters?.levels && filters.levels.length > 0) {
      filtered = filtered.filter(entry => filters.levels!.includes(entry.level));
    }

    if (filters?.categories && filters.categories.length > 0) {
      filtered = filtered.filter(entry => filters.categories!.includes(entry.category));
    }

    if (filters?.searchText) {
      const searchLower = filters.searchText.toLowerCase();
      filtered = filtered.filter(entry =>
        entry.message.toLowerCase().includes(searchLower) ||
        entry.category.toLowerCase().includes(searchLower)
      );
    }

    return filtered;
  }
}

// Export convenience functions for global use
export const log = (category: string, ...messages: any[]) => Logger.Instance.log(category, ...messages);
export const logDebug = (category: string, ...messages: any[]) => Logger.Instance.logDebug(category, ...messages);
export const logError = (category: string, ...messages: any[]) => Logger.Instance.logError(category, ...messages);
