/**
 * Clamp library (placeholder)
 * Direct conversion from C# ClampLibrary class
 */
import { SingletonRegistry } from '../../utils/SingletonRegistry';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { DataFileConstants } from '../DataFileConstants';
import { Clamp } from './Clamp';
import { SaveableDataBase } from './SaveableDataBase';

export enum ClampShape {
  Rectangular,
  Screw
}
export class ClampLibrary extends SaveableDataBase {
  public clamps: Clamp[] = []; // Array to hold clamp definitions

  /**
   * Filename for saving/loading clamp library data
   */
  protected get filename(): string {
    return DataFileConstants.CLAMPS;
  }

  private constructor() {
    super();

    // Register this singleton - will throw if a duplicate is created
    SingletonRegistry.ClampLibrary = this;

    // Initialize default clamps
    const defaultClamp = new Clamp();
    defaultClamp.clampname = "Small Clamp";
    defaultClamp.clampXWidth = 1;
    defaultClamp.clampYWidth = 3;
    defaultClamp.clampHeight = 5;
    defaultClamp.clampShape = ClampShape.Rectangular;
    defaultClamp.clampColor = 'blue';
    this.clamps.push(defaultClamp);

    // add more default clamps as needed
    const anotherClamp = new Clamp();
    anotherClamp.clampname = "Low Profile Clamp";
    anotherClamp.clampXWidth = 1;
    anotherClamp.clampYWidth = 3;
    anotherClamp.clampHeight = 2;
    anotherClamp.clampShape = ClampShape.Rectangular;
    anotherClamp.clampColor = 'lightblue';
    this.clamps.push(anotherClamp);

    // add larger clamps
    const largeClamp = new Clamp();
    largeClamp.clampname = "Large Clamp";
    largeClamp.clampXWidth = 3;
    largeClamp.clampYWidth = 3;
    largeClamp.clampHeight = 7;
    largeClamp.clampShape = ClampShape.Rectangular;
    largeClamp.clampColor = 'darkblue';
    this.clamps.push(largeClamp);

    // add very low profile clamp
    const veryLowClamp = new Clamp();
    veryLowClamp.clampname = "Very Low Profile Clamp";
    veryLowClamp.clampXWidth = 1;
    veryLowClamp.clampYWidth = 1;
    veryLowClamp.clampHeight = 0.5;
    veryLowClamp.clampShape = ClampShape.Rectangular;
    veryLowClamp.clampColor = 'darkgray';
    this.clamps.push(veryLowClamp);

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  public static get Instance(): ClampLibrary {
    if (!SingletonRegistry.ClampLibrary) {
      const instance = new ClampLibrary();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
    }
    return SingletonRegistry.ClampLibrary!;
  }

  /**
   * Update the entire clamps array from loaded data
   * This preserves existing clamp objects where possible by updating their properties
   * instead of replacing the entire array
   */
  public updateFromLoadedData(loadedClamps: any[]): void {
    if (!Array.isArray(loadedClamps)) return;

    // Clear existing clamps
    this.clamps.length = 0;

    // Add loaded clamps
    for (const clampData of loadedClamps) {
      const clamp = new Clamp();
      if (clampData.clampname !== undefined) clamp.clampname = clampData.clampname;
      if (clampData.clampXWidth !== undefined) clamp.clampXWidth = clampData.clampXWidth;
      if (clampData.clampYWidth !== undefined) clamp.clampYWidth = clampData.clampYWidth;
      if (clampData.clampHeight !== undefined) clamp.clampHeight = clampData.clampHeight;
      if (clampData.clampShape !== undefined) clamp.clampShape = clampData.clampShape;
      if (clampData.clampColor !== undefined) clamp.clampColor = clampData.clampColor;
      if (clampData.clampOffsetX !== undefined) clamp.clampOffsetX = clampData.clampOffsetX;
      if (clampData.clampOffsetY !== undefined) clamp.clampOffsetY = clampData.clampOffsetY;
      if (clampData.clampOffsetZ !== undefined) clamp.clampOffsetZ = clampData.clampOffsetZ;

      this.clamps.push(clamp);
    }

    StateManager.propertyChanged(this, 'clamps');
  }

  // Methods to manipulate clamps with state notifications
  public addClamp(clamp: Clamp): void {
    this.clamps.push(clamp);
    StateManager.propertyChanged(this, 'clamps');
  }

  public removeClamp(clamp: Clamp): void {
    const index = this.clamps.indexOf(clamp);
    if (index > -1) {
      this.clamps.splice(index, 1);
      StateManager.propertyChanged(this, 'clamps');
    }
  }

  public updateClamp(oldClamp: Clamp, newClamp: Clamp): void {
    const index = this.clamps.indexOf(oldClamp);
    if (index > -1) {
      this.clamps[index] = newClamp;
      StateManager.propertyChanged(this, 'clamps');
    }
  }

  /**
   * Serialize to JSON - handle clamps array explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['clamps']); // Exclude clamps from auto-processing

    // Handle clamps array explicitly with proper serialization
    return {
      ...baseData,
      clamps: this.clamps.map(clamp => clamp.toJSON())
    };
  }

  /**
   * Load from JSON - handle clamps array explicitly using fromJSON
   */
  public fromJSON(data: any): void {
    // Load basic properties
    DataUtilities.loadStorageData(this, data, ['clamps']); // Exclude clamps from auto-processing

    // Handle clamps array explicitly
    if (data.clamps && Array.isArray(data.clamps)) {
      this.clamps = data.clamps.map((clampData: any) => {
        const clamp = new Clamp();
        clamp.fromJSON(clampData);
        return clamp;
      });
    }
  }
}
