import React, { Component } from 'react';
import { LogCategory, Logger } from '../Logger';
import { Profiler } from '../Profiler';
import { DataUtilities } from './DataUtilities';
import { StateManager } from './StateManager';

export interface ObservableObjectProperties {
  object: any;
  properties: string[];
}

interface ObserveMultiPropertiesProps {
  key?: string; // RECOMMENDED: Unique identifier to prevent React reconciliation issues
  profilerName?: string; // Optional: Custom name for profiler tracking (defaults to key)
  listenTo: ObservableObjectProperties[];
  control: (changedProperties?: string[]) => React.ReactNode;
  shouldRender?: (changedProperties: string[]) => boolean; // Optional: Return false to skip re-render
}

interface ObserveMultiPropertiesState {
  updateCounter: number;
}

/**
 * Internal component that does the actual multi-property observation work
 */
class ObserveMultiPropertiesInternal extends Component<ObserveMultiPropertiesProps, ObserveMultiPropertiesState> {
  private lastChangedProperties?: string[];

  constructor(props: ObserveMultiPropertiesProps) {
    super(props);
    this.state = {
      updateCounter: 0
    };
  }

  componentDidMount() {
    this.subscribe();
  }

  componentWillUnmount() {
    this.unsubscribe();
  }

  componentDidUpdate(prevProps: ObserveMultiPropertiesProps) {
    // Check if the listenTo configuration has changed
    if (this.hasConfigurationChanged(prevProps.listenTo, this.props.listenTo)) {
      // Unsubscribe from previous configuration
      prevProps.listenTo.forEach(({ object }) => {
        if (object) {
          StateManager.removeObserver(object, this);
        }
      });

      // Subscribe to new configuration
      this.subscribe();
    }
  }

  private hasConfigurationChanged(
    prev: ObservableObjectProperties[],
    current: ObservableObjectProperties[]
  ): boolean {
    if (prev.length !== current.length) {
      return true;
    }

    for (let i = 0; i < prev.length; i++) {
      const prevItem = prev[i];
      const currentItem = current[i];

      // Check if object reference changed
      if (prevItem.object !== currentItem.object) {
        return true;
      }

      // Check if properties array changed
      if (prevItem.properties.length !== currentItem.properties.length) {
        return true;
      }

      for (let j = 0; j < prevItem.properties.length; j++) {
        if (prevItem.properties[j] !== currentItem.properties[j]) {
          return true;
        }
      }
    }

    return false;
  }

  private subscribe() {
    // Subscribe to each object with its specific properties
    this.props.listenTo.forEach(({ object, properties }) => {
      if (object) {
        if (Array.isArray(object)) {
          const error = 'ObserveMultiProperties.listenTo[].object cannot be an array. Arrays do not have individual property watchers. Map array elements to individual observation entries instead.';
          Logger.Instance.logError(LogCategory.StateManager, error);
          throw new Error(error);
        }
        StateManager.addObserver(object, this, properties);
      }
    });
  }

  private unsubscribe() {
    // Unsubscribe from all objects
    this.props.listenTo.forEach(({ object }) => {
      if (object) {
        StateManager.removeObserver(object, this);
      }
    });
  }

  // Required by IReactComponent interface
  updateFromStateManager(changedProperties?: string[]) {
    // Call optional shouldRender to allow component to skip unnecessary re-renders
    if (this.props.shouldRender && !this.props.shouldRender(changedProperties || [])) {
      return; // Skip re-render
    }

    this.lastChangedProperties = changedProperties;
    this.setState(prevState => ({
      updateCounter: prevState.updateCounter + 1
    }));
    super.forceUpdate();
  }

  render() {
    const profilerName = this.props.profilerName || this.props.key || 'ObserveMultiProperties';
    Profiler.Instance.captureStart(`${profilerName}-render`);
    const result = this.props.control(this.lastChangedProperties);
    Profiler.Instance.captureEnd(`${profilerName}-render`);
    return result;
  }
}

/**
 * ObserveMultiProperties - Advanced state observation component
 * 
 * Allows observing specific properties on multiple objects simultaneously
 * without unnecessary re-renders when unrelated properties change.
 * 
 * Example:
 * <ObserveMultiProperties
 *   key="unique-component-identifier"
 *   listenTo={[
 *     { object: ConfigurationState.Instance, properties: ['isSpindleDragging', 'isOrbitEnabled'] },
 *     { object: MachineStateData.Instance, properties: ['currentPosition'] }
 *   ]}
 *   control={() => <YourComponent />}
 * />
 * 
 * CRITICAL: Always provide a unique 'key' prop to prevent React reconciliation issues.
 */
export class ObserveMultiProperties extends Component<ObserveMultiPropertiesProps, { uniqueKey: string }> {

  constructor(props: ObserveMultiPropertiesProps) {
    super(props);
    // Generate a stable GUID that persists for the lifetime of this component instance
    this.state = {
      uniqueKey: DataUtilities.generateUniqueId()
    };
  }

  render() {
    return (
      <ObserveMultiPropertiesInternal
        key={this.state.uniqueKey}
        profilerName={this.props.profilerName}
        listenTo={this.props.listenTo}
        control={this.props.control}
      />
    );
  }
}
