import { Add as AddIcon, Close as CloseIcon, Delete as DeleteIcon, Edit as EditIcon } from '@mui/icons-material';
import { Box, Button, Chip, FormControl, IconButton, InputLabel, MenuItem, Paper, Select, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TextField, Typography } from '@mui/material';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { AddActionType } from '../data/ui/AddActionType';
import { KeybindingItem } from '../data/ui/KeybindingItem';
import { UITrigger } from '../data/ui/UITrigger';
import { KeybindingItemDialog } from './KeybindingItemDialog';

interface UITriggerDialogProps {
    open: boolean;
    trigger: UITrigger | null;
    onClose: () => void;
    onSave: (trigger: UITrigger) => void;
    programType: PLCProgramType;
}

/**
 * Dialog for editing UI Trigger properties
 */
export function UITriggerDialog({ open, trigger, onClose, onSave, programType }: UITriggerDialogProps): React.ReactElement {
    const [workingTrigger, setWorkingTrigger] = useState<UITrigger>(new UITrigger());
    const [errors, setErrors] = useState<{ [key: string]: string }>({});
    const [editingName, setEditingName] = useState('');
    const [keybindingDialogOpen, setKeybindingDialogOpen] = useState(false);
    const [editingKeybinding, setEditingKeybinding] = useState<KeybindingItem | null>(null);
    const colors = ConfigurationDataColors.Instance;
    const program = PLCProgram.Instance(programType);

    useEffect(() => {
        if (open) {
            if (trigger) {
                // Editing existing trigger - create a clone
                setWorkingTrigger(trigger.clone());
                // Remove _UI suffix for editing
                let name = trigger.eventName;
                if (name.endsWith('_UI')) {
                    name = name.slice(0, -3);
                }
                setEditingName(name);
            } else {
                // Creating new trigger - use first available number
                const availableNums = program.getAvailableEventNumbers();
                const newTrigger = new UITrigger();
                newTrigger.eventNumber = availableNums.length > 0 ? availableNums[0] : 0;
                newTrigger.pressedText = 'Triggered';
                newTrigger.notPressedText = 'Not Triggered';
                setWorkingTrigger(newTrigger);
                setEditingName('');
            }
            setErrors({});
        }
    }, [open, trigger, program]);

    const validateForm = (): boolean => {
        const newErrors: { [key: string]: string } = {};

        if (!workingTrigger.eventName.trim()) {
            newErrors.eventName = 'Event name is required';
        }

        if (workingTrigger.eventNumber < 0 || workingTrigger.eventNumber > 255) {
            newErrors.eventNumber = 'Event number must be between 0 and 255';
        }

        if (program.isEventNumberInUse(workingTrigger.eventNumber, trigger || undefined)) {
            newErrors.eventNumber = 'Event number is already in use';
        }

        if (!workingTrigger.pressedText.trim()) {
            newErrors.pressedText = 'Triggered text is required';
        }

        if (!workingTrigger.notPressedText.trim()) {
            newErrors.notPressedText = 'Not triggered text is required';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSave = () => {
        if (!validateForm()) {
            return;
        }

        onSave(workingTrigger);
    };

    const availableEventNumbers = program.getAvailableEventNumbers(trigger || undefined);

    const handleNameFocus = () => {
        // Remove _UI suffix when focusing
        let name = workingTrigger.eventName;
        if (name.endsWith('_UI')) {
            name = name.slice(0, -3);
        }
        setEditingName(name);
    };

    const handleNameBlur = () => {
        // Add _UI suffix and uppercase when leaving field
        let name = editingName.trim();
        if (name) {
            name = name.toUpperCase();
            if (!name.endsWith('_UI')) {
                name = name + '_UI';
            }
            workingTrigger.eventName = name;
        }
    };

    const handleAddKeybinding = () => {
        setEditingKeybinding(null);
        setKeybindingDialogOpen(true);
    };

    const handleEditKeybinding = (keybinding: KeybindingItem) => {
        setEditingKeybinding(keybinding);
        setKeybindingDialogOpen(true);
    };

    const handleDeleteKeybinding = (keybinding: KeybindingItem) => {
        workingTrigger.removeKeybinding(keybinding);
    };

    const handleKeybindingDialogClose = () => {
        setKeybindingDialogOpen(false);
        setEditingKeybinding(null);
    };

    const handleKeybindingDialogSave = (keybinding: KeybindingItem) => {
        if (editingKeybinding) {
            workingTrigger.updateKeybinding(editingKeybinding, keybinding);
        } else {
            workingTrigger.addKeybinding(keybinding);
        }
        setKeybindingDialogOpen(false);
        setEditingKeybinding(null);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                {trigger ? 'Edit UI Trigger' : 'Add UI Trigger'}
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <ObserveState
                        key="ui-trigger-dialog-form"
                        listenTo={workingTrigger}
                        properties={['eventName', 'eventNumber', 'description', 'pressedText', 'notPressedText', 'addAction']}
                        control={() => (
                            <>
                                <TextField
                                    label="Event Name"
                                    value={editingName}
                                    onChange={(e) => setEditingName(e.target.value)}
                                    onFocus={handleNameFocus}
                                    onBlur={handleNameBlur}
                                    error={!!errors.eventName}
                                    helperText={errors.eventName || 'Unique name for this UI trigger (suffix _UI will be added automatically)'}
                                    fullWidth
                                    autoFocus
                                />

                                <FormControl fullWidth error={!!errors.eventNumber}>
                                    <InputLabel>Event Number</InputLabel>
                                    <Select
                                        value={workingTrigger.eventNumber}
                                        label="Event Number"
                                        onChange={(e) => workingTrigger.eventNumber = Number(e.target.value)}
                                    >
                                        {trigger && !availableEventNumbers.includes(workingTrigger.eventNumber) && (
                                            <MenuItem value={workingTrigger.eventNumber}>
                                                {workingTrigger.eventNumber} (current)
                                            </MenuItem>
                                        )}
                                        {availableEventNumbers.map((num) => (
                                            <MenuItem key={num} value={num}>
                                                {num}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                    {errors.eventNumber && (
                                        <Box sx={{ color: 'error.main', fontSize: '0.75rem', mt: 0.5, ml: 2 }}>
                                            {errors.eventNumber}
                                        </Box>
                                    )}
                                    {!errors.eventNumber && (
                                        <Box sx={{ fontSize: '0.75rem', mt: 0.5, ml: 2, color: 'text.secondary' }}>
                                            Unique event number (0-255) for skin events
                                        </Box>
                                    )}
                                </FormControl>

                                <TextField
                                    label="Description"
                                    value={workingTrigger.description}
                                    onChange={(e) => workingTrigger.description = e.target.value}
                                    fullWidth
                                    multiline
                                    rows={2}
                                    helperText="Optional description of this trigger's purpose"
                                />

                                <TextField
                                    label="Triggered Text"
                                    value={workingTrigger.pressedText}
                                    onChange={(e) => workingTrigger.pressedText = e.target.value}
                                    error={!!errors.pressedText}
                                    helperText={errors.pressedText || 'Text to display when trigger is triggered/active'}
                                    fullWidth
                                />

                                <TextField
                                    label="Not Triggered Text"
                                    value={workingTrigger.notPressedText}
                                    onChange={(e) => workingTrigger.notPressedText = e.target.value}
                                    error={!!errors.notPressedText}
                                    helperText={errors.notPressedText || 'Text to display when trigger is not triggered/inactive'}
                                    fullWidth
                                />

                                <FormControl fullWidth>
                                    <InputLabel>Add to Action Panel</InputLabel>
                                    <Select
                                        value={workingTrigger.addAction}
                                        label="Add to Action Panel"
                                        onChange={(e) => workingTrigger.addAction = Number(e.target.value) as AddActionType}
                                    >
                                        <MenuItem value={AddActionType.No}>No</MenuItem>
                                        <MenuItem value={AddActionType.Click}>Click</MenuItem>
                                        <MenuItem value={AddActionType.Press}>Press</MenuItem>
                                    </Select>
                                    <Box sx={{ fontSize: '0.75rem', mt: 0.5, ml: 2, color: 'text.secondary' }}>
                                        Whether to add this trigger as an action in the action panel
                                    </Box>
                                </FormControl>
                            </>
                        )}
                    />

                    {/* Keybindings Section */}
                    <ObserveState
                        key="ui-trigger-keybindings"
                        listenTo={workingTrigger}
                        properties={['keybindings']}
                        control={() => (
                            <Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                    <Typography variant="subtitle2">
                                        Keybindings (Optional)
                                    </Typography>
                                    <Button
                                        variant="outlined"
                                        size="small"
                                        startIcon={<AddIcon />}
                                        onClick={handleAddKeybinding}
                                    >
                                        Add Keybinding
                                    </Button>
                                </Box>

                                {workingTrigger.keybindings.length > 0 ? (
                                    <TableContainer component={Paper} sx={{ maxHeight: 200 }}>
                                        <Table size="small">
                                            <TableHead>
                                                <TableRow>
                                                    <TableCell sx={{ fontWeight: 600 }}>Key Combination</TableCell>
                                                    <TableCell sx={{ fontWeight: 600 }} align="right">Actions</TableCell>
                                                </TableRow>
                                            </TableHead>
                                            <TableBody>
                                                {workingTrigger.keybindings.map((kb, index) => (
                                                    <TableRow key={index}>
                                                        <TableCell>
                                                            <Chip
                                                                label={kb.getKeyString()}
                                                                size="small"
                                                                sx={{ fontFamily: 'monospace' }}
                                                            />
                                                        </TableCell>
                                                        <TableCell align="right">
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => handleEditKeybinding(kb)}
                                                                sx={{ mr: 1 }}
                                                            >
                                                                <EditIcon fontSize="small" />
                                                            </IconButton>
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => handleDeleteKeybinding(kb)}
                                                                color="error"
                                                            >
                                                                <DeleteIcon fontSize="small" />
                                                            </IconButton>
                                                        </TableCell>
                                                    </TableRow>
                                                ))}
                                            </TableBody>
                                        </Table>
                                    </TableContainer>
                                ) : (
                                    <Box
                                        sx={{
                                            p: 2,
                                            textAlign: 'center',
                                            border: `1px dashed ${colors.borderColor}`,
                                            borderRadius: 1,
                                            color: 'text.secondary'
                                        }}
                                    >
                                        <Typography variant="body2">
                                            No keybindings assigned. Click "Add Keybinding" to add keyboard shortcuts.
                                        </Typography>
                                    </Box>
                                )}
                            </Box>
                        )}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose}>Cancel</Button>
                <Button
                    onClick={handleSave}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9,
                        },
                    }}
                >
                    {trigger ? 'Update' : 'Add'}
                </Button>
            </DialogActions>

            {/* Keybinding Item Dialog */}
            <KeybindingItemDialog
                open={keybindingDialogOpen}
                keybindingItem={editingKeybinding}
                onClose={handleKeybindingDialogClose}
                onSave={handleKeybindingDialogSave}
            />
        </Dialog>
    );
}
