import {
  Lock as LockIcon,
  SwapHoriz as SwapIcon
} from '@mui/icons-material';
import {
  Box,
  IconButton,
  ListItem,
  Tooltip,
  Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { OutputWithState } from '../../data/IOStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface OutputItemProps {
  output: OutputWithState;
  onToggle: (outputNumber: number) => void;
}

export function OutputItem({ output, onToggle }: OutputItemProps) {
  return (
    <ObserveState
      key={`output-item-${output.number}`}
      listenTo={output}
      properties={['isActive', 'isForced']}
      control={() => {
        const colors = ConfigurationDataColors.Instance;
        const displayText = output.isActive ? output.activeText : output.inactiveText;
        const activeColor = colors.successColor; // Green color for active outputs
        const forcedColor = colors.warningColor; // Orange color for forced outputs

        return (
          <ListItem
            sx={{
              py: 0.75,
              px: 1.5,
              borderBottom: `1px solid ${colors.borderColor}`,
              minHeight: 48,
              display: 'flex',
              alignItems: 'center',
              backgroundColor: output.isForced ? `${forcedColor}08` : 'transparent'
            }}
          >
            <Box sx={{
              display: 'flex',
              alignItems: 'center',
              width: '100%',
              gap: 1
            }}>
              {/* Output Number in Solid Box */}
              <Box
                sx={{
                  width: 28,
                  height: 24,
                  backgroundColor: output.isForced ? forcedColor : (output.isActive ? activeColor : colors.errorColor),
                  color: colors.lightTextColor,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: 1,
                  fontSize: '0.75rem',
                  fontWeight: 'bold',
                  flexShrink: 0
                }}
              >
                {output.number}
              </Box>

              {/* Output Name */}
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <Typography
                    variant="body2"
                    sx={{
                      fontSize: '0.8rem',
                      fontWeight: 500,
                      color: colors.darkTextColor,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap'
                    }}
                  >
                    {output.name}
                  </Typography>
                  {output.isForced && (
                    <Tooltip title="Output is forced - manual control active">
                      <LockIcon sx={{ fontSize: 14, color: forcedColor }} />
                    </Tooltip>
                  )}
                </Box>
                {output.centroidName && (
                  <Typography
                    variant="caption"
                    sx={{
                      fontSize: '0.65rem',
                      color: colors.mutedTextColor,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      fontStyle: 'italic'
                    }}
                  >
                    {output.centroidName} [{output.getOnGCode()} • {output.getOffGCode()}]
                  </Typography>
                )}
                {!output.centroidName && (
                  <Typography
                    variant="caption"
                    sx={{
                      fontSize: '0.65rem',
                      color: colors.mutedTextColor,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      letterSpacing: '0.5px'
                    }}
                  >
                    [{output.getOnGCode()} • {output.getOffGCode()}]
                  </Typography>
                )}
              </Box>

              {/* Active/Inactive Status Text */}
              <Box sx={{
                minWidth: 80,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'flex-end'
              }}>
                <Typography
                  variant="caption"
                  sx={{
                    fontSize: '0.7rem',
                    fontWeight: output.isActive ? 'bold' : 'normal',
                    color: output.isForced ? forcedColor : (output.isActive ? activeColor : colors.errorColor),
                    textAlign: 'right'
                  }}
                >
                  {displayText}
                </Typography>
              </Box>

              {/* Toggle Button */}
              <Box sx={{
                minWidth: 40,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'flex-end'
              }}>
                <Tooltip title={output.isForced ? 'Forced - click to manage' : 'Toggle output state'}>
                  <IconButton
                    size="small"
                    onClick={() => onToggle(output.number)}
                    sx={{
                      color: output.isForced ? forcedColor : (output.isActive ? activeColor : colors.errorColor),
                      '&:hover': {
                        backgroundColor: output.isForced
                          ? `${forcedColor}1A`
                          : (output.isActive ? `${activeColor}1A` : `${colors.errorColor}1A`)
                      }
                    }}
                  >
                    <SwapIcon />
                  </IconButton>
                </Tooltip>
              </Box>
            </Box>
          </ListItem>
        );
      }}
    />
  );
}