import {
  Box,
  Button,
  Divider
} from '@mui/material';
import React, { useState } from 'react';
import { ClampLibraryTab, FixtureLibraryTab, MaterialLibraryTab, ToolLibraryTab } from './Settings/';

interface SettingsTabButtonProps {
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const SettingsTabButton: React.FC<SettingsTabButtonProps> = ({ label, isActive, onClick }) => (
  <Button
    variant={isActive ? 'contained' : 'text'}
    onClick={onClick}
    sx={{
      mx: 1,
      minWidth: '120px',
      textTransform: 'none',
      fontSize: '14px'
    }}
  >
    {label}
  </Button>
);

type SettingsTab = 'materials' | 'tools' | 'clamps' | 'fixtures';

export const Settings: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('tools');

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'materials':
        return <MaterialLibraryTab />;
      case 'tools':
        return <ToolLibraryTab />;
      case 'clamps':
        return <ClampLibraryTab />;
      case 'fixtures':
        return <FixtureLibraryTab />;
      default:
        return <MaterialLibraryTab />;
    }
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Tab Navigation */}
      <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', backgroundColor: 'background.paper' }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>

          <SettingsTabButton
            label="Tools"
            isActive={activeTab === 'tools'}
            onClick={() => setActiveTab('tools')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Fixtures/Known Points"
            isActive={activeTab === 'fixtures'}
            onClick={() => setActiveTab('fixtures')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Materials"
            isActive={activeTab === 'materials'}
            onClick={() => setActiveTab('materials')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Clamps"
            isActive={activeTab === 'clamps'}
            onClick={() => setActiveTab('clamps')}
          />
        </Box>
      </Box>

      {/* Main Content - Full Width */}
      <Box sx={{ flex: 1, overflow: 'auto' }}>
        {renderActiveTab()}
      </Box>
    </Box>
  );
};
