import { Box, Button, Typography } from '@mui/material';
import React, { useState } from 'react';
import { CNCPoint } from '../../../../data/CNCPoint';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { DataManager } from '../../../../data/DataManager';
import { AxisType } from '../../../../data/Machine/AxisType';
import { MachineData } from '../../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { MovementCoordinateType } from '../../../../machine/ICNCMovement';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { AxisCalibrationWizard } from '../AxisCalibrationWizard';
import { StartingPositionStep } from './StartingPositionStep';

/**
 * Step to ask if user wants to return to starting position before rerunning calibration
 */
export class ReturnToStartStep extends WizardStep {
    getTitle(): string {
        return 'Return to Starting Position?';
    }

    nextStep(): WizardStep | null {
        return null; // We'll navigate programmatically
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="return-to-start-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <ReturnToStartStepComponent step={this} />}
            />
        );
    }
}

interface ReturnToStartStepComponentProps {
    step: ReturnToStartStep;
}

function ReturnToStartStepComponent({ step }: ReturnToStartStepComponentProps) {
    const wizard = step.wizard as AxisCalibrationWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isReturning, setIsReturning] = useState(false);

    const axisName = wizard.state.selectedAxis;
    const startingPosition = wizard.state.startingPosition;
    const actualDistance = wizard.state.actualDistance;
    const commandedDistance = wizard.state.commandedDistance || 10;

    // Get axis configuration
    const machineData = MachineData.Instance;
    const axis = machineData.axisConfigurations.find(a => a.axisType === axisName);

    const applyChanges = async () => {
        try {
            if (!axis) {
                Logger.Instance.logError(LogCategory.System, `Failed to find ${axisName} axis`);
                UserMessageQueue.Instance.addMessage(`❌ Failed to find ${axisName} axis`);
                return false;
            }

            // Calculate new turns ratio
            const currentTurnsRatio = axis.overallTurnsRatio;
            if (actualDistance === null || actualDistance === 0) {
                Logger.Instance.logError(LogCategory.System, `Invalid actual distance for ${axisName} axis`);
                UserMessageQueue.Instance.addMessage(`❌ Invalid actual distance`);
                return false;
            }
            const ratio = commandedDistance / actualDistance;
            const newTurnsRatio = currentTurnsRatio * ratio;

            // Update axis configuration with new turns ratio
            axis.overallTurnsRatio = newTurnsRatio;

            // Save configuration
            await DataManager.Instance.saveMachineDataIndividual();

            UserMessageQueue.Instance.addMessage(`✓ ${axisName} axis calibration applied`);

            return true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to apply axis calibration:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to apply calibration changes');
            return false;
        }
    };

    const resetWizardState = () => {
        // Reset state for new calibration run
        wizard.state = {
            ...wizard.state,
            startingPosition: 0,
            commandedDistance: 10,
            actualDistance: null,
            currentStepsPerInch: axis ? axis.stepsPerRevolution * axis.overallTurnsRatio : 0,
            newStepsPerInch: null
        };
    };

    const handleYes = async () => {
        setIsReturning(true);

        // Apply the calibration changes first
        const success = await applyChanges();
        if (!success) {
            setIsReturning(false);
            return;
        }

        try {
            // Return to starting position
            const currentPoint = ConfigurationState.Instance.currentMachinePoint;

            let targetPoint: CNCPoint;
            if (axisName === AxisType.X) {
                targetPoint = new CNCPoint(startingPosition, currentPoint.y, currentPoint.z, CoordinateType.MachineZero);
            } else if (axisName === AxisType.Y) {
                targetPoint = new CNCPoint(currentPoint.x, startingPosition, currentPoint.z, CoordinateType.MachineZero);
            } else if (axisName === AxisType.Z) {
                targetPoint = new CNCPoint(currentPoint.x, currentPoint.y, startingPosition, CoordinateType.MachineZero);
            } else {
                targetPoint = currentPoint;
            }

            // Move to starting position
            await Machine.getInstance().movement.MoveTo(
                targetPoint,
                MovementCoordinateType.Machine,
                100,  // XY speed
                100   // Z speed
            );

            UserMessageQueue.Instance.addMessage(`✓ Returned to starting position`);
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to return to starting position:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to return to starting position');
        }

        // Reset wizard state and go to starting position step
        resetWizardState();
        wizard.currentStep = new StartingPositionStep(wizard, null);
        StateManager.propertyChanged(wizard, 'currentStep');
        setIsReturning(false);
    };

    const handleNo = async () => {
        // Apply the calibration changes
        const success = await applyChanges();
        if (!success) {
            return;
        }

        // Reset wizard state and go to starting position step
        resetWizardState();
        wizard.currentStep = new StartingPositionStep(wizard, null);
        StateManager.propertyChanged(wizard, 'currentStep');
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Return to Starting Position?
                </Typography>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Would you like to return the {axisName} axis to the starting position before running calibration again?
                </Typography>
            </Box>

            {/* Main content */}
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 3 }}>
                {/* Starting position info */}
                <Box sx={{
                    p: 3,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    border: `1px solid ${colors.borderColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.mutedTextColor, mb: 2 }}>
                        Starting Position:
                    </Typography>
                    <Typography variant="h4" sx={{ color: colors.primaryColor, fontWeight: 'bold', fontFamily: 'monospace' }}>
                        {axisName} = {startingPosition.toFixed(4)}"
                    </Typography>
                </Box>

                {/* Options explanation */}
                <Box sx={{
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Your Options:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 1 }}>
                        <strong>Yes</strong> - Apply calibration, move back to starting position, then run calibration again
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        <strong>No</strong> - Apply calibration and run again from current position
                    </Typography>
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                    disabled={isReturning}
                >
                    Back
                </Button>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button
                        variant="outlined"
                        onClick={handleNo}
                        disabled={isReturning}
                    >
                        No
                    </Button>
                    <Button
                        variant="contained"
                        onClick={handleYes}
                        disabled={isReturning}
                        sx={{ backgroundColor: colors.primaryColor }}
                    >
                        {isReturning ? 'Returning...' : 'Yes'}
                    </Button>
                </Box>
            </Box>
        </Box>
    );
}
