import { Job } from './Job';
import { StateManager } from '../utils/statemanager/StateManager';

/**
 * Job execution status enum
 */
export enum JobExecutionStatus {
    Ready = 'ready',
    Running = 'running',
    Paused = 'paused',
    Stopped = 'stopped',
    Completed = 'completed'
}

/**
 * Tracks the state of a running job execution
 * NOT a singleton - each job run gets its own execution state instance
 * This ensures runs are independent and don't share state
 */
export class JobExecutionState {
    private _currentJob: Job | null = null;
    private _isRunning: boolean = false;
    private _isPaused: boolean = false;
    private _isCompleted: boolean = false;
    private _isStopped: boolean = false;
    private _currentStageIndex: number = 0;
    private _currentLineNumber: number = -1;
    private _startTime: number = 0;
    private _endTime: number | null = null;
    private _elapsedSeconds: number = 0;
    private _feedRateOverride: number = 100;
    private _spindleSpeedOverride: number = 100;
    private _errorMessage: string | null = null;

    constructor(job: Job) {
        this._currentJob = job;
    }

    // Current job being executed
    public get currentJob(): Job | null {
        return this._currentJob;
    }

    public set currentJob(value: Job | null) {
        this._currentJob = value;
        StateManager.propertyChanged(this, 'currentJob');
    }

    // Running state
    public get isRunning(): boolean {
        return this._isRunning;
    }

    public set isRunning(value: boolean) {
        this._isRunning = value;
        StateManager.propertyChanged(this, 'isRunning');
    }

    public get isPaused(): boolean {
        return this._isPaused;
    }

    public set isPaused(value: boolean) {
        this._isPaused = value;
        StateManager.propertyChanged(this, 'isPaused');
    }

    public get isCompleted(): boolean {
        return this._isCompleted;
    }

    public set isCompleted(value: boolean) {
        this._isCompleted = value;
        StateManager.propertyChanged(this, 'isCompleted');
    }

    public get isStopped(): boolean {
        return this._isStopped;
    }

    public set isStopped(value: boolean) {
        this._isStopped = value;
        StateManager.propertyChanged(this, 'isStopped');
    }

    // Progress tracking
    public get currentStageIndex(): number {
        return this._currentStageIndex;
    }

    public set currentStageIndex(value: number) {
        this._currentStageIndex = value;
        StateManager.propertyChanged(this, 'currentStageIndex');
    }

    public get currentLineNumber(): number {
        return this._currentLineNumber;
    }

    public set currentLineNumber(value: number) {
        this._currentLineNumber = value;
        StateManager.propertyChanged(this, 'currentLineNumber');
    }

    // Timing
    public get startTime(): number {
        return this._startTime;
    }

    public set startTime(value: number) {
        this._startTime = value;
        StateManager.propertyChanged(this, 'startTime');
    }

    public get endTime(): number | null {
        return this._endTime;
    }

    public set endTime(value: number | null) {
        this._endTime = value;
        StateManager.propertyChanged(this, 'endTime');
    }

    public get elapsedSeconds(): number {
        return this._elapsedSeconds;
    }

    public set elapsedSeconds(value: number) {
        this._elapsedSeconds = value;
        StateManager.propertyChanged(this, 'elapsedSeconds');
    }

    // Overrides
    public get feedRateOverride(): number {
        return this._feedRateOverride;
    }

    public set feedRateOverride(value: number) {
        this._feedRateOverride = value;
        StateManager.propertyChanged(this, 'feedRateOverride');
    }

    public get spindleSpeedOverride(): number {
        return this._spindleSpeedOverride;
    }

    public set spindleSpeedOverride(value: number) {
        this._spindleSpeedOverride = value;
        StateManager.propertyChanged(this, 'spindleSpeedOverride');
    }

    // Error tracking
    public get errorMessage(): string | null {
        return this._errorMessage;
    }

    public set errorMessage(value: string | null) {
        this._errorMessage = value;
        StateManager.propertyChanged(this, 'errorMessage');
    }

    /**
     * Get current run status as string
     */
    public get status(): JobExecutionStatus {
        if (this._isCompleted) return JobExecutionStatus.Completed;
        if (this._isStopped) return JobExecutionStatus.Stopped;
        if (this._isPaused) return JobExecutionStatus.Paused;
        if (this._isRunning) return JobExecutionStatus.Running;
        return JobExecutionStatus.Ready;
    }

    /**
     * Start a new job execution
     */
    public startJob(): void {
        this.isRunning = true;
        this.isPaused = false;
        this.isCompleted = false;
        this.isStopped = false;
        this.currentStageIndex = 0;
        this.currentLineNumber = -1;
        this.startTime = Date.now();
        this.endTime = null;
        this.elapsedSeconds = 0;
        this.errorMessage = null;
    }

    /**
     * Pause the current job
     */
    public pause(): void {
        this.isPaused = true;
        this.isRunning = false;
    }

    /**
     * Resume the paused job
     */
    public resume(): void {
        this.isPaused = false;
        this.isRunning = true;
    }

    /**
     * Stop the current job
     */
    public stop(): void {
        this.isStopped = true;
        this.isRunning = false;
        this.isPaused = false;
        this.endTime = Date.now();
    }

    /**
     * Mark job as completed
     */
    public complete(): void {
        this.isCompleted = true;
        this.isRunning = false;
        this.isPaused = false;
        this.endTime = Date.now();
    }

    /**
     * Reset to initial state
     */
    public reset(): void {
        this.currentJob = null;
        this.isRunning = false;
        this.isPaused = false;
        this.isCompleted = false;
        this.endTime = null;
        this.isStopped = false;
        this.currentStageIndex = 0;
        this.currentLineNumber = -1;
        this.startTime = 0;
        this.elapsedSeconds = 0;
        this.feedRateOverride = 100;
        this.spindleSpeedOverride = 100;
        this.errorMessage = null;
    }
}
