import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying machine zero coordinates configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the machine zero coordinates are correctly set relative to machine home.
 */
export class MachineZeroChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Machine Zero Coordinates',
            'Configure machine zero coordinates from machine home position'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured the correct coordinates
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if coordinates are correct
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new MachineZeroChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
