import {
    Box,
    Grid,
    Paper,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

export function PLCParametersSection() {
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Message Queue Settings</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Controls the depth of message priority queue levels. Lower values generate less PLC code.
                    </Typography>

                    <ObserveState
                        key="plc-message-queue-depth"
                        listenTo={config}
                        properties={['messageQueueDepth']}
                        control={() => (
                            <Box>
                                <Typography variant="body2" gutterBottom sx={{ fontWeight: 500 }}>
                                    Message Queue Depth: {config.messageQueueDepth} {config.messageQueueDepth === 1 ? 'level' : 'levels'}
                                </Typography>
                                <ToggleButtonGroup
                                    value={config.messageQueueDepth}
                                    exclusive
                                    onChange={(_, value) => {
                                        if (value !== null) {
                                            config.messageQueueDepth = value;
                                        }
                                    }}
                                    sx={{
                                        mt: 1,
                                        '& .MuiToggleButton-root': {
                                            '&.Mui-selected': {
                                                backgroundColor: colors.primaryColor,
                                                color: colors.lightTextColor,
                                                '&:hover': {
                                                    backgroundColor: colors.primaryColor,
                                                    opacity: 0.9
                                                }
                                            }
                                        }
                                    }}
                                    fullWidth
                                >
                                    <ToggleButton value={1} sx={{ flex: 1 }}>1</ToggleButton>
                                    <ToggleButton value={2} sx={{ flex: 1 }}>2</ToggleButton>
                                    <ToggleButton value={3} sx={{ flex: 1 }}>3</ToggleButton>
                                    <ToggleButton value={4} sx={{ flex: 1 }}>4</ToggleButton>
                                    <ToggleButton value={5} sx={{ flex: 1 }}>5</ToggleButton>
                                </ToggleButtonGroup>
                                <Typography variant="caption" display="block" sx={{ mt: 1, color: 'text.secondary' }}>
                                    Default: 3 levels. Higher values create more nested IF statements for message priority handling.
                                </Typography>
                            </Box>
                        )}
                    />
                </Paper>
            </Grid>
        </Grid>
    );
}
