/**
 * Enum of standard PLC input names from Centroid PLC template
 * These correspond to the centroidName field in InputMapping
 * All input names have _I suffix to distinguish from outputs
 * Only includes inputs that are actually used in DefaultPLCInputs
 */
export enum PLCInputName {
    // Safety & Emergency Stop
    EStopOk = 'ESTOPOK_I',
    EStopOk2 = 'ESTOPOK2_I',

    // Spindle Control & Monitoring
    SpindleOk = 'SPINDLEOK_I',

    // Tool Management & ATC
    ToolIsUnclamped = 'TOOLISUNCLAMPED_I',
    ToolUnclampButton = 'TOOLUNCLAMPBUTTON_I',
    ToolIsClamped = 'TOOLCLAMPED_I',
    ToolIsPresent_I = 'TOOLISPRESENT_I',
    DrawBarReleased = 'DRAWBARRELEASED_I',
    DrawBarIsUp = 'DRAWBARISUP_I',
    DrawBarIsDown = 'DRAWBARISDOWN_I',
    ATC_AirPressureOk = 'ATC_AIRPRESSUREOK_I',

    // Axis Control & Limits
    XAxisHomeLimitOk = 'x_AXISLIMITOK_I',
    YAxisHomeLimitOk = 'Y_AXISLIMITOK_I',
    ZAxisHomeLimitOk = 'Z_AXISLIMITOK_I',
    XAxisLimitOk = 'X_AXISLIMIT_I',
    YAxisLimitOk = 'Y_AXISLIMIT_I',
    ZAxisLimitOk = 'Z_AXISLIMIT_I',
    AAxisHomeLimitOk = 'A_AXISHOMELIMITOK_I',
    AAxisLimitOk = 'A_AXISLIMIT_I',

    HomeLimitAll = 'HOMELIMITALL_I',
    SlavedHomeInput = 'SLAVEDHOMEINPUT_I',

    // Drive Status
    DriveOk = 'DRIVEOK_I',
    Axis1DriveOk = 'AXIS1DRIVEOK_I',
    Axis2DriveOk = 'AXIS2DRIVEOK_I',
    Axis3DriveOk = 'AXIS3DRIVEOK_I',
    Axis4DriveOk = 'AXIS4DRIVEOK_I',

    // Probe Functions
    ProbeDetect = 'PROBEDETECT_I',
    ProbeTripped = 'PROBETRIPPED_I',

    // Coolant & Air Pressure
    LubeOk = 'LUBEOK_I',
    AirPressureLowMessage = 'AIRPRESSURELOWMESSAGE_I',
    AirPressureLowStop = 'AIRPRESSURELOWSTOP_I',

    // Control Buttons
    CycleStart2 = 'CYCLESTART2_I',
    FeedHold2 = 'FEEDHOLD2_I',
    CycleCancel2 = 'CYCLECANCEL2_I',
    ToolCheck2 = 'TOOLCHECK2_I',

    // Laser Functions
    LaserReady = 'LASERREADY_I',

    // Additional Custom Touch Plates
    FixedToolTouchPlate = 'FIXED_TOOL_TOUCH_PLATE_I',
    MaterialToolTouchPlate = 'MATERIAL_TOOL_TOUCH_PLATE_I',
}

/**
 * Enum of standard PLC output names from Centroid PLC template
 * These correspond to the centroidName field in OutputMapping
 * All output names have _O suffix to distinguish from inputs
 * Only includes outputs that are actually used in DefaultPLCOutputs
 */
export enum PLCOutputName {
    // System Status
    NoFaultOut = 'NOFAULTOUT_O',
    DriveResetOut = 'DRIVERESETOUT_O',

    // Spindle Control
    SpinFWD = 'SPINFWD_O',
    SpinREV = 'SPINREV_O',
    SpindleBrakeRelease = 'SPINDLEBRAKERELEASE_O',

    // Tool Management & ATC
    UnclampTool = 'UNCLAMPTOOL_O',
    DrawBarUp_O = 'DRAWBARUP_O',
    ATCAirBlowActivate = 'ATCAIRBLOWACTIVATE_O',

    // Coolant & Auxiliary
    Flood = 'FLOOD_O',
    Mist = 'MIST_O',
    LubePump = 'LUBEPUMP_O',
    RouterVacuumHoldDown = 'ROUTERVACUUMHOLDDOWN_O',
    DustCollectionOn = 'DUSTCOLLECTIONON_O',

    // Router/Mill Specific
    DustFootActivate = 'DUSTFOOTACTIVATE_O',
    LaserAlignActivate = 'LASERALIGNACTIVATE_O',
    AirBlowNozzle = 'AIRBLOWNOZZLE_O',
    LaserPointer = 'LASERPOINTER_O',
    PositioningPins = 'POSITIONINGPINS_O',

    // Laser Functions
    LaserEnable = 'LASERENABLE_O',
    LaserReset = 'LASERRESET_O',
    AlignmentLaserEnable_O = 'ALIGNMENTLASERENABLE_O',
    LaserStandby_O = 'LASERSTANDBY_O',
    FiberLaserReset_O = 'FIBERLASERRESE T_O',
    LaserDeploy_O = 'LASERDEPLOY_O',

    // PWM and Special Outputs
    PWMSelect = 'PWMSELECT_O',
}
