import {
  Inventory as MaterialIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Divider,
  FormControl,
  Grid,
  InputLabel,
  Link,
  MenuItem,
  Select,
  ToggleButton,
  ToggleButtonGroup,
  Tooltip,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { Material } from '../../data/Common/Material';
import { MaterialColors, MaterialType } from '../../data/Common/MaterialLibrary';
import { MaterialPositionReference } from '../../data/Common/MaterialPositionReference';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { ViewStyle } from '../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ViewDataFactory, ViewNames } from '../../utils/ViewDataFactory';
import { ColorPicker } from '../Common/ColorPicker';
import { NumberInput } from '../Common/NumberInput';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';

interface MaterialEditorFormProps {
  material: Material;
  onMaterialChange: (field: keyof Material, value: any) => void;
  onSaveToLibrary?: () => void;
  onLoadFromLibrary?: () => void;
}

interface MaterialEditorFormState {
  selectedMaterialType: string;
}

export class MaterialEditorForm extends Component<MaterialEditorFormProps, MaterialEditorFormState> {
  constructor(props: MaterialEditorFormProps) {
    super(props);

    this.state = {
      selectedMaterialType: props.material.type || MaterialType.Wood
    };
  }

  componentDidUpdate(prevProps: MaterialEditorFormProps) {
    if (prevProps.material.type !== this.props.material.type) {
      this.setState({
        selectedMaterialType: this.props.material.type || MaterialType.Wood
      });
    }
  }

  handleMaterialTypeChange = (type: MaterialType) => {
    this.setState({ selectedMaterialType: type });
    this.props.onMaterialChange('type', type);
  };

  getMaterialTypeColor = (type: MaterialType) => {
    switch (type) {
      case MaterialType.Wood: return 'success';
      case MaterialType.Metal: return 'info';
      case MaterialType.Plastic: return 'warning';
      case MaterialType.Composite: return 'secondary';
      default: return 'default';
    }
  };

  calculateMaterialVolume = () => {
    const { material } = this.props;
    return (material.xLength * material.yLength * material.height).toFixed(3);
  };

  // Create a hardcoded simulator view specifically for material editing
  private createMaterialEditorSimulatorView(): SimulatorView {
    const view = new SimulatorView();

    // Show essential elements for material stage: spoilboard, toolpaths, material, tool
    view.spoilBoard = ViewStyle.Show;          // Show spoilboard
    view.toolpaths = true;                     // Show toolpaths
    view.material = ViewStyle.Show;            // Show material (solid)
    view.tool = ViewStyle.Show;                // Show tool
    view.workHome = true;                      // Show work home for reference

    // Hide everything else to keep focus on material
    view.softLimits = false;
    view.machineZero = false;
    view.machineHome = false;
    view.gantry = ViewStyle.Hide;
    view.base = ViewStyle.Hide;
    view.bed = ViewStyle.Hide;
    view.railing = ViewStyle.Hide;
    view.spindle = ViewStyle.SemiTransparent;
    view.workPiece = ViewStyle.Hide;
    view.clamps = ViewStyle.Hide;
    view.rotary = ViewStyle.Hide;
    view.verticalTable = ViewStyle.Hide;
    view.laser = ViewStyle.Hide;
    view.laserPointer = ViewStyle.Hide;
    view.drillHead = ViewStyle.Hide;
    view.atc = ViewStyle.Hide;

    return view;
  }

  render() {
    const {
      material,
      onMaterialChange,
      onSaveToLibrary,
      onLoadFromLibrary
    } = this.props;
    const { selectedMaterialType } = this.state;

    // Get material colors from the library
    const materialColors = MaterialColors.Instance;

    return (
      <Box sx={{ display: 'flex', gap: 3, height: '100%' }}>
        {/* Material Editor Form */}
        <Box sx={{ flex: 1, height: '100%' }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">Material Properties</Typography>
          </Box>

          <Grid container spacing={3}>
            {/* First row: X/Y/Z dimensions */}
            <Grid item xs={12} sm={4}>
              <NumberInput
                fullWidth
                label="Length (X)"
                value={material.xLength}
                onChange={(value) => onMaterialChange('xLength', value)}
                allowNegative={false}
                allowPositive={true}
                allowFractions={true}
                defaultUnit="in"
                precision={3}
                showHelperText={false}
                min={0}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <NumberInput
                fullWidth
                label="Width (Y)"
                value={material.yLength}
                onChange={(value) => onMaterialChange('yLength', value)}
                allowNegative={false}
                allowPositive={true}
                allowFractions={true}
                defaultUnit="in"
                precision={3}
                showHelperText={false}
                min={0}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <NumberInput
                fullWidth
                label="Height (Z)"
                value={material.height}
                onChange={(value) => onMaterialChange('height', value)}
                allowNegative={false}
                allowPositive={true}
                allowFractions={true}
                defaultUnit="in"
                precision={3}
                showHelperText={false}
                min={0}
              />
            </Grid>

            {/* Second row: Position Type and Material Type */}
            <ObserveState
              key="material-editor-position-type"
              listenTo={ConfigurationState.Instance}
              properties={['currentJob']}
              control={() => {
                const currentJob = ConfigurationState.Instance.currentJob;

                if (!currentJob) {
                  return (
                    <>
                      <Grid item xs={12} sm={6}>
                        <ToggleButtonGroup
                          value={MaterialPositionReference.WorkHome}
                          exclusive
                          disabled
                          aria-label="material position reference"
                          size="medium"
                          sx={{
                            height: '56px',
                            width: '100%',
                            '& .MuiToggleButton-root': {
                              height: '56px',
                              border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                              flex: 1,
                            },
                          }}
                        >
                          <ToggleButton value={MaterialPositionReference.WorkHome} aria-label="work home">
                            Work Home
                          </ToggleButton>
                          <ToggleButton value={MaterialPositionReference.Spoilboard} aria-label="spoilboard">
                            Spoilboard
                          </ToggleButton>
                        </ToggleButtonGroup>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <FormControl fullWidth>
                          <InputLabel>Material Type</InputLabel>
                          <Select
                            value={selectedMaterialType}
                            label="Material Type"
                            onChange={(e) => this.handleMaterialTypeChange(e.target.value as MaterialType)}
                          >
                            {Object.values(MaterialType).map((type) => (
                              <MenuItem key={type} value={type}>
                                {type}
                              </MenuItem>
                            ))}
                          </Select>
                        </FormControl>
                      </Grid>
                    </>
                  );
                }

                return (
                  <ObserveState
                    listenTo={currentJob}
                    properties={['materialPositionReference']}
                    control={() => {
                      return (
                        <>
                          <Grid item xs={12} sm={6}>
                            <ToggleButtonGroup
                              value={currentJob.materialPositionReference || MaterialPositionReference.WorkHome}
                              exclusive
                              onChange={(event, newReference) => {
                                if (newReference !== null) {
                                  currentJob.materialPositionReference = newReference;
                                }
                              }}
                              aria-label="material position reference"
                              size="medium"
                              sx={{
                                height: '56px',
                                width: '100%',
                                '& .MuiToggleButton-root': {
                                  height: '56px',
                                  border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                                  flex: 1,
                                  '&.Mui-selected': {
                                    backgroundColor: `${ConfigurationDataColors.Instance.primaryColor} !important`,
                                    color: 'white !important',
                                    borderColor: `${ConfigurationDataColors.Instance.primaryColor} !important`,
                                    '&:hover': {
                                      backgroundColor: `${ConfigurationDataColors.Instance.primaryColor} !important`,
                                    },
                                  },
                                },
                              }}
                            >
                              <ToggleButton value={MaterialPositionReference.WorkHome} aria-label="work home">
                                Work Home
                              </ToggleButton>
                              <ToggleButton value={MaterialPositionReference.Spoilboard} aria-label="spoilboard">
                                Spoilboard
                              </ToggleButton>
                            </ToggleButtonGroup>
                          </Grid>
                          <Grid item xs={12} sm={6}>
                            <FormControl fullWidth>
                              <InputLabel>Material Type</InputLabel>
                              <Select
                                value={selectedMaterialType}
                                label="Material Type"
                                onChange={(e) => this.handleMaterialTypeChange(e.target.value as MaterialType)}
                              >
                                {Object.values(MaterialType).map((type) => (
                                  <MenuItem key={type} value={type}>
                                    {type}
                                  </MenuItem>
                                ))}
                              </Select>
                            </FormControl>
                          </Grid>
                        </>
                      );
                    }}
                  />
                );
              }}
            />

            {/* Third row: Offsets */}
            <ObserveState
              key="material-editor-offsets"
              listenTo={ConfigurationState.Instance}
              properties={['currentJob']}
              control={() => {
                const currentJob = ConfigurationState.Instance.currentJob;

                if (!currentJob) {
                  return null;
                }

                return (
                  <ObserveState
                    listenTo={currentJob}
                    properties={['materialXOffset', 'materialYOffset']}
                    control={() => {
                      const materialXOffset = currentJob.materialXOffset || 0;
                      const materialYOffset = currentJob.materialYOffset || 0;

                      return (
                        <>
                          <Grid item xs={6} sm={6}>
                            <NumberInput
                              fullWidth
                              label="X Offset"
                              value={materialXOffset}
                              onChange={(value) => {
                                currentJob.materialXOffset = value;
                              }}
                              allowNegative={true}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>

                          <Grid item xs={6} sm={6}>
                            <NumberInput
                              fullWidth
                              label="Y Offset"
                              value={materialYOffset}
                              onChange={(value) => {
                                currentJob.materialYOffset = value;
                              }}
                              allowNegative={true}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                        </>
                      );
                    }}
                  />
                );
              }}
            />

            {/* Color Selection */}
            <Grid item xs={12}>
              <Box sx={{ mb: 3 }}>
                {/* Color circles in a scrollable area */}
                <Box sx={{
                  display: 'flex',
                  gap: 1,
                  flexWrap: 'wrap',
                  maxHeight: 120,
                  overflowY: 'auto',
                  mb: 2,
                  p: 1,
                  border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                  borderRadius: 1
                }}>
                  {materialColors.colors.map((colorDef) => (
                    <Tooltip key={colorDef.name} title={`${colorDef.name} - ${colorDef.description}`} arrow>
                      <Box
                        onClick={() => onMaterialChange('materialColor', colorDef.color)}
                        sx={{
                          width: 32,
                          height: 32,
                          borderRadius: '50%',
                          backgroundColor: colorDef.color,
                          border: material.materialColor === colorDef.color
                            ? `3px solid ${ConfigurationDataColors.Instance.primaryColor}`
                            : `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          cursor: 'pointer',
                          transition: 'all 0.2s ease',
                          '&:hover': {
                            transform: 'scale(1.1)',
                            boxShadow: `0 2px 8px ${ConfigurationDataColors.Instance.shadowColor}`
                          }
                        }}
                      />
                    </Tooltip>
                  ))}
                </Box>

                {/* Custom ColorPicker with wider area */}
                <Box sx={{ maxWidth: 200 }}>
                  <ColorPicker
                    label=""
                    value={material.materialColor}
                    onChange={(color) => onMaterialChange('materialColor', color)}
                    size="large"
                  />
                </Box>
              </Box>
            </Grid>
          </Grid>

          {/* Library buttons at bottom */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 2 }}>
            <Box>
              {onLoadFromLibrary && (
                <Button
                  variant="outlined"
                  startIcon={<MaterialIcon />}
                  onClick={onLoadFromLibrary}
                  size="small"
                >
                  Load from Library
                </Button>
              )}
            </Box>
            <Box>
              {onSaveToLibrary && (
                <Link
                  component="button"
                  variant="body2"
                  onClick={onSaveToLibrary}
                  sx={{
                    textDecoration: 'none',
                    '&:hover': {
                      textDecoration: 'underline'
                    }
                  }}
                >
                  Save to Library
                </Link>
              )}
            </Box>
          </Box>
        </Box>

        {/* Divider */}
        <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

        {/* Compact 3D Viewer */}
        <Box sx={{ width: '50%', height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Typography variant="h6" gutterBottom>
            Preview
          </Typography>
          <Box sx={{ flex: 1, minHeight: 400, display: 'flex', flexDirection: 'column' }}>
            <FullSizeCNCViewer
              simulatorViewData={ViewDataFactory.createForContext(ViewNames.MATERIAL_EDITOR)}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
            />
          </Box>
        </Box>
      </Box>
    );
  }
}
