import {
  Add as AddIcon,
  Delete as DeleteIcon,
  InsertDriveFile as FileIcon,
  Folder as FolderIcon,
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Grid,
  IconButton,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { DirectoryBrowserDialog } from '../../../Common/DirectoryBrowserDialog';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function FilesSection() {
  const [newFileType, setNewFileType] = useState('');
  const [newDirectory, setNewDirectory] = useState('');
  const [directoryBrowserOpen, setDirectoryBrowserOpen] = useState(false);

  const handleAddFileType = () => {
    if (newFileType.trim()) {
      const config = ConfigurationData.Instance;
      let fileType = newFileType.trim();

      // Ensure format is .ext (not *.ext or just ext)
      if (fileType.startsWith('*.')) {
        fileType = fileType.substring(1); // Remove the * but keep the .
      } else if (!fileType.startsWith('.')) {
        fileType = `.${fileType}`; // Add the . prefix
      }

      if (!config.fileTypesToMonitor.includes(fileType)) {
        config.fileTypesToMonitor = [...config.fileTypesToMonitor, fileType];
        setNewFileType('');
      }
    }
  };

  const handleRemoveFileType = (fileType: string) => {
    const config = ConfigurationData.Instance;
    config.fileTypesToMonitor = config.fileTypesToMonitor.filter(type => type !== fileType);
  };

  const handleAddDirectory = () => {
    if (newDirectory.trim()) {
      const config = ConfigurationData.Instance;
      if (!config.directoriesToMonitor.includes(newDirectory.trim())) {
        config.directoriesToMonitor = [...config.directoriesToMonitor, newDirectory.trim()];
        setNewDirectory('');
      }
    }
  };

  const handleRemoveDirectory = (directory: string) => {
    const config = ConfigurationData.Instance;
    config.directoriesToMonitor = config.directoriesToMonitor.filter(dir => dir !== directory);
  };

  const handlePickDirectory = () => {
    setDirectoryBrowserOpen(true);
  };

  const handleDirectorySelected = (path: string) => {
    const config = ConfigurationData.Instance;
    if (!config.directoriesToMonitor.includes(path)) {
      config.directoriesToMonitor = [...config.directoriesToMonitor, path];
    }
    setDirectoryBrowserOpen(false);
  };

  return (
    <>
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <SetupChecklistIndicator name="File Monitoring Configuration" />
        </Grid>

        {/* Directories to Monitor */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <FolderIcon color="primary" />
              Directories to Monitor
            </Typography>

            {/* Add Directory */}
            <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
              <TextField
                label="Directory Path"
                variant="outlined"
                size="small"
                fullWidth
                value={newDirectory}
                onChange={(e) => setNewDirectory(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === 'Enter') {
                    handleAddDirectory();
                  }
                }}
                placeholder="C:\Projects\CNC"
              />
              <Button
                variant="outlined"
                onClick={handlePickDirectory}
                sx={{ minWidth: 'auto', px: 1 }}
              >
                <FolderIcon />
              </Button>
              <Button
                variant="contained"
                onClick={handleAddDirectory}
                disabled={!newDirectory.trim()}
                sx={{ minWidth: 'auto', px: 2 }}
              >
                <AddIcon />
              </Button>
            </Box>

            {/* Directory List */}
            <ObserveState
              key="files-directory-list"
              listenTo={ConfigurationData.Instance}
              properties={['directoriesToMonitor']}
              control={() => (
                <Box sx={{ maxHeight: 200, overflow: 'auto' }}>
                  {ConfigurationData.Instance.directoriesToMonitor.length === 0 ? (
                    <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic', p: 2, textAlign: 'center' }}>
                      No directories configured for monitoring
                    </Typography>
                  ) : (
                    ConfigurationData.Instance.directoriesToMonitor.map((directory, index) => (
                      <Box key={index} sx={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        p: 1,
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: 1,
                        mb: 1,
                        '&:last-child': { mb: 0 }
                      }}>
                        <Typography variant="body2" sx={{ flex: 1, wordBreak: 'break-all' }}>
                          {directory}
                        </Typography>
                        <IconButton
                          size="small"
                          onClick={() => handleRemoveDirectory(directory)}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </Box>
                    ))
                  )}
                </Box>
              )}
            />
          </Paper>
        </Grid>

        {/* File Types to Monitor */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <FileIcon color="secondary" />
              File Types to Monitor
            </Typography>

            {/* Add File Type */}
            <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
              <TextField
                label="File Extension"
                variant="outlined"
                size="small"
                fullWidth
                value={newFileType}
                onChange={(e) => setNewFileType(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === 'Enter') {
                    handleAddFileType();
                  }
                }}
                placeholder=".tap or .gcode"
                helperText="Use format: .tap (do NOT include asterisk)"
              />
              <Button
                variant="contained"
                onClick={handleAddFileType}
                disabled={!newFileType.trim()}
                sx={{ minWidth: 'auto', px: 2, alignSelf: 'flex-start', mt: 0.5 }}
              >
                <AddIcon />
              </Button>
            </Box>

            {/* File Types List */}
            <ObserveState
              key="files-type-list"
              listenTo={ConfigurationData.Instance}
              properties={['fileTypesToMonitor']}
              control={() => (
                <Box sx={{ maxHeight: 200, overflow: 'auto' }}>
                  {ConfigurationData.Instance.fileTypesToMonitor.length === 0 ? (
                    <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic', p: 2, textAlign: 'center' }}>
                      No file types configured
                    </Typography>
                  ) : (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                      {ConfigurationData.Instance.fileTypesToMonitor.map((fileType, index) => (
                        <Chip
                          key={index}
                          label={fileType}
                          onDelete={() => handleRemoveFileType(fileType)}
                          deleteIcon={<DeleteIcon />}
                          variant="outlined"
                          color="secondary"
                          size="small"
                        />
                      ))}
                    </Box>
                  )}
                </Box>
              )}
            />
          </Paper>
        </Grid>

      </Grid>

      {/* Directory Browser Dialog */}
      <DirectoryBrowserDialog
        open={directoryBrowserOpen}
        onClose={() => setDirectoryBrowserOpen(false)}
        onSelect={handleDirectorySelected}
        title="Select Directory to Monitor"
        confirmText="Add Directory"
      />
    </>
  );
}
