/// <reference path="../three-jsx.d.ts" />
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-nocheck
import React, { useRef, useState } from 'react';
import { Plane, Vector3 } from 'three';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { ActionBus } from '../../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Box } from './Box';

export interface SpindleProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
  orbitControlsRef?: React.RefObject<any>;
  enableSpindleDrag?: boolean;
  isTopDownView?: () => boolean;
}

export const Spindle: React.FC<SpindleProps> = ({
  simulatorView,
  machineState,
  machineData,
  orbitControlsRef,
  enableSpindleDrag = true,
  isTopDownView
}) => {
  const [highlighted, setHighlighted] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const dragPlaneRef = useRef<Plane>();
  const lastSentLocationRef = useRef<CNCPoint | null>(null);
  const lastMoveActionRef = useRef<MoveAction | null>(null);
  const pointerDownTimeRef = useRef<number>(0);

  // Get configuration state
  const configState = ConfigurationState.Instance;

  // Initialize drag plane (XY plane at current Z position)
  React.useEffect(() => {
    dragPlaneRef.current = new Plane(new Vector3(0, 0, 1), 0);
  }, []);

  // Update highlighting based on spindle drag mode
  React.useEffect(() => {
    if (configState.isSpindleDragging) {
      setHighlighted(true);
    } else {
      setHighlighted(false);
    }
  }, [configState.isSpindleDragging]);

  const handlePointerOver = () => {
    // Only show hover highlighting if we're already in spindle drag mode
    if (configState.isSpindleDragging) {
      setHighlighted(true);
    }

    // Show message when hover begins if spindle drag is enabled, machine is homed,
    // not currently dragging, and camera is in top-down view
    if (enableSpindleDrag && ConfigurationState.Instance.isHomed && !configState.isSpindleDragging && isTopDownView?.()) {
      // // //// console.log('Spindle hover: showing drag message'); // Debug log
      UserMessageQueue.Instance.addMessage('Click and drag to move spindle');
      setHighlighted(true);
    }
  };

  const handlePointerOut = () => {
    // Only handle hover out if we're in hover mode (not drag mode)
    if (!configState.isSpindleDragging) {
      setHighlighted(false);
    }
  };

  const handlePointerDown = (event: any) => {
    event.stopPropagation();

    // Only allow spindle interaction if enableSpindleDrag is true and machine is homed
    if (!enableSpindleDrag || !ConfigurationState.Instance.isHomed) {
      return;
    }

    // Only allow spindle dragging when camera is primarily above (top-down view)
    if (!isTopDownView?.()) {
      return;
    }

    // Record the time when pointer went down
    pointerDownTimeRef.current = Date.now();

    // Enter spindle drag mode immediately if not already active
    if (!configState.isSpindleDragging) {
      configState.selectSpindle();
    }

    // Start dragging immediately on pointer down
    startDragging(event);
  };

  const handlePointerUp = (event: any) => {
    event.stopPropagation();

    if (!enableSpindleDrag) return;

    if (isDragging) {
      // We were dragging, finalize the movement
      stopDragging();

      // Apply the final proposed position to machine state using MoveAction
      if (ConfigurationState.Instance.proposedSpindlePosition) {
        // Check if the proposed position is significantly different from current position
        const currentPos = ConfigurationState.Instance.currentMachinePoint;
        const proposedPos = ConfigurationState.Instance.proposedSpindlePosition;

        const deltaX = Math.abs(proposedPos.x - currentPos.x);
        const deltaY = Math.abs(proposedPos.y - currentPos.y);

        // Check if this position is significantly different from the last sent location
        let deltaFromLastSent = Infinity; // Default to large value if no last sent location
        if (lastSentLocationRef.current) {
          const deltaXFromLast = Math.abs(proposedPos.x - lastSentLocationRef.current.x);
          const deltaYFromLast = Math.abs(proposedPos.y - lastSentLocationRef.current.y);
          deltaFromLastSent = Math.max(deltaXFromLast, deltaYFromLast);
        }

        // Only create move action if movement is greater than 0.25 units from current position 
        // AND greater than 0.25 units from last sent location
        if ((deltaX > 0.25 || deltaY > 0.25) && deltaFromLastSent > 0.25) {
          const moveAction = MoveAction.fromCNCPoint(ConfigurationState.Instance.proposedSpindlePosition, MoveType.Simulator);
          // Add to ActionBus to show UI and handle timing
          ActionBus.Instance.addAction(moveAction);
          // Store this as the last move action so we can cancel it if needed
          lastMoveActionRef.current = moveAction;
          // Remember this location as the last sent
          lastSentLocationRef.current = new CNCPoint(
            proposedPos.x,
            proposedPos.y,
            proposedPos.z,
            proposedPos.coordinateType
          );
          // Don't clear proposed position here - let the MoveAction manage it
        }
        // If movement is too small, do nothing - leave proposed position as is
      }

      // Exit drag mode after dragging completes
      configState.deselectSpindle();
    }
  };

  const startDragging = (event: any) => {
    setIsDragging(true);

    // Cancel any pending move action from previous drag
    if (lastMoveActionRef.current) {
      // Preserve the current proposed position so we don't get a visual jump
      const currentProposedPosition = ConfigurationState.Instance.proposedSpindlePosition;

      // Cancel the previous move action (this will clear timeout and remove from ActionBus)
      lastMoveActionRef.current.cancel();
      lastMoveActionRef.current = null;

      // Restore the proposed position if it existed
      if (currentProposedPosition) {
        ConfigurationState.Instance.proposedSpindlePosition = currentProposedPosition;
      }
    }

    // Disable orbit controls directly
    if (orbitControlsRef?.current) {
      orbitControlsRef.current.enabled = false;
    }

    // Update drag plane to current Z position
    const currentPosition = CoordinateUtil.toSimulator(ConfigurationState.Instance.currentMachinePoint);
    if (dragPlaneRef.current) {
      dragPlaneRef.current.constant = -currentPosition.z;
    }
  };

  const stopDragging = () => {
    setIsDragging(false);

    // Re-enable orbit controls
    if (orbitControlsRef?.current) {
      orbitControlsRef.current.enabled = true;
    }
  };

  const handlePointerMove = (event: any) => {
    if (!isDragging || !dragPlaneRef.current) return;

    event.stopPropagation();

    // Use the intersection point from the event (React Three Fiber provides this)
    if (event.intersections && event.intersections.length > 0) {
      const intersection = event.intersections[0].point;

      // Project this point onto our drag plane
      const projectedPoint = new Vector3();
      dragPlaneRef.current.projectPoint(intersection, projectedPoint);

      // Convert intersection point to machine coordinates
      const machinePoint = CoordinateUtil.toMachineZero(
        new CNCPoint(projectedPoint.x, projectedPoint.y, projectedPoint.z, CoordinateType.Simulator)
      );

      // Check soft limits only if soft limits safety is enabled
      let withinLimits = true;
      if (!configState.softLimitsOff) {
        const softLimitsBox = CoordinateUtil.getSoftLimitsBox(machineState);
        withinLimits = softLimitsBox.contains(machinePoint.x, machinePoint.y);
      }

      if (withinLimits) {
        // Keep current Z, only update X and Y
        const currentZ = ConfigurationState.Instance.currentMachinePoint.z;
        const newPosition = new CNCPoint(
          machinePoint.x,
          machinePoint.y,
          currentZ,
          ConfigurationState.Instance.currentMachinePoint.coordinateType
        );

        // Store the proposed position in machine state
        ConfigurationState.Instance.proposedSpindlePosition = newPosition;
      }
    }
  };

  return (
    <ObserveMultiProperties
      key="spindle-observer"
      listenTo={[
        { object: configState, properties: ['isSpindleDragging', 'proposedSpindlePosition', 'currentMachinePoint'] },
        { object: simulatorView, properties: ['spindle'] },
        { object: ConfigurationDataColors.Instance, properties: ['spindleTransparency', 'spindleColor', 'toolHolderColor', 'zPlateColor'] },
        { object: machineData, properties: ['spindleDiameter', 'spindleLength', 'toolHolderDiameter', 'toolHolderLength', 'zPlateHeight', 'zPlateSideExtension', 'zPlateDepth', 'zPlateVerticalOffset'] }
      ]}
      control={() => {
        const colors = ConfigurationDataColors.Instance;

        // Get current position from machine state
        // currentMachinePoint represents the SPINDLE BOTTOM position in MachineZero coordinates
        const spindleBottomMachineZero = CoordinateUtil.toMachineZero(
          ConfigurationState.Instance.proposedSpindlePosition || ConfigurationState.Instance.currentMachinePoint
        );

        // Convert spindle bottom to simulator coordinates for rendering
        const simulatorPosition = CoordinateUtil.toSimulator(spindleBottomMachineZero);
        const x = simulatorPosition.x;
        const y = simulatorPosition.y;
        const z = simulatorPosition.z;

        // Get spindle and tool holder dimensions from machine data
        const spindleRadius = machineData.spindleDiameter / 2;
        const spindleHeight = machineData.spindleLength;
        const toolHolderRadius = machineData.toolHolderDiameter / 2;
        const toolHolderHeight = machineData.toolHolderLength;

        // Color logic: highlight if in drag mode, being dragged, or hovered
        const spindleColor = configState.isSpindleDragging ? colors.highlightColor :
          (isDragging ? colors.highlightColor :
            (highlighted ? colors.highlightColor : colors.spindleColor));

        const toolHolderColor = configState.isSpindleDragging ? colors.highlightColor :
          (isDragging ? colors.highlightColor :
            (highlighted ? colors.highlightColor : colors.toolHolderColor));

        // Determine cursor style
        const getCursor = () => {
          if (!enableSpindleDrag) return 'default';
          if (isDragging) return 'grabbing';
          if (configState.isSpindleDragging) return 'grab';
          if (isTopDownView?.() && highlighted) return 'pointer';
          return 'default';
        };

        // Calculate opacity for render key
        const spindleOpacity = (simulatorView.spindle === ViewStyle.SemiTransparent && !highlighted && !isDragging && !configState.isSpindleDragging) ? colors.spindleTransparency * 1.5 : 1;

        // Create unique key for React re-rendering when material properties change
        const renderKey = `spindle-${ViewStyle[simulatorView.spindle]}-${spindleOpacity}-${highlighted}-${isDragging}-${configState.isSpindleDragging}-${Date.now()}`;

        // Calculate Z-plate dimensions
        const plateWidth = machineData.spindleDiameter + (2 * machineData.zPlateSideExtension);
        const plateDepth = machineData.zPlateDepth;
        const plateHeight = machineData.zPlateHeight;

        // Z-plate position relative to spindle bottom (group origin at [0, 0, 0])
        // X: centered on spindle (0 offset)
        // Y: behind the spindle body (spindle is rotated 90° so axis is along Y)
        //    Back of spindle is at +spindleRadius, then add half plate depth to center it
        // Z: from top of tool holder (bottom of spindle body) + vertical offset + half plate height to center
        const zPlateRelativeX = 0;
        const zPlateRelativeY = spindleRadius + (plateDepth / 2);
        const zPlateRelativeZ = toolHolderHeight + machineData.zPlateVerticalOffset + (plateHeight / 2);

        const spindleMesh = (
          <group key={renderKey} position={[x, y, z]}>
            {/* Z-Plate - positioned behind the spindle */}
            <Box
              position={[zPlateRelativeX, zPlateRelativeY, zPlateRelativeZ]}
              size={[plateWidth, plateDepth, plateHeight]}
              color={colors.zPlateColor}
              viewStyle={simulatorView.spindle}
              opacity={spindleOpacity}
            />

            {/* Tool Holder - positioned at the reference point (center bottom) */}
            <mesh
              rotation={[Math.PI / 2, 0, 0]}
              position={[0, 0, toolHolderHeight / 2]}
            >
              <cylinderGeometry args={[toolHolderRadius, toolHolderRadius, toolHolderHeight, 16]} />
              <meshStandardMaterial
                color={toolHolderColor}
                transparent={simulatorView.spindle === ViewStyle.SemiTransparent && !highlighted && !isDragging && !configState.isSpindleDragging}
                opacity={(simulatorView.spindle === ViewStyle.SemiTransparent && !highlighted && !isDragging && !configState.isSpindleDragging) ? colors.spindleTransparency * 1.5 : 1}
                wireframe={simulatorView.spindle === ViewStyle.Wireframe}
                metalness={0.7}
                roughness={0.3}
              />
            </mesh>

            {/* Main spindle body - positioned above the tool holder */}
            <mesh
              rotation={[Math.PI / 2, 0, 0]}
              position={[0, 0, toolHolderHeight + spindleHeight / 2]}
            >
              <cylinderGeometry args={[spindleRadius, spindleRadius, spindleHeight, 16]} />
              <meshStandardMaterial
                color={spindleColor}
                transparent={simulatorView.spindle === ViewStyle.SemiTransparent && !highlighted && !isDragging && !configState.isSpindleDragging}
                opacity={(simulatorView.spindle === ViewStyle.SemiTransparent && !highlighted && !isDragging && !configState.isSpindleDragging) ? colors.spindleTransparency * 1.5 : 1}
                wireframe={simulatorView.spindle === ViewStyle.Wireframe}
                metalness={0.7}
                roughness={0.3}
              />
            </mesh>

            {/* Invisible larger collision mesh for easier clicking - covers both spindle and tool holder */}
            <mesh
              onPointerOver={handlePointerOver}
              onPointerOut={handlePointerOut}
              onPointerDown={handlePointerDown}
              onPointerMove={handlePointerMove}
              onPointerUp={handlePointerUp}
              rotation={[Math.PI / 2, 0, 0]}
              style={{ cursor: getCursor() }}
              position={[0, 0, (toolHolderHeight + spindleHeight) / 2]}
            >
              <cylinderGeometry args={[
                Math.max(spindleRadius * 2.5, toolHolderRadius * 2.5, 1),
                Math.max(spindleRadius * 2.5, toolHolderRadius * 2.5, 1),
                toolHolderHeight + spindleHeight,
                16
              ]} />
              <meshBasicMaterial
                transparent={true}
                opacity={0}
                depthWrite={false}
              />
            </mesh>
          </group>
        );

        // Return null if spindle is hidden
        if (simulatorView.spindle === ViewStyle.Hide) {
          return null;
        }

        // Return the spindle mesh without tooltip wrapper
        // Note: Three.js components cannot be wrapped with DOM components like Tooltip
        return spindleMesh;
      }}
    />
  );
};
