import {
  Add as AddIcon,
  Close as CloseIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  Link as LinkIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { Fixture, FixtureLibrary, FixtureType } from '../../../data/Common/FixtureLibrary';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../Common/NumberInput';

const getFixtureTypeLabel = (type: FixtureType): string => {
  switch (type) {
    case FixtureType.SavedPoint:
      return 'Saved Point';
    case FixtureType.SpoilboardCorner:
      return 'Spoilboard Corner';
    case FixtureType.BedCorner:
      return 'Bed Corner';
    case FixtureType.System:
      return 'System';
    case FixtureType.Fixture:
      return 'Fixture';
    default:
      return 'Unknown';
  }
};

interface FixtureDialogProps {
  open: boolean;
  fixture: Fixture | null;
  isNewKnownPoint: boolean;
  onClose: () => void;
  onSave: (fixture: Fixture) => void;
}

const FixtureDialog: React.FC<FixtureDialogProps> = ({ open, fixture, isNewKnownPoint, onClose, onSave }) => {
  const [formData, setFormData] = useState<Fixture>(() => fixture || new Fixture('', '', 0, 0, 0));
  const colors = ConfigurationDataColors.Instance;

  React.useEffect(() => {
    setFormData(fixture || new Fixture('', '', 0, 0, 0));
  }, [fixture]);

  const handleSave = () => {
    if (formData.name.trim()) {
      onSave(formData);
      onClose();
    }
  };

  const handleNumberChange = (field: 'xOffset' | 'yOffset' | 'zOffset') => (value: number) => {
    setFormData(prev => {
      const newFixture = new Fixture(prev.name, prev.fixtureNumber, prev.xOffset, prev.yOffset, prev.zOffset, prev.systemControlled);
      if (field === 'xOffset') newFixture.xOffset = value;
      else if (field === 'yOffset') newFixture.yOffset = value;
      else if (field === 'zOffset') newFixture.zOffset = value;
      return newFixture;
    });
  };

  const handleCaptureCurrentPosition = () => {
    const currentPoint = ConfigurationState.Instance.currentMachinePoint;
    setFormData(prev => {
      const newFixture = new Fixture(
        prev.name,
        prev.fixtureNumber,
        currentPoint.x,
        currentPoint.y,
        currentPoint.z,
        prev.systemControlled
      );
      return newFixture;
    });
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backgroundColor: colors.primaryColor,
        color: colors.lightTextColor,
        py: 2,
        px: 3
      }}>
        {isNewKnownPoint ? 'Add Known Point' : `Edit Fixture Offsets - ${fixture?.name}`}
        <IconButton
          onClick={onClose}
          sx={{
            color: colors.lightTextColor,
            '&:hover': {
              backgroundColor: colors.lightOverlay
            }
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent>
        <Box sx={{ mt: 3 }}>
          {fixture?.isComputed && (
            <Box sx={{ mb: 3, p: 2, backgroundColor: 'info.light', borderRadius: 1 }}>
              <Typography variant="body2" color="info.dark">
                This is a computed known point. The coordinates are automatically calculated and cannot be edited.
              </Typography>
            </Box>
          )}
          <Grid container spacing={3}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Name"
                value={formData.name}
                onChange={(e) => setFormData(prev => {
                  const newFixture = new Fixture(e.target.value, prev.fixtureNumber, prev.xOffset, prev.yOffset, prev.zOffset, prev.systemControlled);
                  return newFixture;
                })}
                InputProps={{ readOnly: !isNewKnownPoint }}
                helperText={isNewKnownPoint ? "Enter a name for this known point" : fixture?.isComputed ? "Computed point names cannot be changed" : "Fixture names are predefined and cannot be changed"}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Fixture Number"
                value={formData.fixtureNumber}
                InputProps={{ readOnly: true }}
                helperText="Fixture numbers are predefined and cannot be changed"
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <NumberInput
                label="X Offset"
                value={formData.xOffset}
                onChange={handleNumberChange('xOffset')}
                precision={3}
                disabled={fixture?.isComputed}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <NumberInput
                label="Y Offset"
                value={formData.yOffset}
                onChange={handleNumberChange('yOffset')}
                precision={3}
                disabled={fixture?.isComputed}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <NumberInput
                label="Z Offset"
                value={formData.zOffset}
                onChange={handleNumberChange('zOffset')}
                precision={3}
                disabled={fixture?.isComputed}
              />
            </Grid>

            {!fixture?.isComputed && (
              <Grid item xs={12}>
                <Button
                  variant="text"
                  startIcon={<LinkIcon />}
                  onClick={handleCaptureCurrentPosition}
                  sx={{
                    color: ConfigurationDataColors.Instance.primaryColor,
                    textTransform: 'none'
                  }}
                >
                  Use Current Machine Position
                </Button>
              </Grid>
            )}
          </Grid>
        </Box>
      </DialogContent>
      <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
        <Button onClick={onClose}>Cancel</Button>
        <Button
          onClick={handleSave}
          variant="contained"
          sx={{
            backgroundColor: colors.primaryColor,
            '&:hover': {
              backgroundColor: colors.primaryColor,
              opacity: 0.9
            }
          }}
        >
          {isNewKnownPoint ? 'Add Known Point' : 'Update Offsets'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export function FixtureLibraryTab() {
  const [library] = useState(() => FixtureLibrary.Instance);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingFixture, setEditingFixture] = useState<Fixture | null>(null);
  const [isNewKnownPoint, setIsNewKnownPoint] = useState(false);

  const handleEditFixture = (fixture: Fixture) => {
    setEditingFixture(fixture);
    setIsNewKnownPoint(false);
    setDialogOpen(true);
  };

  const handleSaveFixture = (fixture: Fixture) => {
    if (isNewKnownPoint) {
      // Create new user-defined known point
      const newFixture = new Fixture(
        fixture.name,
        '', // Empty fixture number for known points
        fixture.xOffset,
        fixture.yOffset,
        fixture.zOffset,
        true,
        FixtureType.SavedPoint,
        true // userDefined = true
      );
      library.addFixture(newFixture);
    } else if (editingFixture) {
      library.updateFixture(editingFixture.name, fixture.xOffset, fixture.yOffset, fixture.zOffset);
    }
  };

  const handleAddKnownPoint = () => {
    const newFixture = new Fixture('New Known Point', '', 0, 0, 0, false, FixtureType.SavedPoint, true);
    setEditingFixture(newFixture);
    setIsNewKnownPoint(true);
    setDialogOpen(true);
  };

  const handleDeleteFixture = (fixture: Fixture) => {
    if (fixture.userDefined) {
      library.removeFixture(fixture.name);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
          Fixtures/Known Points
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={handleAddKnownPoint}
        >
          Add Known Point
        </Button>
      </Box>

      {/* Fixtures Table */}
      <ObserveState
        key="fixture-library-table"
        listenTo={library}
        properties={['fixtures']}
        control={(changedProperties) => {
          return (
            <TableContainer component={Paper} sx={{ backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor }}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Name</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Fixture Number</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>X Offset (mm)</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Y Offset (mm)</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Z Offset (mm)</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Type</TableCell>
                    <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {library.fixtures.map((fixture, index) => (
                    <TableRow key={index}>
                      <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
                        {fixture.name}
                      </TableCell>
                      <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
                        {fixture.fixtureNumber}
                      </TableCell>
                      <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
                        {fixture.xOffset.toFixed(3)}
                      </TableCell>
                      <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
                        {fixture.yOffset.toFixed(3)}
                      </TableCell>
                      <TableCell sx={{ color: ConfigurationDataColors.Instance.darkTextColor }}>
                        {fixture.zOffset.toFixed(3)}
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={getFixtureTypeLabel(fixture.type)}
                          color={
                            fixture.type === FixtureType.System ? 'error' :
                              fixture.type === FixtureType.Fixture ? 'primary' :
                                fixture.type === FixtureType.SavedPoint ? 'success' :
                                  fixture.type === FixtureType.SpoilboardCorner ? 'warning' :
                                    fixture.type === FixtureType.BedCorner ? 'warning' :
                                      'default'
                          }
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        {fixture.userDefined && (
                          <IconButton
                            size="small"
                            onClick={() => handleDeleteFixture(fixture)}
                            sx={{
                              color: 'error.main',
                              mr: 1
                            }}
                            title="Delete known point"
                          >
                            <DeleteIcon />
                          </IconButton>
                        )}
                        <IconButton
                          size="small"
                          onClick={() => handleEditFixture(fixture)}
                          sx={{
                            color: ConfigurationDataColors.Instance.primaryColor
                          }}
                          title="Edit fixture offsets"
                        >
                          <EditIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                  {library.fixtures.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={7} align="center" sx={{ color: 'text.secondary', py: 4 }}>
                        No fixtures defined.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          )
        }}
      />

      {/* Fixture Dialog */}
      <FixtureDialog
        open={dialogOpen}
        fixture={editingFixture}
        isNewKnownPoint={isNewKnownPoint}
        onClose={() => setDialogOpen(false)}
        onSave={handleSaveFixture}
      />
    </Box>
  );
}
