/**
 * Stage for timed action operations (M103/M104)
 */

import { Machine } from '../../machine/Machine';
import { JobStage, StageStatus, StageType } from '../JobStage';

export class TimedActionStage extends JobStage {
    public timeoutSeconds: number;
    public lineNumber: number;
    public gcodeLine: string;
    public description: string;

    constructor(stageNumber: number, timeoutSeconds: number, lineNumber: number, gcodeLine: string, description: string = '') {
        super(stageNumber, StageType.TimedAction, lineNumber - 1, lineNumber - 1);
        this.timeoutSeconds = timeoutSeconds;
        this.lineNumber = lineNumber;
        this.gcodeLine = gcodeLine;
        this.description = description;
    }

    protected async executeStage(callback?: import('../JobStage').StageCallback): Promise<void> {
        // Execute the timed action command
        await Machine.getInstance().program.RunGCodeCommand(this.gcodeLine);

        // Mark as completed
        this.status = StageStatus.Completed;
        this.endTime = new Date();

        // Timed actions continue automatically
        if (callback) {
            await callback.onComplete();
        }
    }

    public getStageName(): string {
        return 'Timed Action';
    }

    public getDisplayName(): string {
        return 'Timed Action';
    }

    public getDescription(): string {
        let desc = `M103 - Programmed Action Timer (Line ${this.lineNumber})\nTimeout: ${this.timeoutSeconds} seconds`;

        if (this.description) {
            desc += `\n${this.description}`;
        }

        return desc;
    }

    public getStageDisplayData(): string[] {
        const data = [
            `M103 - Programmed Action Timer (Line ${this.lineNumber})`,
            `Timeout: ${this.timeoutSeconds} seconds`
        ];

        if (this.description) {
            data.push(this.description);
        }

        return data;
    }
}
