import { useEffect, useState } from 'react';
import * as THREE from 'three';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { Job } from '../../../data/Job';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { GCodeParser } from '../../Views/Milling/gcode/GCodeParser';
import { SimpleColorizer } from '../../Views/Milling/gcode/SegmentColorizer';
import { ToolpathGeometry } from '../../Views/Milling/gcode/ToolpathGeometry';

export interface DryRunToolpathsProps {
    simulatorView: SimulatorView;
    machineState: MachineStateData;
    machineData: MachineData;
    job?: Job; // Optional job - can be null, only use what's passed in
}

/**
 * DryRunToolpaths component - renders dry run G-code toolpaths in 3D space
 * Similar to Toolpaths but uses job.getDryRunGCode() and displays with dry run color
 * Renders based on current work home coordinates
 */
export function DryRunToolpaths({
    simulatorView,
    machineState,
    machineData,
    job // Optional job override
}: DryRunToolpathsProps) {
    const colors = ConfigurationDataColors.Instance;
    const [parsedGCode, setParsedGCode] = useState<THREE.Group | null>(null);

    // Parse dry run G-code when job changes or dry run toolpaths setting changes
    useEffect(() => {
        if (!job?.gcode || simulatorView.dryRunToolpaths === false) {
            setParsedGCode(null);
            return;
        }

        try {
            // Get the dry run G-code from the job
            const dryRunGCode = job.getDryRunGCode();

            if (!dryRunGCode) {
                setParsedGCode(null);
                return;
            }

            // Use custom colorizer that overrides colors with dry run color
            const dryRunColor = new THREE.Color(colors.dryRunToolpathColor);
            const colorizer = new SimpleColorizer();
            // Override all colors with dry run color
            colorizer.travelColor = dryRunColor;
            colorizer.extrusionColor = dryRunColor;
            colorizer.rapidColor = dryRunColor;

            // Use our custom G-code parser
            const parser = new GCodeParser(colorizer);
            const parseResult = parser.parse(dryRunGCode);

            if (parseResult.linePoints.length > 0) {
                // Create group for dry run toolpath
                const toolpathGroup = new THREE.Group();

                // Create simple line geometry from line points
                const lineGeometry = new ToolpathGeometry();
                lineGeometry.addPoints(parseResult.linePoints);

                // Create line material with vertex colors
                // Note: linewidth > 1 only works on some platforms (not WebGL)
                // For true thick lines, use MeshLine or THREE.Line2
                const lineMaterial = new THREE.LineBasicMaterial({
                    vertexColors: true,
                    linewidth: 6  // 3x the original size (though limited by WebGL)
                });

                // Create line segments object
                const toolpathLines = new THREE.LineSegments(lineGeometry, lineMaterial);
                toolpathGroup.add(toolpathLines);

                setParsedGCode(toolpathGroup);
            } else {
                setParsedGCode(null);
            }
        } catch (error) {
            setParsedGCode(null);
        }
    }, [
        job,
        job?.gcode,
        simulatorView.dryRunToolpaths,
        // Watch for changes to dry run settings on the job
        job?.dryRunToolpathMode,
        job?.dryRunToolMode,
        job?.dryRunZ,
        job?.dryRunChangeSpeed,
        job?.dryRunSpeed,
        colors.dryRunToolpathColor
    ]);

    return (
        <ObserveMultiProperties
            key="dry-run-toolpaths-observer"
            listenTo={[
                { object: simulatorView, properties: ['dryRunToolpaths'] },
                { object: machineState, properties: ['currentWorkZero'] },
                { object: colors, properties: ['dryRunToolpathColor'] }
            ]}
            control={() => {
                // Don't render if dry run toolpaths are disabled or no G-code is available
                if (!simulatorView.dryRunToolpaths || !parsedGCode) {
                    return null;
                }

                // G-code coordinates are relative to WorkZero (absolute position on workpiece)
                // Position the group at WorkZero (0,0,0) in simulator space
                const workZeroOrigin = CoordinateUtil.toSimulator(
                    new CNCPoint(0, 0, 0, CoordinateType.WorkZero)
                );
                const workHomeOffset: [number, number, number] = [
                    workZeroOrigin.x,
                    workZeroOrigin.y,
                    workZeroOrigin.z
                ];

                return (
                    <group position={workHomeOffset}>
                        <primitive
                            object={parsedGCode.clone()}
                            scale={[1, 1, 1]}
                        />
                    </group>
                );
            }}
        />
    );
}
