import {
  AccountTree as FlowIcon,
  Home as HomeIcon,
  HomeOutlined as HomeOutlinedIcon,
  Hardware as MachineIcon,
  PlayArrow as RunIcon,
  StarBorder as StarBorderIcon,
  Star as StarIcon,
  Build as ToolIcon,
  TouchApp as TouchIcon,
} from '@mui/icons-material';
import {
  Box,
  Button,
  Card,
  CardContent,
  Grid,
  IconButton,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ActionData } from '../../data/ActionData';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IOStateData } from '../../data/IOStateData';
import { UserActionData } from '../../data/UserActionData';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { DefaultUserActions, UserActionRegistry, type IUserAction } from '../../utils/userActions';

interface ActionsPanelProps {
  onViewChange?: (view: string) => void;
}

interface ActionLinkProps {
  action: IUserAction;
  onClick: (actionId: string) => void;
  showUsageCount?: boolean;
}

const ActionLink: React.FC<ActionLinkProps> = ({
  action,
  onClick,
  showUsageCount = false
}) => {
  const [isHovering, setIsHovering] = useState(false);

  return (
    <ObserveMultiProperties
      key={`actions-panel-action-link-${action.id}`}
      listenTo={[
        { object: ConfigurationState.Instance, properties: ['isHomed', 'isJobRunning'] },
        { object: IOStateData.Instance, properties: ['outputs'] }
      ]}
      control={() => {
        const userActionData = UserActionData.Instance;
        const isFavorite = userActionData.isFavorite(action.id);
        const isOnHomePage = userActionData.isOnHomePage(action.id);
        const isDefaultHomeAction = action.isDefaultHomeAction || false;
        const isAvailable = action.isAvailable ? action.isAvailable() : true;
        const isDisabled = !isAvailable;
        const usageStats = userActionData.getActionUsage(action.id);
        const usageCount = usageStats?.count || 0;

        const handleFavoriteClick = (e: React.MouseEvent) => {
          e.stopPropagation();
          userActionData.toggleFavorite(action.id);
        };

        const handleHomePageClick = (e: React.MouseEvent) => {
          e.stopPropagation();
          userActionData.toggleHomePage(action.id);
        };

        return (
          <Box
            onMouseEnter={() => setIsHovering(true)}
            onMouseLeave={() => setIsHovering(false)}
            sx={{
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              width: '100%',
            }}
          >
            <Button
              onClick={() => !isDisabled && onClick(action.id)}
              disabled={isDisabled}
              fullWidth
              variant="outlined"
              sx={{
                justifyContent: 'space-between',
                gap: 1.5,
                py: 1.5,
                px: 2,
                pr: isHovering ? 9 : 2,
                minHeight: 44, // Touch-friendly minimum height
                textTransform: 'none',
                borderColor: isFavorite ? ConfigurationDataColors.Instance.primaryColor : 'divider',
                backgroundColor: isFavorite ? `${ConfigurationDataColors.Instance.primaryColor}15` : 'transparent',
                color: 'inherit',
                '&:hover': {
                  backgroundColor: isFavorite ? `${ConfigurationDataColors.Instance.primaryColor}25` : 'action.hover',
                  borderColor: 'primary.main',
                },
                transition: 'padding-right 0.2s, border-color 0.2s, background-color 0.2s',
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                {action.renderButton(true)}
              </Box>
              {usageCount > 0 && (
                <Typography variant="caption" sx={{ color: 'text.secondary', ml: 'auto', mr: isHovering ? 6 : 0 }}>
                  ({usageCount})
                </Typography>
              )}
            </Button>

            {/* Home icon - shows on hover or if on home page (only if not a default home action) */}
            {!isDefaultHomeAction && (isHovering || isOnHomePage) && (
              <IconButton
                size="small"
                onClick={handleHomePageClick}
                sx={{
                  position: 'absolute',
                  right: 20,
                  top: '50%',
                  transform: 'translateY(-50%)',
                  padding: 0.5,
                  transition: 'all 0.2s',
                  '&:hover': {
                    backgroundColor: 'action.hover',
                    transform: 'translateY(-50%) scale(1.1)',
                  },
                }}
              >
                {isOnHomePage ? (
                  <HomeIcon sx={{
                    fontSize: 16,
                    color: 'primary.main' // Blue color for home page
                  }} />
                ) : (
                  <HomeOutlinedIcon sx={{
                    fontSize: 16,
                    color: 'text.secondary',
                    '&:hover': { color: 'primary.main' }
                  }} />
                )}
              </IconButton>
            )}

            {/* Star icon - shows on hover or if favorited */}
            {(isHovering || isFavorite) && (
              <IconButton
                size="small"
                onClick={handleFavoriteClick}
                sx={{
                  position: 'absolute',
                  right: 0,
                  top: '50%',
                  transform: 'translateY(-50%)',
                  padding: 0.5,
                  transition: 'all 0.2s',
                  '&:hover': {
                    backgroundColor: 'action.hover',
                    transform: 'translateY(-50%) scale(1.1)',
                  },
                }}
              >
                {isFavorite ? (
                  <StarIcon sx={{
                    fontSize: 16,
                    color: 'warning.main' // Gold color for favorites
                  }} />
                ) : (
                  <StarBorderIcon sx={{
                    fontSize: 16,
                    color: 'text.secondary',
                    '&:hover': { color: 'warning.main' }
                  }} />
                )}
              </IconButton>
            )}
          </Box>
        );
      }}
    />
  );
};

const ActionSection: React.FC<{
  title: string;
  icon: React.ComponentType<any>;
  actions: IUserAction[];
  onActionClick: (actionId: string) => void;
  showUsageCount?: boolean;
}> = ({ title, icon: Icon, actions, onActionClick, showUsageCount = false }) => {
  // Sort actions by usage count (most popular first)
  const userActionData = UserActionData.Instance;
  const sortedActions = [...actions].sort((a, b) => {
    const aUsage = userActionData.getActionUsage(a.id)?.count || 0;
    const bUsage = userActionData.getActionUsage(b.id)?.count || 0;
    return bUsage - aUsage;
  });

  return (
    <Card
      variant="outlined"
      sx={{
        mb: 0,
        height: 'fit-content',
        transition: 'box-shadow 0.2s',
        '&:hover': {
          boxShadow: 3,
          borderColor: 'primary.light'
        }
      }}
    >
      <CardContent sx={{ p: 2.5, '&:last-child': { pb: 2.5 } }}>
        <Box sx={{
          display: 'flex',
          alignItems: 'center',
          mb: 1.5,
          mx: -2.5,
          mt: -2.5,
          px: 2.5,
          py: 1.5,
          backgroundColor: ConfigurationDataColors.Instance.primaryColor
        }}>
          <Typography variant="h6" sx={{
            fontWeight: 600,
            fontSize: '16px',
            color: ConfigurationDataColors.Instance.lightTextColor
          }}>
            {title}
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25 }}>
          {sortedActions.map((action) => (
            <ActionLink
              key={action.id}
              action={action}
              onClick={onActionClick}
              showUsageCount={showUsageCount}
            />
          ))}
        </Box>
      </CardContent>
    </Card>
  );
};

export function ActionsPanel({ onViewChange }: ActionsPanelProps) {
  const registry = UserActionRegistry.Instance;

  // Re-initialize with view change callback
  React.useEffect(() => {
    DefaultUserActions.initialize(onViewChange);
  }, [onViewChange]);

  const handleActionClick = async (actionId: string) => {
    try {
      await registry.executeAction(actionId);
      // Record that this action was used
      UserActionData.Instance.recordActionUsage(actionId);
    } catch (error) {
      console.error('Failed to execute action:', error);
    }
  };

  const getCategoryIcon = (category: string): React.ComponentType<any> => {
    const iconMap: { [key: string]: React.ComponentType<any> } = {
      'Run Job': RunIcon,
      'Measure Z': TouchIcon,
      'Machine Homing': HomeIcon,
      'Machine Setup': HomeIcon,
      'Machine Controls': MachineIcon,
      'Tool Management': ToolIcon,
      'Custom Routines': FlowIcon,
    };
    return iconMap[category] || ToolIcon;
  };

  return (
    <ObserveMultiProperties
      key="actions-panel"
      listenTo={[
        { object: ActionData.Instance, properties: ['allActions', 'actionsByCategory', 'isInitialized'] },
        { object: ConfigurationData.Instance, properties: ['systemConfigurationUnlocked'] },
        { object: ConfigurationState.Instance, properties: ['isHomed', 'isJobRunning'] },
        { object: UserActionData.Instance, properties: ['favoriteActionIds', 'homePageActionIds'] },
        { object: IOStateData.Instance, properties: ['outputs'] }
      ]}
      control={() => {
        const actionData = ActionData.Instance;

        // Don't render until actions are initialized
        if (!actionData.isInitialized) {
          return (
            <Box sx={{ p: 2, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Loading actions...
              </Typography>
            </Box>
          );
        }

        // Don't filter out any categories - all actions should be available
        const actionsByCategory = actionData.actionsByCategory;

        // Balance sections across two columns by action count
        const categories = Array.from(actionsByCategory.entries());
        const leftColumn: [string, IUserAction[]][] = [];
        const rightColumn: [string, IUserAction[]][] = [];
        let leftCount = 0;
        let rightCount = 0;

        // Greedy algorithm: add each category to the column with fewer actions
        categories.forEach(([category, actions]) => {
          if (leftCount <= rightCount) {
            leftColumn.push([category, actions]);
            leftCount += actions.length;
          } else {
            rightColumn.push([category, actions]);
            rightCount += actions.length;
          }
        });

        return (
          <Box sx={{ p: 2, height: '100%', overflow: 'auto' }}>
            {actionsByCategory.size === 0 && (
              <Card variant="outlined" sx={{ p: 3, textAlign: 'center' }}>
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                  No actions available
                </Typography>
              </Card>
            )}

            {/* Regular Category Sections - Two Column Stacked Layout */}
            <Grid container spacing={1}>
              <Grid item xs={12} md={6}>
                {/* Left Column Stack */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                  {leftColumn.map(([category, actions]) => (
                    <ActionSection
                      key={category}
                      title={category}
                      icon={getCategoryIcon(category)}
                      actions={actions}
                      onActionClick={handleActionClick}
                    />
                  ))}
                </Box>
              </Grid>
              <Grid item xs={12} md={6}>
                {/* Right Column Stack */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                  {rightColumn.map(([category, actions]) => (
                    <ActionSection
                      key={category}
                      title={category}
                      icon={getCategoryIcon(category)}
                      actions={actions}
                      onActionClick={handleActionClick}
                    />
                  ))}
                </Box>
              </Grid>
            </Grid>
          </Box>
        );
      }}
    />
  );
}
