import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { CNCPoint } from '../../../../data/CNCPoint';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { MovementCoordinateType } from '../../../../machine/ICNCMovement';
import { Machine } from '../../../../machine/Machine';
import { MoveStrategy } from '../../../../machine/MoveStrategy';
import { CoordinateOperations } from '../../../../utils/CoordinateOperations';
import { CoordinateUtil } from '../../../../utils/CoordinateUtil';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { JogControls } from '../../../Common/JogControls';
import { NumberInput } from '../../../Common/NumberInput';
import { WizardStep } from '../../../Wizard/WizardStep';
import { SurfaceSpoilboardWizard } from '../SurfaceSpoilboardWizard';
import { TouchOffZStep } from './TouchOffZStep';

export class ConfirmDimensionsStep extends WizardStep {
    constructor(wizard: SurfaceSpoilboardWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Surface Spoilboard - Confirm Dimensions';
    }

    nextStep(): WizardStep | null {
        return new TouchOffZStep(this.wizard as SurfaceSpoilboardWizard, this);
    }

    backStep(): WizardStep | null {
        return null;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="confirm-dimensions-step"
                listenTo={MachineStateData.Instance}
                properties={['spoilBoardWidth', 'spoilBoardYLength']}
                control={() => <ConfirmDimensionsStepComponent step={this} />}
            />
        );
    }
}

interface ConfirmDimensionsStepComponentProps {
    step: ConfirmDimensionsStep;
}

function ConfirmDimensionsStepComponent({ step }: ConfirmDimensionsStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineData = MachineData.Instance;
    const machineState = MachineStateData.Instance;
    const wizard = step.wizard as SurfaceSpoilboardWizard;

    const handleMoveToCorner = async () => {
        try {
            // Get spoilboard box to find the corner position (X/Y)
            const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);

            // Get maximum Z height (safe travel height)
            const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);

            // Move to spoilboard corner at maximum Z height
            const targetPoint = new CNCPoint(
                spoilboardBox.origin.x,
                spoilboardBox.origin.y,
                zMax,
                CoordinateType.MachineZero
            );

            const machine = Machine.getInstance();
            await machine.movement.MoveTo(targetPoint, MovementCoordinateType.Machine, undefined, undefined, MoveStrategy.ZSeparate);

        } catch (error) {
            Logger.Instance.logError(LogCategory.Machine, 'Failed to move to spoilboard corner:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to move to spoilboard corner');
        }
    };

    const handleNext = async () => {
        try {
            // Set work zero for X and Y axes (makes current position the spoilboard corner)
            CoordinateOperations.setWorkZero('X');
            CoordinateOperations.setWorkZero('Y');


            // Advance to next step
            wizard.advanceToNextStep();
        } catch (error) {
            Logger.Instance.logError(LogCategory.Machine, 'Failed to set spoilboard corner:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to set spoilboard corner');
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Position the spindle at the front-left corner of the spoilboard area to surface.
                </Typography>

                <Box sx={{
                    display: 'flex',
                    gap: 2,
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor
                }}>
                    <Box sx={{ flex: 1, display: 'flex', justifyContent: 'center' }}>
                        <JogControls />
                    </Box>
                    <Box sx={{ display: 'flex', alignItems: 'flex-end', pb: 1 }}>
                        <Button
                            variant="contained"
                            onClick={handleMoveToCorner}
                        >
                            Move to Spoilboard Corner
                        </Button>
                    </Box>
                </Box>

                <Box sx={{ display: 'flex', gap: 2, mt: 2 }}>
                    <NumberInput
                        label="Spoilboard Width (X, inches)"
                        sx={{ width: 200 }}
                        value={machineState.spoilBoardWidth}
                        onChange={(value) => {
                            machineState.spoilBoardWidth = value;
                        }}
                        allowNegative={false}
                        min={1}
                        max={machineData.bedWidth}
                        precision={2}
                    />

                    <NumberInput
                        label="Spoilboard Length (Y, inches)"
                        sx={{ width: 200 }}
                        value={machineState.spoilBoardYLength}
                        onChange={(value) => {
                            machineState.spoilBoardYLength = value;
                        }}
                        allowNegative={false}
                        min={1}
                        max={machineData.bedLength}
                        precision={2}
                    />
                </Box>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="outlined"
                    onClick={() => wizard.cancelWizard()}
                >
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleNext}
                >
                    Next: Touch Off Z
                </Button>
            </Box>
        </Box>
    );
}
