import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying spoil board configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the spoil board dimensions and position are correctly configured.
 */
export class SpoilBoardChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Spoil Board',
            'Configure spoil board dimensions and position for workpiece support'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured the spoil board correctly
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if spoil board is correctly configured
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new SpoilBoardChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
