import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import RefreshIcon from '@mui/icons-material/Refresh';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    Grid,
    IconButton,
    MenuItem,
    Paper,
    Select,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { SetupChecklistIndicator } from '../../../components/Common/SetupChecklistIndicator';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { IOStateData } from '../../../data/IOStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Machine } from '../../../machine/Machine';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { SymbolNameWithUsageTooltip } from '../components/SymbolNameWithUsageTooltip';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { DefaultPLCOutputs } from '../data/io/DefaultPLCOutputs';
import { PLCOutput } from '../data/io/PLCOutput';

interface OutputDialogProps {
    open: boolean;
    output: PLCOutput | null;
    availableOutputs: number[];
    onClose: () => void;
    onSave: (output: PLCOutput, outputNumber: number | null) => void;
}

function OutputDialog({ open, output, availableOutputs, onClose, onSave }: OutputDialogProps) {
    const plcProgram = PLCProgram.Instance(PLCProgramType.System);
    const [selectedOutputs, setSelectedOutputs] = useState<Set<string>>(new Set());
    const [showCustomDialog, setShowCustomDialog] = useState(false);
    const defaultOutputs = DefaultPLCOutputs.getDefaults();

    useEffect(() => {
        if (open && !output) {
            const currentNames = new Set(plcProgram.outputs.map((o: PLCOutput) => o.centroidName));
            setSelectedOutputs(currentNames);
            setShowCustomDialog(false);
        } else if (output) {
            setShowCustomDialog(true);
        }
    }, [open, output, plcProgram.outputs]);

    const handleToggleOutput = (centroidName: string) => {
        const newSelected = new Set(selectedOutputs);
        if (newSelected.has(centroidName)) {
            newSelected.delete(centroidName);
        } else {
            newSelected.add(centroidName);
        }
        setSelectedOutputs(newSelected);
    };

    const handleSaveMultiple = () => {
        if (!plcProgram) return;

        const defaultOutputMap = new Map(defaultOutputs.map(dout => [dout.centroidName, dout]));

        const toRemove = plcProgram.outputs.filter((output: PLCOutput) => !selectedOutputs.has(output.centroidName));
        toRemove.forEach((output: PLCOutput) => {
            const index = plcProgram.outputs.indexOf(output);
            if (index > -1) {
                plcProgram.outputs.splice(index, 1);
            }
        });

        const existingNames = new Set(plcProgram.outputs.map((o: PLCOutput) => o.centroidName));
        selectedOutputs.forEach(centroidName => {
            if (!existingNames.has(centroidName) && defaultOutputMap.has(centroidName)) {
                const defaultOutput = defaultOutputMap.get(centroidName)!;
                plcProgram.outputs.push(defaultOutput.clone());
            }
        });

        StateManager.propertyChanged(plcProgram, 'outputs');
        onClose();
    };

    const defaultOutputNames = new Set(defaultOutputs.map(dout => dout.centroidName));
    const currentCustomOutputs = plcProgram.outputs.filter((o: PLCOutput) => !defaultOutputNames.has(o.centroidName));

    // Group default outputs by category
    const outputsByCategory = defaultOutputs.reduce((acc, output) => {
        const category = output.category || 'General';
        if (!acc[category]) {
            acc[category] = [];
        }
        acc[category].push(output);
        return acc;
    }, {} as Record<string, typeof defaultOutputs>);

    // Sort categories alphabetically
    const sortedCategories = Object.keys(outputsByCategory).sort();

    return (
        <>
            <Dialog open={open && !showCustomDialog} onClose={onClose} maxWidth="md" fullWidth>
                <DialogTitle>Manage Outputs</DialogTitle>
                <Box sx={{ px: 3, pt: 2, pb: 1, borderBottom: '1px solid', borderColor: 'divider', display: 'flex', justifyContent: 'flex-end' }}>
                    <Button
                        variant="outlined"
                        color="primary"
                        onClick={() => setShowCustomDialog(true)}
                        sx={{ textTransform: 'none' }}
                    >
                        + Add Custom Output
                    </Button>
                </Box>
                <DialogContent>
                    <Box>
                        <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold', mt: 2 }}>
                            Default Outputs (click to toggle)
                        </Typography>

                        {sortedCategories.map(category => (
                            <Box key={category} sx={{ mb: 3 }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'text.secondary', mb: 1 }}>
                                    {category}
                                </Typography>
                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                    {outputsByCategory[category].map((dout) => {
                                        const isSelected = selectedOutputs.has(dout.centroidName);
                                        return (
                                            <Button
                                                key={dout.centroidName}
                                                variant={isSelected ? 'contained' : 'outlined'}
                                                color={isSelected ? 'primary' : 'inherit'}
                                                onClick={() => handleToggleOutput(dout.centroidName)}
                                                sx={{ textTransform: 'none' }}
                                            >
                                                {dout.name}
                                            </Button>
                                        );
                                    })}
                                </Box>
                            </Box>
                        ))}

                        {currentCustomOutputs.length > 0 && (
                            <>
                                <Divider sx={{ my: 2 }} />
                                <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                    Custom Outputs (click to remove)
                                </Typography>
                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                                    {currentCustomOutputs.map((co: PLCOutput) => (
                                        <Button
                                            key={co.centroidName}
                                            variant="contained"
                                            color="secondary"
                                            onClick={() => handleToggleOutput(co.centroidName)}
                                            sx={{ textTransform: 'none' }}
                                        >
                                            {co.name} (Custom)
                                        </Button>
                                    ))}
                                </Box>
                            </>
                        )}
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={onClose}>Cancel</Button>
                    <Button
                        onClick={handleSaveMultiple}
                        variant="contained"
                        color="primary"
                    >
                        Save
                    </Button>
                </DialogActions>
            </Dialog>

            <CustomOutputDialog
                open={showCustomDialog}
                output={output}
                availableOutputs={availableOutputs}
                onClose={() => {
                    setShowCustomDialog(false);
                    if (output) {
                        onClose();
                    }
                }}
                onSave={(customOutput, number) => {
                    const existingIndex = plcProgram.outputs.findIndex((o: PLCOutput) => o.centroidName === customOutput.centroidName);
                    if (existingIndex > -1) {
                        plcProgram.outputs[existingIndex] = customOutput;
                        plcProgram.outputs[existingIndex].number = number;
                    } else {
                        customOutput.number = number;
                        plcProgram.outputs.push(customOutput);
                    }
                    StateManager.propertyChanged(plcProgram, 'outputs');

                    const newSelected = new Set(selectedOutputs);
                    newSelected.add(customOutput.centroidName);
                    setSelectedOutputs(newSelected);

                    setShowCustomDialog(false);

                    if (output) {
                        onClose();
                    }
                }}
            />
        </>
    );
}

function CustomOutputDialog({ open, output, availableOutputs, onClose, onSave }: OutputDialogProps) {
    const [workingOutput, setWorkingOutput] = useState<PLCOutput>(new PLCOutput());
    const [editingCentroidName, setEditingCentroidName] = useState('');
    const [outputNumber, setOutputNumber] = useState<number | null>(null);
    const plcProgram = PLCProgram.Instance(PLCProgramType.System);
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    useEffect(() => {
        if (open) {
            if (output) {
                setWorkingOutput(output.clone());
                // Remove _O suffix for editing
                let name = output.centroidName;
                if (name.endsWith('_O')) {
                    name = name.slice(0, -2);
                }
                setEditingCentroidName(name);
                setOutputNumber(output.number);
            } else {
                setWorkingOutput(new PLCOutput());
                setEditingCentroidName('');
                setOutputNumber(null);
            }
        }
    }, [open, output]);

    const handleCentroidNameFocus = () => {
        // Remove _O suffix when focusing
        let name = editingCentroidName;
        if (name.endsWith('_O')) {
            name = name.slice(0, -2);
        }
        setEditingCentroidName(name);
    };

    const handleCentroidNameBlur = () => {
        // Add _O suffix and uppercase when leaving field
        let name = editingCentroidName.trim();
        if (name) {
            name = name.toUpperCase();
            if (!name.endsWith('_O')) {
                name = name + '_O';
            }
            workingOutput.centroidName = name;
            setEditingCentroidName(name);
        }
    };

    const handleSave = () => {
        if (!workingOutput.name.trim()) {
            return;
        }
        if (!editingCentroidName.trim()) {
            return;
        }
        // Ensure centroid name has _O suffix
        let finalName = editingCentroidName.trim().toUpperCase();
        if (!finalName.endsWith('_O')) {
            finalName = finalName + '_O';
        }
        workingOutput.centroidName = finalName;
        onSave(workingOutput, outputNumber);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>{output ? 'Edit Custom Output' : 'Add Custom Output'}</DialogTitle>
            <ObserveState
                key="custom-output-dialog-form"
                listenTo={workingOutput}
                properties={['centroidName', 'name', 'activeText', 'inactiveText', 'onCommand', 'offCommand']}
                control={() => (
                    <>
                        <DialogContent>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
                                <TextField
                                    label="Centroid Name"
                                    value={editingCentroidName}
                                    onChange={(e) => setEditingCentroidName(e.target.value)}
                                    onFocus={handleCentroidNameFocus}
                                    onBlur={handleCentroidNameBlur}
                                    fullWidth
                                    required
                                    helperText="PLC variable name. _O suffix will be added automatically."
                                />

                                <TextField
                                    label="Display Name"
                                    value={workingOutput.name}
                                    onChange={(e) => workingOutput.name = e.target.value}
                                    fullWidth
                                    required
                                />

                                <TextField
                                    label="Active Text"
                                    value={workingOutput.activeText}
                                    onChange={(e) => workingOutput.activeText = e.target.value}
                                    fullWidth
                                />

                                <TextField
                                    label="Inactive Text"
                                    value={workingOutput.inactiveText}
                                    onChange={(e) => workingOutput.inactiveText = e.target.value}
                                    fullWidth
                                />

                                <Divider sx={{ my: 1 }} />

                                <Typography variant="subtitle2" gutterBottom>
                                    Custom G-Code Commands (Optional)
                                </Typography>
                                <Typography variant="caption" color="textSecondary" gutterBottom sx={{ display: 'block', mb: 1 }}>
                                    Leave empty to use standard M94/M95 commands. Use custom commands for outputs like spindle (M3/M5) or coolant (M7/M9).
                                </Typography>

                                <Box sx={{ display: 'flex', gap: 2 }}>
                                    <TextField
                                        label="ON Command"
                                        value={workingOutput.onCommand}
                                        onChange={(e) => workingOutput.onCommand = e.target.value.toUpperCase()}
                                        fullWidth
                                        placeholder="M3"
                                        helperText="G-code to turn ON"
                                    />
                                    <TextField
                                        label="OFF Command"
                                        value={workingOutput.offCommand}
                                        onChange={(e) => workingOutput.offCommand = e.target.value.toUpperCase()}
                                        fullWidth
                                        placeholder="M5"
                                        helperText="G-code to turn OFF"
                                    />
                                </Box>





                                <Box>
                                    <Typography variant="body2" gutterBottom>
                                        Assign Output Number:
                                    </Typography>
                                    <Select
                                        fullWidth
                                        value={outputNumber ?? ''}
                                        displayEmpty
                                        onChange={(e) => setOutputNumber(e.target.value === '' ? null : Number(e.target.value))}
                                    >
                                        <MenuItem value="">
                                            <em>Unassigned</em>
                                        </MenuItem>
                                        {availableOutputs.map((num) => {
                                            const isAssigned = plcProgram.outputs.some(
                                                (o: PLCOutput) => o.number === num && o.centroidName !== output?.centroidName
                                            );
                                            return (
                                                <MenuItem
                                                    key={num}
                                                    value={num}
                                                    sx={{
                                                        color: isAssigned ? 'text.disabled' : 'text.primary',
                                                        fontStyle: isAssigned ? 'italic' : 'normal'
                                                    }}
                                                >
                                                    {num}{isAssigned ? ' (in use)' : ''}
                                                </MenuItem>
                                            );
                                        })}
                                    </Select>
                                </Box>
                            </Box>
                        </DialogContent>
                        <DialogActions>
                            <Button onClick={onClose}>Cancel</Button>
                            <Button
                                onClick={handleSave}
                                variant="contained"
                                sx={{
                                    backgroundColor: colors.primaryColor,
                                    '&:hover': {
                                        backgroundColor: colors.primaryColor,
                                        opacity: 0.9,
                                    },
                                }}
                            >
                                Save
                            </Button>
                        </DialogActions>
                    </>
                )}
            />
        </Dialog>
    );
}

export function OutputsTab(): React.ReactElement {
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingOutput, setEditingOutput] = useState<PLCOutput | null>(null);
    const [availableOutputs, setAvailableOutputs] = useState<number[]>([]);
    const [bulkIOStates, setBulkIOStates] = useState<{ inputs: Record<number, boolean>, outputs: Record<number, boolean>, readAt: Date } | null>(null);
    const [isRefreshing, setIsRefreshing] = useState(false);

    useEffect(() => {
        loadAvailableOutputs();
        loadBulkIOStates();
    }, []);

    const loadAvailableOutputs = async () => {
        try {
            const machine = Machine.getInstance();
            const availableNumbers = await machine.io.GetAvailableOutputs();
            setAvailableOutputs(availableNumbers);
        } catch (error) {
            console.error('Failed to load available outputs:', error);
            setAvailableOutputs([]);
        }
    };

    const loadBulkIOStates = async () => {
        setIsRefreshing(true);
        try {
            const machine = Machine.getInstance();
            const states = await machine.io.GetBulkIOStates();
            setBulkIOStates(states);

            // Update IOStateData with the bulk states
            const ioStateData = IOStateData.Instance;
            Object.entries(states.inputs).forEach(([num, isOn]) => {
                const input = ioStateData.getInputByNumber(parseInt(num));
                if (input) {
                    input.isActive = isOn;
                }
            });
            Object.entries(states.outputs).forEach(([num, isOn]) => {
                const output = ioStateData.getOutputByNumber(parseInt(num));
                if (output) {
                    output.isActive = isOn;
                }
            });

        } catch (error) {
            console.error('Failed to load bulk I/O states:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load I/O states');
        } finally {
            setIsRefreshing(false);
        }
    };

    const plcProgram = PLCProgram.Instance(PLCProgramType.System);

    const handleAddOutput = () => {
        setEditingOutput(null);
        setDialogOpen(true);
    };

    const handleDeleteOutput = async (output: PLCOutput) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(
            `output "${output.name}"`
        );
        if (confirmed && plcProgram) {
            const index = plcProgram.outputs.indexOf(output);
            if (index > -1) {
                plcProgram.outputs.splice(index, 1);
                StateManager.propertyChanged(plcProgram, 'outputs');
            }
        }
    };

    const isNumberAssigned = (num: number, currentOutputCentroidName?: string) => {
        if (!plcProgram) return false;
        return plcProgram.outputs.some(
            (output: PLCOutput) => output.number === num && output.centroidName !== currentOutputCentroidName
        );
    };

    const getAssignedOutputs = () => {
        if (!plcProgram) return [];
        return plcProgram.outputs
            .filter((output: PLCOutput) => output.number !== null)
            .sort((a: PLCOutput, b: PLCOutput) => (a.number ?? 0) - (b.number ?? 0));
    };

    const getUnassignedOutputs = () => {
        if (!plcProgram) return [];
        return plcProgram.outputs.filter((output: PLCOutput) => output.number === null);
    };

    return (
        <ObserveState
            key="plc-outputs-tab"
            listenTo={plcProgram}
            properties={['outputs']}
            control={() => {
                const assignedOutputs = getAssignedOutputs();
                const unassignedOutputs = getUnassignedOutputs();

                return (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                        <Grid container spacing={2}>
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="Outputs Configuration" />
                            </Grid>
                            <Grid item xs={12}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Typography variant="h6">PLC Outputs</Typography>
                                    <Box sx={{ display: 'flex', gap: 2 }}>
                                        <Button
                                            variant="outlined"
                                            color="primary"
                                            startIcon={<RefreshIcon />}
                                            onClick={loadBulkIOStates}
                                            disabled={isRefreshing}
                                        >
                                            {isRefreshing ? 'Refreshing...' : 'Refresh I/O States'}
                                        </Button>
                                        <Button
                                            variant="contained"
                                            color="primary"
                                            startIcon={<AddIcon />}
                                            onClick={handleAddOutput}
                                        >
                                            Add Output
                                        </Button>
                                    </Box>
                                </Box>
                            </Grid>
                        </Grid>

                        {/* Unassigned Outputs */}
                        <Box>
                            <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                Unassigned Outputs ({unassignedOutputs.length})
                            </Typography>
                            <TableContainer component={Paper}>
                                <Table size="small">
                                    <TableHead>
                                        <TableRow>
                                            <TableCell sx={{ width: '150px' }}>Assign Number</TableCell>
                                            <TableCell>Centroid Name</TableCell>
                                            <TableCell>Display Name</TableCell>
                                            <TableCell>Active Text</TableCell>
                                            <TableCell>Inactive Text</TableCell>
                                            <TableCell align="right">Actions</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {unassignedOutputs.length === 0 ? (
                                            <TableRow>
                                                <TableCell colSpan={6} align="center">
                                                    <Typography variant="body2" color="textSecondary">
                                                        No unassigned outputs
                                                    </Typography>
                                                </TableCell>
                                            </TableRow>
                                        ) : (
                                            unassignedOutputs.map((output: PLCOutput) => (
                                                <TableRow key={output.centroidName}>
                                                    <TableCell>
                                                        <Select
                                                            size="small"
                                                            displayEmpty
                                                            value={output.number ?? ''}
                                                            onChange={(e) => {
                                                                const value = e.target.value;
                                                                if (value === '') {
                                                                    output.number = null;
                                                                } else {
                                                                    const num = Number(value);
                                                                    const existingOutput = plcProgram.outputs.find(
                                                                        (o: PLCOutput) => o.number === num && o.centroidName !== output.centroidName
                                                                    );
                                                                    if (existingOutput) {
                                                                        existingOutput.number = null;
                                                                    }
                                                                    output.number = num;
                                                                }
                                                                StateManager.propertyChanged(plcProgram, 'outputs');
                                                            }}
                                                            sx={{ width: '120px' }}
                                                        >
                                                            <MenuItem value="">
                                                                <em>Unassigned</em>
                                                            </MenuItem>
                                                            {availableOutputs.map((num) => {
                                                                const isAssigned = isNumberAssigned(num, output.centroidName);
                                                                return (
                                                                    <MenuItem
                                                                        key={num}
                                                                        value={num}
                                                                        sx={{
                                                                            color: isAssigned ? 'text.disabled' : 'text.primary',
                                                                            fontStyle: isAssigned ? 'italic' : 'normal'
                                                                        }}
                                                                    >
                                                                        {num}{isAssigned ? ' (in use)' : ''}
                                                                    </MenuItem>
                                                                );
                                                            })}
                                                        </Select>
                                                    </TableCell>
                                                    <TableCell>{output.centroidName}</TableCell>
                                                    <TableCell>{output.name}</TableCell>
                                                    <TableCell>{output.activeText}</TableCell>
                                                    <TableCell>{output.inactiveText}</TableCell>
                                                    <TableCell align="right">
                                                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => {
                                                                    setEditingOutput(output);
                                                                    setDialogOpen(true);
                                                                }}
                                                                title="Edit output"
                                                            >
                                                                <EditIcon fontSize="small" />
                                                            </IconButton>
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => handleDeleteOutput(output)}
                                                                title="Delete output"
                                                            >
                                                                <DeleteIcon fontSize="small" />
                                                            </IconButton>
                                                        </Box>
                                                    </TableCell>
                                                </TableRow>
                                            ))
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        </Box>

                        {/* Assigned Outputs */}
                        <Box>
                            <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                Assigned Outputs ({assignedOutputs.length})
                            </Typography>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                                {assignedOutputs.length === 0 ? (
                                    <Paper sx={{ p: 3 }}>
                                        <Typography variant="body2" color="textSecondary" align="center">
                                            No assigned outputs
                                        </Typography>
                                    </Paper>
                                ) : (
                                    assignedOutputs.map((output: PLCOutput) => {
                                        // Get current state from bulk I/O states
                                        const isActive = bulkIOStates?.outputs[output.number || 0] ?? false;

                                        return (
                                            <Paper
                                                key={output.centroidName}
                                                sx={{
                                                    p: 2,
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: 2
                                                }}
                                            >
                                                <Select
                                                    size="small"
                                                    value={output.number ?? ''}
                                                    displayEmpty
                                                    onChange={(e) => {
                                                        const value = e.target.value;
                                                        if (value === '') {
                                                            output.number = null;
                                                        } else {
                                                            const num = Number(value);
                                                            const existingOutput = plcProgram.outputs.find(
                                                                (o: PLCOutput) => o.number === num && o.centroidName !== output.centroidName
                                                            );
                                                            if (existingOutput) {
                                                                existingOutput.number = null;
                                                            }
                                                            output.number = num;
                                                        }
                                                        StateManager.propertyChanged(plcProgram, 'outputs');
                                                    }}
                                                    sx={{ width: '120px' }}
                                                >
                                                    <MenuItem value="">
                                                        <em>Unassigned</em>
                                                    </MenuItem>
                                                    {availableOutputs.map((num) => {
                                                        const isAssigned = isNumberAssigned(num, output.centroidName);
                                                        return (
                                                            <MenuItem
                                                                key={num}
                                                                value={num}
                                                                sx={{
                                                                    color: isAssigned ? 'text.disabled' : 'text.primary',
                                                                    fontStyle: isAssigned ? 'italic' : 'normal'
                                                                }}
                                                            >
                                                                {num}{isAssigned ? ' (in use)' : ''}
                                                            </MenuItem>
                                                        );
                                                    })}
                                                </Select>

                                                <Box sx={{ flex: '0 0 200px' }}>
                                                    <SymbolNameWithUsageTooltip
                                                        centroidName={output.centroidName}
                                                        programType={PLCProgramType.System}
                                                    >
                                                        <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                                            {output.name}
                                                        </Typography>
                                                    </SymbolNameWithUsageTooltip>
                                                </Box>

                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: '0 0 150px' }}>
                                                    <Typography variant="body2" color="textSecondary">
                                                        Current:
                                                    </Typography>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                        <Box
                                                            sx={{
                                                                width: 10,
                                                                height: 10,
                                                                borderRadius: '50%',
                                                                backgroundColor: isActive ? ConfigurationDataColors.Instance.successColor : ConfigurationDataColors.Instance.errorColor
                                                            }}
                                                        />
                                                        <Typography
                                                            variant="body2"
                                                            sx={{
                                                                fontWeight: 'bold',
                                                                color: isActive ? 'success.main' : 'error.main'
                                                            }}
                                                        >
                                                            {isActive ? 'Active' : 'Inactive'}
                                                        </Typography>
                                                    </Box>
                                                </Box>

                                                <Box sx={{ flex: 1, display: 'flex', alignItems: 'center', gap: 2 }}>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                        <Typography variant="body2" sx={{ fontWeight: 500 }}>
                                                            Active:
                                                        </Typography>
                                                        <Typography variant="body2">
                                                            {output.activeText}
                                                        </Typography>
                                                    </Box>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                        <Typography variant="body2" sx={{ fontWeight: 500 }}>
                                                            Inactive:
                                                        </Typography>
                                                        <Typography variant="body2">
                                                            {output.inactiveText}
                                                        </Typography>
                                                    </Box>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                        <Typography variant="body2" sx={{ fontWeight: 500 }}>
                                                            G-Code (on/off):
                                                        </Typography>
                                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontSize: '0.85rem' }}>
                                                            {output.getOnGCode() || <em style={{ color: 'gray' }}>none</em>}
                                                            {' / '}
                                                            {output.getOffGCode() || <em style={{ color: 'gray' }}>none</em>}
                                                        </Typography>
                                                    </Box>
                                                </Box>

                                                <Box sx={{ display: 'flex', gap: 1 }}>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => {
                                                            setEditingOutput(output);
                                                            setDialogOpen(true);
                                                        }}
                                                        title="Edit output"
                                                    >
                                                        <EditIcon fontSize="small" />
                                                    </IconButton>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => handleDeleteOutput(output)}
                                                        title="Delete output"
                                                    >
                                                        <DeleteIcon fontSize="small" />
                                                    </IconButton>
                                                </Box>
                                            </Paper>
                                        );
                                    })
                                )}
                            </Box>
                        </Box>

                        <OutputDialog
                            open={dialogOpen}
                            output={editingOutput}
                            availableOutputs={availableOutputs}
                            onClose={() => {
                                setDialogOpen(false);
                                setEditingOutput(null);
                            }}
                            onSave={() => {
                                setEditingOutput(null);
                            }}
                        />
                    </Box>
                );
            }}
        />
    );
}

