import { Condition } from './Condition';
import { ConditionGroup } from './ConditionGroup';
import { DataCondition } from './DataCondition';

/**
 * Factory for creating Condition instances from JSON data
 * Handles deserialization of different condition types
 */
export class ConditionFactory {
    /**
     * Create a condition instance based on type string
     * @param type The condition type ('DataCondition', 'ConditionGroup')
     * @returns New condition instance of the specified type
     */
    public static createCondition(type: string): Condition {
        switch (type) {
            case 'DataCondition':
                return new DataCondition();
            case 'ConditionGroup':
                return new ConditionGroup();
            default:
                throw new Error(`Unknown condition type: ${type}`);
        }
    }

    /**
     * Create a condition instance from JSON data
     * Automatically detects type and deserializes all fields
     * @param data JSON data containing condition information
     * @returns Fully populated condition instance
     */
    public static createConditionFromJSON(data: any): Condition {
        if (!data) {
            throw new Error('Invalid condition data: data is null or undefined');
        }

        // Get conditionType from data, or infer from structure for backward compatibility
        let conditionType = data.conditionType;

        if (!conditionType) {
            // Backward compatibility: infer type from data structure
            if (data._conditions && Array.isArray(data._conditions)) {
                // Has _conditions array -> ConditionGroup
                conditionType = 'ConditionGroup';
            } else if (data._dataElement || data._comparisonOperator !== undefined) {
                // Has _dataElement or _comparisonOperator -> DataCondition
                conditionType = 'DataCondition';
            } else {
                throw new Error('Invalid condition data: cannot determine type from structure');
            }
        }

        const condition = this.createCondition(conditionType);
        // DO NOT call fromJSON here - let the parent set plcSource first, then call fromJSON
        // condition.fromJSON(data);
        return condition;
    }

    /**
     * Create multiple conditions from JSON array
     * @param dataArray Array of JSON condition data
     * @returns Array of condition instances
     */
    public static createConditionsFromJSON(dataArray: any[]): Condition[] {
        if (!Array.isArray(dataArray)) {
            return [];
        }

        return dataArray.map(data => this.createConditionFromJSON(data));
    }
}
