import { PlayArrow as MeasureIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { TouchOffTarget } from '../../../../machine/ICNCSystem';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { JogControls } from '../../../Common/JogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { TouchOffWizard } from '../TouchOffWizard';

/**
 * Step for touch plate measurement with jog controls
 */
export class TouchPlateTouchOffStep extends WizardStep {

    getTitle(): string {
        const wizard = this.wizard as TouchOffWizard;
        const targetName = wizard.state.target === TouchOffTarget.WorkZero
            ? 'Work Zero'
            : wizard.state.target === TouchOffTarget.SpoilBoard
                ? 'Spoilboard'
                : 'Machine Bed';
        return `Touch Plate - ${targetName}`;
    }

    nextStep(): WizardStep | null {
        return null; // Last step
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="touchplate-touchoff-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <TouchPlateTouchOffStepComponent step={this} />}
            />
        );
    }
}

interface TouchPlateTouchOffStepComponentProps {
    step: TouchPlateTouchOffStep;
}

function TouchPlateTouchOffStepComponent({ step }: TouchPlateTouchOffStepComponentProps) {
    const wizard = step.wizard as TouchOffWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isProcessing, setIsProcessing] = React.useState(false);

    const target = wizard.state.target === TouchOffTarget.WorkZero
        ? 'work zero'
        : wizard.state.target === TouchOffTarget.SpoilBoard
            ? 'spoilboard'
            : 'machine bed';
    const targetName = wizard.state.target === TouchOffTarget.WorkZero
        ? 'Work Zero'
        : wizard.state.target === TouchOffTarget.SpoilBoard
            ? 'Spoilboard'
            : 'Machine Bed';

    const handleMeasure = async () => {
        try {
            setIsProcessing(true);

            // Call the machine interface method to handle probing and setting the reference
            // This method handles all the calculations and coordinate transformations
            const machine = Machine.getInstance();
            await machine.system.probeAndSetMaterialReference(wizard.state.target!, {
                onComplete: async () => {
                    setIsProcessing(false);
                    wizard.completeWizard();
                },
                onError: async (error: Error | string) => {
                    setIsProcessing(false);
                    const errorMessage = typeof error === 'string' ? error : error.message;
                    Logger.Instance.logError(LogCategory.UserInterface, `Touch plate measurement failed: ${errorMessage}`);
                    UserMessageQueue.Instance.addMessage(`❌ ${errorMessage}`);
                }
            });
        } catch (error) {
            setIsProcessing(false);
            const errorMessage = error instanceof Error ? error.message : String(error);
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to start touch plate measurement:', error);
            UserMessageQueue.Instance.addMessage(`❌ ${errorMessage}`);
        }
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Position Over Touch Plate
                </Typography>
            </Box>

            {/* Main content area - side by side layout */}
            <Box sx={{ flex: 1, display: 'flex', gap: 3, minHeight: 0 }}>
                {/* Instructions - left side */}
                <Box sx={{
                    width: '300px',
                    flexShrink: 0,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`,
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Instructions:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        1. Place the touch plate on top of the {target}
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        2. Use the jog controls to position the tool above the center of the touch plate
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        3. Ensure the touch plate cable is connected
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        4. Click "Measure" - the machine will automatically probe down to measure the Z height
                    </Typography>
                </Box>

                {/* Jog Controls - right side, centered */}
                <Box sx={{
                    flex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                }}>
                    <JogControls />
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                    disabled={isProcessing}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleMeasure}
                    disabled={isProcessing}
                    startIcon={<MeasureIcon />}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    {isProcessing ? 'Measuring...' : 'Measure'}
                </Button>
            </Box>
        </Box>
    );
}
