import { FormControlLabel, Grid, Switch } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function RailingSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="railing-width"
                    listenTo={machine}
                    properties={['railingWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Railing Width"
                            value={machine.railingWidth}
                            onChange={(value) => machine.railingWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />

                <ObserveState
                    key="railing-height"
                    listenTo={machine}
                    properties={['railingHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Railing Height"
                            value={machine.railingHeight}
                            onChange={(value) => machine.railingHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="railing-outside-bed"
                    listenTo={machine}
                    properties={['railingOutsideBed']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.railingOutsideBed}
                                    onChange={(e) => machine.railingOutsideBed = e.target.checked}
                                />
                            }
                            label="Railing Outside Bed"
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
