import { IStorable } from '../../../common/IStorable';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { Declaration } from './Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode, PLCValidationIssue } from './IPLCElement';
import { PLCBlock } from './PLCBlock';
import { IPLCSource, PLCProgramType, PLCSerializationHelper, PLCUtilities } from './PLCUtilities';

/**
 * Stage type enum for PLC program organization
 */
export enum StageType {
    Initial = 'Initial',           // Initialization/startup stage
    Main = 'Main',                 // Main program stage
    Final = 'Final'                // Shutdown/cleanup stage
}

/**
 * Represents a stage in a PLC program
 * A stage contains multiple blocks organized for a specific purpose
 */
export class PLCStage implements IStorable, IPLCElement {
    private _name: string;
    private _type: StageType;
    private _blocks: PLCBlock[];
    private _description: string;   // Stage description/documentation
    private _enabled: boolean;      // Whether this stage is enabled/active
    private _fast: boolean;         // Whether this is a fast stage (runs at higher priority)
    private _collapsed: boolean;    // UI state: whether stage is collapsed in editor
    private _plcSource: IPLCSource | undefined;
    private _parentElement: IPLCElement | undefined;  // Parent program that contains this stage
    private _ordinal: number;       // Sort order for stages

    constructor(name: string = '', type: StageType = StageType.Main) {
        this._plcSource = undefined;
        this._name = name;
        this._type = type;
        this._blocks = [];
        this._description = '';
        this._enabled = true;
        this._fast = false;
        this._collapsed = false;
        this._ordinal = 0;

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
        this.notifyProgramValidationChanged();
    }

    public get type(): StageType {
        return this._type;
    }

    public set type(value: StageType) {
        this._type = value;
        StateManager.propertyChanged(this, 'type');
    }

    public get blocks(): PLCBlock[] {
        return this._blocks.slice().sort((a, b) => a.ordinal - b.ordinal);
    }

    public set blocks(value: PLCBlock[]) {
        this._blocks = value;
        // Set parent on all blocks - they'll resolve plcSource from parent chain
        for (const block of this._blocks) {
            block.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'blocks');
        this.notifyProgramValidationChanged();
    }

    public get description(): string {
        return this._description;
    }

    public set description(value: string) {
        this._description = value;
        StateManager.propertyChanged(this, 'description');
    }

    public get enabled(): boolean {
        return this._enabled;
    }
    public set enabled(value: boolean) {
        this._enabled = value;
        StateManager.propertyChanged(this, 'enabled');
        this.notifyProgramValidationChanged();
    }

    public get fast(): boolean {
        return this._fast;
    }

    public set fast(value: boolean) {
        this._fast = value;
        StateManager.propertyChanged(this, 'fast');
    }

    public get collapsed(): boolean {
        return this._collapsed;
    }

    public set collapsed(value: boolean) {
        this._collapsed = value;
        StateManager.propertyChanged(this, 'collapsed');
    }

    public get plcSource(): IPLCSource | undefined {
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    /**
     * Get the type of this PLC element
     */
    public getElementType(): 'stage' {
        return 'stage';
    }

    /**
     * Reset cached state in this stage and all child elements
     */
    public preRenderReset(): void {
        for (const block of this._blocks) {
            block.preRenderReset();
        }
    }

    /**
     * Get unique identifier for this stage (the stage name)
     */
    public getElementId(): string {
        return this._name;
    }

    /**
     * Get the parent element (program) that contains this stage
     */
    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    /**
     * Set the parent element (program) that contains this stage
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
        // Clear cached plcSource - will be resolved on next access
        this._plcSource = undefined;

        // Cascade to all child blocks to ensure complete parent chain
        for (const block of this._blocks) {
            block.setParentElement(this);
        }
    }

    public get ordinal(): number {
        return this._ordinal;
    }

    public set ordinal(value: number) {
        this._ordinal = value;
        StateManager.propertyChanged(this, 'ordinal');
    }

    /**
     * Check if this stage is inherited from SystemDefault
     * A stage is inherited if its plcSource.type is SystemDefault
     * @returns true if the stage is from SystemDefault program
     */
    public IsInheritedFromSystemDefault(): boolean {
        // Check if plcSource exists and its type is SystemDefault
        if (!this.plcSource) {
            return false;
        }

        return this.plcSource.getProgramType() === PLCProgramType.SystemDefault;
    }

    /**
     * Check if this System stage mirrors a SystemDefault stage (same name exists in SystemDefault)
     * @returns true if a stage with this name exists in SystemDefault
     */
    public IsMirroringSystemDefault(): boolean {
        // Only relevant for System program stages
        const source = this.plcSource; // Use getter to resolve through parent chain
        if (!source || source.getProgramType() !== PLCProgramType.System) {
            return false;
        }

        // Check if SystemDefault has a stage with the same name and type
        const systemDefaultProgram = source.constructor as any;
        const systemDefault = systemDefaultProgram.Instance(PLCProgramType.SystemDefault);
        const matchingStage = systemDefault.stages.find((s: PLCStage) =>
            s.name === this._name && s.type === this._type
        );
        return !!matchingStage;
    }

    /**
     * Get blocks for rendering - includes SystemDefault blocks if this is a mirror stage
     * @returns Array of blocks (SystemDefault blocks first, then System blocks)
     */
    public getBlocksForRendering(): PLCBlock[] {
        // If this is a System stage that mirrors a SystemDefault stage, merge the blocks
        if (this.IsMirroringSystemDefault()) {
            // Get SystemDefault program instance
            const source = this.plcSource!; // Use getter
            const systemDefaultProgram = source.constructor as any;
            const systemDefault = systemDefaultProgram.Instance(PLCProgramType.SystemDefault);
            const sdStage = systemDefault.stages.find((s: PLCStage) =>
                s.name === this._name && s.type === this._type
            );

            if (sdStage) {
                // Get SystemDefault blocks (with statements and enabled) sorted by ordinal
                // Disabled blocks are NOT mirrored from SystemDefault
                const sdBlocksWithStatements = sdStage.blocks
                    .filter((b: PLCBlock) => b.actions.length > 0 && b.enabled)
                    .sort((a: PLCBlock, b: PLCBlock) => a.ordinal - b.ordinal);

                // Get user-defined blocks sorted by ordinal
                const userBlocks = this.getDefinedBlocks();

                // Return SystemDefault blocks first, then user-defined blocks
                return [...sdBlocksWithStatements, ...userBlocks];
            }
        }

        // Otherwise just return this stage's blocks
        return this.blocks;
    }

    /**
     * Get only this stage's own defined blocks (not inherited from SystemDefault)
     * Returns sorted blocks by ordinal
     * @returns Array of blocks owned by this stage
     */
    public getDefinedBlocks(): PLCBlock[] {
        return this._blocks.slice().sort((a, b) => a.ordinal - b.ordinal);
    }

    /**
     * Add a block to this stage
     */
    public addBlock(block: PLCBlock): void {
        // Only set parent - block will resolve plcSource from parent chain
        // Callers (such as the editor) may want to create a block that belongs to
        // a different program than the stage's source (e.g. adding a System-owned
        // block into a stage that was inherited from SystemDefault).
        block.setParentElement(this);
        // Set ordinal to max + 1
        const maxOrdinal = this._blocks.length > 0
            ? Math.max(...this._blocks.map(b => b.ordinal))
            : -1;
        block.ordinal = maxOrdinal + 1;
        this._blocks.push(block);
        StateManager.propertyChanged(this, 'blocks');
        // Invalidate cache since declarations may have been added
        PLCUtilities.invalidateProgramCache();
    }

    /**
     * Add a block at a specific ordinal position
     * Used for moving/reordering items - does not auto-assign ordinal
     * Inserts at the correct array position to maintain sorted order
     */
    public addBlockAt(block: PLCBlock, ordinal: number): void {
        block.setParentElement(this);
        block.ordinal = ordinal;

        // Find the correct insertion index by counting blocks with lower ordinals
        let insertIndex = 0;
        for (const existing of this._blocks) {
            if (existing.ordinal < ordinal) {
                insertIndex++;
            }
        }

        this._blocks.splice(insertIndex, 0, block);
        StateManager.propertyChanged(this, 'blocks');
        PLCUtilities.invalidateProgramCache();
    }

    /**
     * Remove a block from this stage
     */
    public removeBlock(block: PLCBlock): void {
        const index = this._blocks.indexOf(block);
        if (index > -1) {
            block.setParentElement(undefined);
            this._blocks.splice(index, 1);

            // Renumber remaining blocks to maintain sequential ordinals
            this._blocks.forEach((b, idx) => {
                b.ordinal = idx;
            });

            StateManager.propertyChanged(this, 'blocks');
            // Invalidate cache since declarations may have been removed
            PLCUtilities.invalidateProgramCache();
        }
    }

    /**
     * Insert a block at a specific index
     */
    public insertBlock(index: number, block: PLCBlock): void {
        block.setParentElement(this);
        this._blocks.splice(index, 0, block);
        StateManager.propertyChanged(this, 'blocks');
    }

    /**
     * Move a block from one position to another
     */
    public moveBlock(fromIndex: number, toIndex: number): void {
        if (fromIndex < 0 || fromIndex >= this._blocks.length ||
            toIndex < 0 || toIndex >= this._blocks.length) {
            return;
        }

        const block = this._blocks.splice(fromIndex, 1)[0];
        this._blocks.splice(toIndex, 0, block);
        StateManager.propertyChanged(this, 'blocks');
    }

    /**
     * Move a block up (decrease ordinal) by swapping with the previous block
     * @param block The block to move up
     */
    public moveBlockUp(block: PLCBlock): void {
        const definedBlocks = this.getDefinedBlocks();
        const index = definedBlocks.indexOf(block);

        if (index <= 0) return; // Already at top or not found

        // Swap ordinals with previous block
        const temp = definedBlocks[index - 1].ordinal;
        definedBlocks[index - 1].ordinal = definedBlocks[index].ordinal;
        definedBlocks[index].ordinal = temp;

        StateManager.propertyChanged(this, 'blocks');
    }

    /**
     * Move a block down (increase ordinal) by swapping with the next block
     * @param block The block to move down
     */
    public moveBlockDown(block: PLCBlock): void {
        const definedBlocks = this.getDefinedBlocks();
        const index = definedBlocks.indexOf(block);

        if (index < 0 || index >= definedBlocks.length - 1) return; // Already at bottom or not found

        // Swap ordinals with next block
        const temp = definedBlocks[index + 1].ordinal;
        definedBlocks[index + 1].ordinal = definedBlocks[index].ordinal;
        definedBlocks[index].ordinal = temp;

        StateManager.propertyChanged(this, 'blocks');
    }

    /**
     * Stages are never disabled - only their child elements can be
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return false;
    }

    /**
     * Render the stage to JSX
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        // Determine effective mode:
        // - If parent says Disabled or ReadOnly, use that (propagate down)
        // - Otherwise, if this stage is disabled, use Disabled mode
        let effectiveMode = mode;
        if (mode === PLCRenderMode.Edit && !this._enabled) {
            effectiveMode = PLCRenderMode.Disabled;
        }

        const stageStyle: React.CSSProperties = {
            textDecoration: effectiveMode === PLCRenderMode.Disabled ? 'line-through' : 'none',
            backgroundColor: effectiveMode === PLCRenderMode.ReadOnly ? ConfigurationDataColors.Instance.lightBackgroundColor : undefined,
            opacity: effectiveMode === PLCRenderMode.Disabled ? 0.6 : 1
        };

        return (
            <div className="plc-stage" data-enabled={this._enabled} style={stageStyle}>
                <div className="stage-header">
                    <h3 className="stage-name">{this._name}</h3>
                    <span className="stage-type">{this._type}</span>
                </div>
                {this._description && <div className="stage-description">{this._description}</div>}
                <div className="stage-blocks">
                    {this._blocks.map((block, index) => (
                        <div key={index} className="block-wrapper">
                            {block.render(effectiveMode, targetProgramType)}
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    /**
     * Get declarations that are used/referenced by this stage and its blocks
     */
    public getUsedDeclarations(): Declaration[] {
        const allDeclarations = this._blocks.flatMap(block => block.getUsedDeclarations());
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get declarations that are added/defined by this stage and its blocks
     */
    public getAddedDeclarations(): Declaration[] {
        const allDeclarations = this._blocks.flatMap(block => block.getAddedDeclarations());
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Check if this stage has any enabled statements
     * @returns true if at least one enabled block contains at least one enabled statement
     */
    private hasEnabledStatements(): boolean {
        const blocks = this.getBlocksForRendering();
        for (const block of blocks) {
            if (block.enabled) {
                for (const action of block.actions) {
                    if (action.enabled) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Get the PLC logic code for this stage
     * @param availableDeclarations Array of declaration names that are available/defined
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this._enabled) {
            return [`; Stage disabled: ${this._name}`];
        }

        const logic: string[] = [];

        // Stage header with visual separator and stage label
        logic.push(';==============================================================================');
        logic.push(`                                 ${this._name}`);
        logic.push(';==============================================================================');

        // Type information with system default indicator
        const isFromSystemDefault = this._parentElement !== null;
        if (isFromSystemDefault) {
            logic.push(`; Type: ${this._type} (from system defaults)`);
        } else {
            logic.push(`; Type: ${this._type}`);
        }

        // Add optional metadata as comments
        if (this._description) {
            const descriptionLines = this._description.split('\n');
            for (const line of descriptionLines) {
                logic.push(`; ${line}`);
            }
        }

        logic.push(';==============================================================================');
        logic.push('');

        // Use getBlocksForRendering() to get merged blocks (includes System Default blocks)
        const blocks = this.getBlocksForRendering();

        // Collect all block logic
        const blockLogic: string[] = [];
        for (const block of blocks) {
            blockLogic.push(...block.getPLCLogic(availableDeclarations));
            blockLogic.push('');
        }

        // Check if blockLogic contains any actual statements (non-comment, non-empty lines)
        const hasActualStatements = blockLogic.some(line => {
            const trimmed = line.trim();
            return trimmed.length > 0 && !trimmed.startsWith(';');
        });

        if (!hasActualStatements) {
            // Empty stages are not allowed by PLC compiler, output a control logic statement
            logic.push('; Empty stages are not allowed - control logic statement');
            logic.push('IF 1==1 THEN SET PROGRAM_CONTROL');
            logic.push('');
        } else {
            // Output all block logic
            logic.push(...blockLogic);
        }

        return logic;
    }

    /**
     * Get validation issues for this stage and its blocks
     */
    public getValidationIssues(): PLCValidationIssue[] {
        // Disabled elements cannot be invalid
        if (!this._enabled) {
            return [];
        }

        const issues: PLCValidationIssue[] = [];

        // Validate stage-level issues
        if (!this._name || this._name.trim() === '') {
            issues.push(new PLCValidationIssue(this, 'Stage name is required'));
        }

        // Check for duplicate stage name
        if (this.plcSource && this._name) {
            const stages = this.plcSource.getStages();
            const isDuplicate = stages.some(s => s !== this && s.name === this._name);
            if (isDuplicate) {
                issues.push(new PLCValidationIssue(this, 'Stage name must be unique'));
            }
        }

        // Collect validation issues from blocks with context
        for (const block of this._blocks) {
            const blockIssues = block.getValidationIssues();
            blockIssues.forEach(issue => {
                issues.push(new PLCValidationIssue(issue.element, `[Block: ${block.name}] ${issue.message}`));
            });
        }

        return issues;
    }

    /**
     * Determine whether this stage should be output
     * @param outputType The type of output (Render or PLCCode)
     * @param availableDeclarations Optional array of available declaration names
     * @returns OutputState indicating how this stage should be handled
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_blocks', '_collapsed']);

        const blocksJson: any[] = [];
        this._blocks.forEach((block, index) => {
            try {
                blocksJson.push(block.toJSON());
            } catch (error) {
                console.error(`Failed to serialize block ${index} (${block.name}) in stage ${this._name}:`, error);
                throw new Error(`Failed to serialize block "${block.name}" in stage "${this._name}": ${error.message}`);
            }
        });

        return {
            ...baseData,
            blocks: blocksJson
        };
    }

    /**
     * Load from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // FIRST: Load this stage's own properties (name, type, etc.) 
        // This must happen BEFORE creating child blocks so we have stage context
        DataUtilities.loadStorageData(this, data, ['_blocks', 'blocks']);

        // NOW load blocks - support both underscore and non-underscore formats for backward compatibility
        const blocksData = data.blocks || data._blocks;
        if (blocksData && Array.isArray(blocksData)) {
            this._blocks = blocksData.map((blockData: any) => {
                const block = new PLCBlock();
                // Deserialize first
                block.fromJSON(blockData);
                // THEN set parent (which will set plcSource via parent chain)
                block.setParentElement(this);
                return block;
            });

            // Validate deserialization count
            if (this._blocks.length !== blocksData.length) {
                const error = `PLCStage '${this._name}' deserialization error: Expected ${blocksData.length} blocks but got ${this._blocks.length}`;
                console.error(error, '\nJSON data:', JSON.stringify(data, null, 2));
                throw new Error(error);
            }
        }

        // ALWAYS default to collapsed = true to prevent flashing when opening PLC editor
        this._collapsed = true;
    }

    /**
     * Notify the parent program that validation state may have changed
     * This propagates validation changes up to the program level so sidebar indicators update
     */
    private notifyProgramValidationChanged(): void {
        // The parent of a stage is the program
        const program = this._parentElement;
        if (program && 'notifyValidationChanged' in program) {
            (program as any).notifyValidationChanged();
        }
    }
}
