import {
    Box,
    FormControl,
    Grid,
    InputLabel,
    MenuItem,
    Paper,
    Select,
    Typography,
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { JogIncrementSpeed } from '../../../../data/ConfigurationState';
import { ObserveState } from '../../../../utils/statemanager';
import NumberInput from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function FeedRateSpeedsSection() {
    const config = ConfigurationData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Feed Rate Speeds" />
            </Grid>

            {/* X/Y Speeds */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" gutterBottom>X/Y Axis Speeds</Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 2 }}>
                        <ObserveState
                            key="config-fast-jog-xy"
                            listenTo={config}
                            properties={['fastJogXY']}
                            control={() => (
                                <NumberInput
                                    label="Fast Jog X/Y (in/min)"
                                    value={config.fastJogXY}
                                    onChange={(value) => config.fastJogXY = value}
                                    fullWidth
                                    min={1}
                                    max={2000}
                                    precision={0}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-slow-jog-xy"
                            listenTo={config}
                            properties={['slowJogXY']}
                            control={() => (
                                <NumberInput
                                    label="Slow Jog X/Y (in/min)"
                                    value={config.slowJogXY}
                                    onChange={(value) => config.slowJogXY = value}
                                    fullWidth
                                    min={1}
                                    max={500}
                                    precision={0}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-max-speed-xy"
                            listenTo={config}
                            properties={['maxSpeedXY']}
                            control={() => (
                                <NumberInput
                                    label="Max Speed X/Y (in/min)"
                                    value={config.maxSpeedXY}
                                    onChange={(value) => config.maxSpeedXY = value}
                                    fullWidth
                                    min={1}
                                    max={5000}
                                    precision={0}
                                />
                            )}
                        />
                    </Box>
                </Paper>

                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Jog Increment</Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 2 }}>
                        <ObserveState
                            key="config-jog-increment-1x"
                            listenTo={config}
                            properties={['jogIncrement1x']}
                            control={() => (
                                <NumberInput
                                    label="Linear Jog Increment (X1) (inches)"
                                    value={config.jogIncrement1x}
                                    onChange={(value) => config.jogIncrement1x = value}
                                    fullWidth
                                    min={0.000001}
                                    max={0.1}
                                    precision={4}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-rotary-jog-increment"
                            listenTo={config}
                            properties={['rotaryJogIncrement']}
                            control={() => (
                                <NumberInput
                                    label="Rotary Jog Increment (X1) (degrees)"
                                    value={config.rotaryJogIncrement}
                                    onChange={(value) => config.rotaryJogIncrement = value}
                                    fullWidth
                                    min={0.000001}
                                    max={10}
                                    precision={2}
                                />
                            )}
                        />
                    </Box>
                </Paper>
            </Grid>

            {/* Z Speeds */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Z Axis Speeds</Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 2 }}>
                        <ObserveState
                            key="config-fast-jog-z-plus"
                            listenTo={config}
                            properties={['fastJogZPlus']}
                            control={() => (
                                <NumberInput
                                    label="Fast Jog Z+ (in/min)"
                                    value={config.fastJogZPlus}
                                    onChange={(value) => config.fastJogZPlus = value}
                                    fullWidth
                                    min={1}
                                    max={2000}
                                    precision={0}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-fast-jog-z-minus"
                            listenTo={config}
                            properties={['fastJogZMinus']}
                            control={() => (
                                <NumberInput
                                    label="Fast Jog Z- (in/min)"
                                    value={config.fastJogZMinus}
                                    onChange={(value) => config.fastJogZMinus = value}
                                    fullWidth
                                    min={1}
                                    max={2000}
                                    precision={0}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-slow-jog-z"
                            listenTo={config}
                            properties={['slowJogZ']}
                            control={() => (
                                <NumberInput
                                    label="Slow Jog Z (in/min)"
                                    value={config.slowJogZ}
                                    onChange={(value) => config.slowJogZ = value}
                                    fullWidth
                                    min={1}
                                    max={500}
                                    precision={0}
                                />
                            )}
                        />

                        <ObserveState
                            key="config-max-speed-z"
                            listenTo={config}
                            properties={['maxSpeedZ']}
                            control={() => (
                                <NumberInput
                                    label="Max Speed Z (in/min)"
                                    value={config.maxSpeedZ}
                                    onChange={(value) => config.maxSpeedZ = value}
                                    fullWidth
                                    min={1}
                                    max={5000}
                                    precision={0}
                                />
                            )}
                        />
                    </Box>
                </Paper>

                <Paper sx={{ p: 3, mt: 3 }}>
                    <Typography variant="h6" gutterBottom>Default Jog Modes</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        These settings are applied when the application starts
                    </Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 2 }}>
                        <ObserveState
                            key="config-default-jog-increment-speed"
                            listenTo={config}
                            properties={['defaultJogIncrementSpeed']}
                            control={() => (
                                <FormControl fullWidth>
                                    <InputLabel>Default Jog Speed Multiplier</InputLabel>
                                    <Select
                                        value={config.defaultJogIncrementSpeed}
                                        onChange={(e) => config.defaultJogIncrementSpeed = e.target.value as JogIncrementSpeed}
                                        label="Default Jog Speed Multiplier"
                                    >
                                        <MenuItem value={JogIncrementSpeed.X1}>X1</MenuItem>
                                        <MenuItem value={JogIncrementSpeed.X10}>X10</MenuItem>
                                        <MenuItem value={JogIncrementSpeed.X100}>X100</MenuItem>
                                    </Select>
                                </FormControl>
                            )}
                        />

                        <ObserveState
                            key="config-default-jog-fast-mode"
                            listenTo={config}
                            properties={['defaultJogFastMode']}
                            control={() => (
                                <FormControl fullWidth>
                                    <InputLabel>Default Jog Speed</InputLabel>
                                    <Select
                                        value={config.defaultJogFastMode ? 'fast' : 'slow'}
                                        onChange={(e) => config.defaultJogFastMode = e.target.value === 'fast'}
                                        label="Default Jog Speed"
                                    >
                                        <MenuItem value="slow">Slow</MenuItem>
                                        <MenuItem value="fast">Fast</MenuItem>
                                    </Select>
                                </FormControl>
                            )}
                        />

                        <ObserveState
                            key="config-default-jog-continuous-mode"
                            listenTo={config}
                            properties={['defaultJogContinuousMode']}
                            control={() => (
                                <FormControl fullWidth>
                                    <InputLabel>Default Jog Mode</InputLabel>
                                    <Select
                                        value={config.defaultJogContinuousMode ? 'continuous' : 'incremental'}
                                        onChange={(e) => config.defaultJogContinuousMode = e.target.value === 'continuous'}
                                        label="Default Jog Mode"
                                    >
                                        <MenuItem value="continuous">Continuous</MenuItem>
                                        <MenuItem value="incremental">Incremental</MenuItem>
                                    </Select>
                                </FormControl>
                            )}
                        />
                    </Box>
                </Paper>
            </Grid>
        </Grid>
    );
}
