import { Box, Typography } from '@mui/material';
import { IPLCElement } from '../../centroid/plc/data/IPLCElement';
import { SetupChecklistLibrary } from '../../data/Checklist/SetupChecklistLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { SystemIcons } from '../../SystemIcons';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';

interface UnifiedValidationIndicatorProps {
    /** The PLC element to validate */
    plcElement: IPLCElement;
    /** Array of checklist item names to validate */
    checklistItemNames: string[];
    /** Optional: Custom styling */
    sx?: any;
}

/**
 * UnifiedValidationIndicator Component
 * 
 * Combines checklist validation and PLC validation into a single indicator
 * showing the total count of issues from both sources.
 */
export function UnifiedValidationIndicator(props: UnifiedValidationIndicatorProps) {
    const { plcElement, checklistItemNames, sx = {} } = props;
    const checklistLibrary = SetupChecklistLibrary.Instance;

    return (
        <ObserveMultiProperties
            key="unified-validation-indicator"
            listenTo={[
                { object: plcElement, properties: ['inputs', 'outputs', 'stages', 'uiTriggers', 'm94m95Triggers'] },
                { object: checklistLibrary, properties: ['items'] }
            ]}
            control={() => {
                const config = ConfigurationData.Instance;
                const colors = ConfigurationDataColors.Instance;

                // Get checklist incomplete count
                const checklistItems = checklistLibrary.items.filter(item =>
                    !checklistItemNames || checklistItemNames.length === 0 || checklistItemNames.includes(item.name)
                );
                const checklistCount = checklistItems.filter(item => !item.isCompleted()).length;

                // Get PLC validation issue count
                const plcIssues = plcElement.getValidationIssues();
                const plcCount = plcIssues.length;

                // Total count
                const totalCount = checklistCount + plcCount;

                if (totalCount === 0) {
                    return null;
                }

                return (
                    <Box
                        sx={{
                            color: colors.errorColor,
                            display: 'flex',
                            alignItems: 'center',
                            gap: 0.5,
                            ...sx
                        }}
                    >
                        {SystemIcons.warning}
                        <Typography
                            variant="caption"
                            sx={{
                                fontWeight: 'bold',
                                color: colors.errorColor
                            }}
                        >
                            {totalCount}
                        </Typography>
                    </Box>
                );
            }}
        />
    );
}
