import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying feed rate speeds configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the feed rates are appropriate for the specific machine.
 */
export class FeedRateSpeedsChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Feed Rate Speeds',
            'Configure feed rate speeds for rapid moves, normal feeds, and other machine operations'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured appropriate speeds
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if speeds are correct for the machine
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new FeedRateSpeedsChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
