import { Box, Grid } from '@mui/material';
import React from 'react';
import { SetupChecklistIndicator } from '../../../../components/Common/SetupChecklistIndicator';
import { MachineData } from '../../../../data/Machine/MachineData';
import { SpindleConfigPanel } from './SpindleConfigPanel';

/**
 * Spindle 1 Setup Tab - Primary spindle configuration
 */
export function Spindle1SetupTab(): React.ReactElement {
    const machineData = MachineData.Instance;

    return (
        <Box sx={{ p: 2 }}>
            <Grid container spacing={2}>
                <Grid item xs={12}>
                    <SetupChecklistIndicator name="Spindle Configuration" />
                </Grid>
                <Grid item xs={12}>
                    <SpindleConfigPanel
                        spindleConfig={machineData.spindleConfig}
                        spindleName="Primary Spindle Configuration"
                        spindleNumber={1}
                        encoderPort={1}
                    />
                </Grid>
            </Grid>
        </Box>
    );
}
