import { PanTool as ManualIcon, Sensors as TouchPlateIcon } from '@mui/icons-material';
import { Box, Card, CardActionArea, CardContent, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { TouchOffTarget } from '../../../../machine/ICNCSystem';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { WizardStep } from '../../../Wizard/WizardStep';
import { TouchOffMethod, TouchOffWizard } from '../TouchOffWizard';
import { ManualTouchOffStep } from './ManualTouchOffStep';
import { SelectOffsetTypeStep } from './SelectOffsetTypeStep';
import { SelectTargetStep } from './SelectTargetStep';
import { TouchPlateTouchOffStep } from './TouchPlateTouchOffStep';

/**
 * Step to select manual or touch plate method
 */
export class SelectMethodStep extends WizardStep {

    getTitle(): string {
        const wizard = this.wizard as TouchOffWizard;
        if (!wizard.state || wizard.state.target === undefined) {
            return 'Touch Off';
        }
        const targetName = wizard.state.target === TouchOffTarget.WorkZero
            ? 'Work Zero'
            : wizard.state.target === TouchOffTarget.SpoilBoard
                ? 'Spoilboard'
                : 'Machine Bed';
        return `Touch Off ${targetName}`;
    }

    nextStep(): WizardStep | null {
        const wizard = this.wizard as TouchOffWizard;

        // For machine bed and material, go directly to measurement (no offset choice needed)
        if (wizard.state.target === TouchOffTarget.MachineBed || wizard.state.target === TouchOffTarget.WorkZero) {
            if (wizard.state.method === TouchOffMethod.Manual) {
                return new ManualTouchOffStep(wizard, this);
            } else if (wizard.state.method === TouchOffMethod.TouchPlate) {
                return new TouchPlateTouchOffStep(wizard, this);
            }
        }

        // For spoilboard, go to offset type selection
        return new SelectOffsetTypeStep(wizard, this);
    }

    backStep(): WizardStep | null {
        const wizard = this.wizard as TouchOffWizard;
        // If target is defined in constructor (pre-specified), this is the first step
        // If target is undefined, go back to target selection
        if (wizard.state.target === undefined) {
            return new SelectTargetStep(wizard, null);
        }
        return null; // First step, no back
    }

    render(): React.ReactNode {
        const wizard = this.wizard as TouchOffWizard;
        const machineData = MachineData.Instance;

        // If touch plate is not configured, skip this step and go straight to manual
        if (!machineData.hasMovableTouchPlate) {
            // Auto-select manual method and advance
            setTimeout(() => {
                wizard.updateState({ method: TouchOffMethod.Manual });
                wizard.advanceToNextStep();
            }, 0);
            return null;
        }

        return (
            <ObserveState
                key="select-method-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <SelectMethodStepComponent step={this} />}
            />
        );
    }
}

interface SelectMethodStepComponentProps {
    step: SelectMethodStep;
}

function SelectMethodStepComponent({ step }: SelectMethodStepComponentProps) {
    const wizard = step.wizard as TouchOffWizard;
    const colors = ConfigurationDataColors.Instance;

    const target = wizard.state.target === TouchOffTarget.WorkZero
        ? 'work zero'
        : wizard.state.target === TouchOffTarget.SpoilBoard
            ? 'spoilboard'
            : 'machine bed';

    const handleSelectMethod = (method: TouchOffMethod) => {
        wizard.updateState({ method });
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Select Touch-Off Method
                </Typography>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Choose how you want to set the Z height for the {target}.
                </Typography>
                {wizard.state.target === TouchOffTarget.WorkZero && (
                    <Box sx={{ mt: 2, p: 2, backgroundColor: `${colors.infoColor}20`, borderRadius: 1 }}>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, fontWeight: 'bold', mb: 1 }}>
                            Set Work Zero Z
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 1 }}>
                            The current position will become Z=0 in your work coordinate system (G54-G59). This is typically the top surface of your material.
                        </Typography>
                        <Typography variant="caption" sx={{ color: colors.darkTextColor, fontWeight: 'bold', display: 'block', mt: 1 }}>
                            What this affects:
                        </Typography>
                        <Typography variant="caption" sx={{ color: colors.darkTextColor, display: 'block' }}>
                            • Your toolpaths will be positioned relative to this surface
                        </Typography>
                        <Typography variant="caption" sx={{ color: colors.darkTextColor, display: 'block' }}>
                            • Current work offset (G54-G59) Z value
                        </Typography>
                    </Box>
                )}
            </Box>

            {/* Method selection cards */}
            <Box sx={{ display: 'flex', gap: 3 }}>
                {/* Manual Method Card */}
                <Card
                    sx={{
                        flex: 1,
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            borderColor: colors.primaryColor,
                            boxShadow: `0 0 0 2px ${colors.primaryColor}40`
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectMethod(TouchOffMethod.Manual)}
                    >
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, p: 2.5 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                <ManualIcon sx={{ fontSize: 48, color: colors.primaryColor }} />
                                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                    Manual
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                                Jog the spindle manually until it touches the {target}, then set the Z position.
                            </Typography>
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>
                                    Best for:
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block' }}>
                                    • Quick setup without additional equipment
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block' }}>
                                    • When touch plate is not available
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>

                {/* Touch Plate Method Card */}
                <Card
                    sx={{
                        flex: 1,
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            borderColor: colors.primaryColor,
                            boxShadow: `0 0 0 2px ${colors.primaryColor}40`
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectMethod(TouchOffMethod.TouchPlate)}
                    >
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, p: 2.5 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                <TouchPlateIcon sx={{ fontSize: 48, color: colors.primaryColor }} />
                                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                    Touch Plate
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                                Use a touch plate for automatic, precise Z height measurement.
                            </Typography>
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold' }}>
                                    Best for:
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block' }}>
                                    • Accurate, repeatable measurements
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block' }}>
                                    • Production workflows
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>
            </Box>
        </Box>
    );
}
