import { IStorable } from "../../common/IStorable";
import { StateManager } from "../../utils/statemanager/StateManager";
import { DataUtilities } from "../../utils/storage/DataUtilities";

/**
 * Abstract base class for setup checklist items
 * Represents a task or verification that must be completed during machine setup
 */
export abstract class SetupChecklistItem implements IStorable {
    private _name: string = '';
    private _description: string = '';
    private _manuallyConfirmed: boolean = false;

    constructor(name?: string, description?: string) {
        if (name) this._name = name;
        if (description) this._description = description;
    }

    /**
     * Get the name of this checklist item
     */
    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
    }

    /**
     * Get the description of this checklist item
     */
    public get description(): string {
        return this._description;
    }

    public set description(value: string) {
        this._description = value;
        StateManager.propertyChanged(this, 'description');
    }

    /**
     * Get whether this item has been manually confirmed by the user
     */
    public get manuallyConfirmed(): boolean {
        return this._manuallyConfirmed;
    }

    public set manuallyConfirmed(value: boolean) {
        this._manuallyConfirmed = value;
        StateManager.propertyChanged(this, 'manuallyConfirmed');
    }

    /**
     * Determine if this checklist item should be included in the checklist
     * Override this to exclude items based on feature flags (e.g., ATC disabled)
     * @returns true if item should be included, false if it should be filtered out
     */
    public shouldInclude(): boolean {
        return true; // By default, all items are included
    }

    /**
     * Abstract method to determine if this item requires manual confirmation
     * @returns true if user must manually confirm completion
     */
    public abstract needsManualConfirmation(): boolean;

    /**
     * Abstract method to check if the completion criteria are met
     * @returns true if the automated checks pass
     */
    public abstract completionCheck(): boolean;

    /**
     * Check if this checklist item is completed
     * An item is completed when:
     * - If manual confirmation is needed: manuallyConfirmed must be true
     * - completionCheck() must return true
     * @returns true if the item is fully completed
     */
    public isCompleted(): boolean {
        // If manual confirmation is needed, check that it's been confirmed
        if (this.needsManualConfirmation() && !this._manuallyConfirmed) {
            return false;
        }

        // Check the automated completion criteria
        return this.completionCheck();
    }

    /**
     * Get a display string for this checklist item
     */
    public getDisplayString(): string {
        return this._name || 'Unnamed Checklist Item';
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }

    /**
     * Create a deep copy of this checklist item
     */
    public abstract clone(): SetupChecklistItem;
}
