/**
 * Stage for executing a block of G-code
 */

import type { GCodeExecutionCallback } from '../../machine/ICNCProgram';
import { GCodePreviewManager } from '../../utils/GCodePreviewManager';
import { JobStage, StageStatus, StageType } from '../JobStage';

export class GCodeStage extends JobStage {
    public gcodeLines: string[];
    public toolNumber?: number;
    private startLineNumber: number;
    private endLineNumber: number;

    constructor(stageNumber: number, gcodeLines: string[], startLineNumber: number, endLineNumber: number, toolNumber?: number) {
        super(stageNumber, StageType.GCode, startLineNumber - 1, endLineNumber - 1);
        this.gcodeLines = gcodeLines;
        this.startLineNumber = startLineNumber;
        this.endLineNumber = endLineNumber;
        this.toolNumber = toolNumber;
    }

    protected async executeStage(callback?: import('../JobStage').StageCallback): Promise<void> {
        // Create callback to handle G-code execution completion
        const gcodeCallback: GCodeExecutionCallback = {
            onExecuteLine: (jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean) => {
                console.log('[DEBUG] GCodeStage - onExecuteLine called:', { jobId, lineNumber, currentLine, totalLines, isLastStep });
                // Forward line execution events to stage callback for UI updates
                if (callback?.onExecuteLine) {
                    console.log('[DEBUG] GCodeStage - Forwarding to stage callback');
                    callback.onExecuteLine(jobId, lineNumber, currentLine, totalLines, isLastStep);
                } else {
                    console.log('[DEBUG] GCodeStage - No stage callback.onExecuteLine to forward to');
                }
            },
            onError: async (jobId: string, errorMessage: string) => {
                this.status = StageStatus.Error;
                this.endTime = new Date();
                this.errorMessage = errorMessage;

                if (callback) {
                    await callback.onError(errorMessage);
                }
            },
            onComplete: async (jobId: string, success: boolean, errorMessage?: string) => {
                if (success) {
                    this.status = StageStatus.Completed;
                    this.endTime = new Date();

                    if (callback) {
                        await callback.onComplete();
                    }
                } else {
                    this.status = StageStatus.Error;
                    this.endTime = new Date();
                    this.errorMessage = errorMessage || 'G-code execution failed';

                    if (callback) {
                        await callback.onError(this.errorMessage);
                    }
                }
            }
        };

        // Execute the G-code block
        // If skipPreview is true (e.g., from JobRunDialog), bypass preview dialog
        const stageName = this.toolNumber !== undefined
            ? `G-Code (Tool ${this.toolNumber})`
            : 'G-Code Block';

        const skipPreview = callback?.skipPreview || false;
        await GCodePreviewManager.Instance.executeOrPreview(
            stageName,
            this.gcodeLines,
            gcodeCallback,
            skipPreview
        );
    }

    public getStageName(): string {
        return 'G-Code Block';
    }

    public getDisplayName(): string {
        if (this.toolNumber !== undefined) {
            return `G-Code (Tool ${this.toolNumber})`;
        }
        return `G-Code Block`;
    }

    public getDescription(): string {
        const lineCount = this.gcodeLines.length;
        const lineRange = `Lines ${this.startLineNumber}-${this.endLineNumber}`;

        if (this.toolNumber !== undefined) {
            return `Execute ${lineCount} lines with Tool ${this.toolNumber} (${lineRange})`;
        }
        return `Execute ${lineCount} G-code lines (${lineRange})`;
    }

    public getStageDisplayData(): string[] {
        const data = [
            `Execute ${this.gcodeLines.length} G-code lines`,
            `(Lines ${this.startLineNumber}-${this.endLineNumber})`
        ];

        if (this.toolNumber !== undefined) {
            data.unshift(`Tool: ${this.toolNumber}`);
        }

        return data;
    }

    /**
     * Get the first few lines of G-code for preview
     */
    public getPreview(maxLines: number = 3): string[] {
        return this.gcodeLines.slice(0, maxLines);
    }

    /**
     * Override to return the stage's own gcodeLines instead of slicing from original G-code
     * This ensures that commented-out tool changes and other modifications are displayed
     */
    public getGCodeLinesWithContext(allGCodeLines: string[], contextLineCount: number = 5): {
        beforeLines: string[];
        stageLines: string[];
        afterLines: string[];
    } {
        const beforeStart = Math.max(0, this.startLineNumber - 1 - contextLineCount);
        const beforeEnd = this.startLineNumber - 1;
        const afterStart = this.endLineNumber;
        const afterEnd = Math.min(allGCodeLines.length, this.endLineNumber + contextLineCount);

        return {
            beforeLines: allGCodeLines.slice(beforeStart, beforeEnd),
            stageLines: this.gcodeLines, // Use the stage's own preprocessed lines
            afterLines: allGCodeLines.slice(afterStart, afterEnd)
        };
    }
}
