import { ExpandMore } from '@mui/icons-material';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Box,
    Checkbox,
    FormControlLabel,
    Grid,
    TextField,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { MachineData } from '../../../data/Machine/MachineData';
import { SpindleConfig } from '../../../data/Machine/SpindleConfig';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { NullableNumberInput } from '../../Common/NullableNumberInput';

export const SetupTab: React.FC = () => {
    const [expandedSections, setExpandedSections] = useState<{ [key: string]: boolean }>({
        spindle: true,
        secondSpindle: false
    });

    const handleSectionToggle = (section: string) => {
        setExpandedSections(prev => ({
            ...prev,
            [section]: !prev[section]
        }));
    };

    const renderSpindleSection = (spindle: SpindleConfig, title: string) => {
        return (
            <ObserveState
                key={`observe-spindle-${title}`}
                listenTo={spindle}
                control={() => (
                    <Box>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2, p: 2, bgcolor: 'info.50', borderRadius: 1 }}>
                            Configure spindle parameters. Leave fields empty (null) if not configured or not applicable.
                        </Typography>

                        <Grid container spacing={3}>
                            {/* Basic Parameters */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1 }}>Basic Parameters</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Encoder Counts per Revolution"
                                    value={spindle.encoderCounts}
                                    onChange={(value) => spindle.encoderCounts = value}
                                    precision={0}
                                    allowNegative={false}
                                    allowFractions={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Spindle Axis Number"
                                    value={spindle.spindleAxis}
                                    onChange={(value) => spindle.spindleAxis = value}
                                    precision={0}
                                    allowNegative={false}
                                    allowFractions={false}
                                    min={1}
                                    max={8}
                                />
                            </Grid>

                            {/* Speed Parameters */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Speed Parameters</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Maximum Speed (RPM)"
                                    value={spindle.maxSpeed}
                                    onChange={(value) => spindle.maxSpeed = value}
                                    precision={0}
                                    allowNegative={false}
                                    allowFractions={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Minimum Speed (RPM)"
                                    value={spindle.minSpeed}
                                    onChange={(value) => spindle.minSpeed = value}
                                    precision={0}
                                    allowNegative={false}
                                    allowFractions={false}
                                />
                            </Grid>

                            {/* Gear Ratios */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Gear Ratios</Typography>
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Low Gear Ratio"
                                    value={spindle.lowGearRatio}
                                    onChange={(value) => spindle.lowGearRatio = value}
                                    precision={3}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Medium Gear Ratio"
                                    value={spindle.mediumGearRatio}
                                    onChange={(value) => spindle.mediumGearRatio = value}
                                    precision={3}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="High Gear Ratio"
                                    value={spindle.highGearRatio}
                                    onChange={(value) => spindle.highGearRatio = value}
                                    precision={3}
                                    allowNegative={false}
                                />
                            </Grid>

                            {/* Timing Parameters */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Timing Parameters</Typography>
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Spindle OK Delay (seconds)"
                                    value={spindle.okDelay}
                                    onChange={(value) => spindle.okDelay = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Fan Delay (seconds)"
                                    value={spindle.fanDelay}
                                    onChange={(value) => spindle.fanDelay = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={4}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Deceleration Time (seconds)"
                                    value={spindle.decelTime}
                                    onChange={(value) => spindle.decelTime = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Spindle Accel/Decel Time"
                                    value={spindle.spindleAccelDecelTime}
                                    onChange={(value) => spindle.spindleAccelDecelTime = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Analog Output Range (0-3)"
                                    value={spindle.analogRange}
                                    onChange={(value) => spindle.analogRange = value}
                                    precision={0}
                                    allowNegative={false}
                                    min={0}
                                    max={3}
                                />
                            </Grid>

                            {/* Boolean Settings */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Features</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.encoderEnabled ?? false}
                                            onChange={(e) => spindle.encoderEnabled = e.target.checked}
                                        />
                                    }
                                    label="Enable Spindle Encoder"
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.rigidTappingEnabled ?? false}
                                            onChange={(e) => spindle.rigidTappingEnabled = e.target.checked}
                                        />
                                    }
                                    label="Enable Rigid Tapping"
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.rtgDisplay ?? false}
                                            onChange={(e) => spindle.rtgDisplay = e.target.checked}
                                        />
                                    }
                                    label="Enable RTG Display"
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.spindleScalingEnabled ?? false}
                                            onChange={(e) => spindle.spindleScalingEnabled = e.target.checked}
                                        />
                                    }
                                    label="Enable Spindle Speed Scaling"
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.allowSpindleOverride ?? false}
                                            onChange={(e) => spindle.allowSpindleOverride = e.target.checked}
                                        />
                                    }
                                    label="Allow Spindle Override"
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={spindle.doNotWaitForIndexPulse ?? false}
                                            onChange={(e) => spindle.doNotWaitForIndexPulse = e.target.checked}
                                        />
                                    }
                                    label="Do Not Wait For Index Pulse"
                                />
                            </Grid>

                            {/* Rigid Tapping Parameters */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Rigid Tapping Parameters</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Rigid Tapping Slow Speed (RPM)"
                                    value={spindle.rigidTappingSlowSpeed}
                                    onChange={(value) => spindle.rigidTappingSlowSpeed = value}
                                    precision={0}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Rigid Tapping Slow Time (seconds)"
                                    value={spindle.rigidTappingSlowTime}
                                    onChange={(value) => spindle.rigidTappingSlowTime = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Minimum Rigid Tapping RPM"
                                    value={spindle.minimumRigidTappingRPM}
                                    onChange={(value) => spindle.minimumRigidTappingRPM = value}
                                    precision={0}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Duration For Min Rigid Tapping RPM (sec)"
                                    value={spindle.durationForMinRigidTappingRPM}
                                    onChange={(value) => spindle.durationForMinRigidTappingRPM = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Threading/Tapping Accel/Decel Distance"
                                    value={spindle.threadingTappingAccelDecelDistance}
                                    onChange={(value) => spindle.threadingTappingAccelDecelDistance = value}
                                    precision={3}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Rigid Tapping Z Axis Sync Distance"
                                    value={spindle.rigidTappingZAxisSyncDistance}
                                    onChange={(value) => spindle.rigidTappingZAxisSyncDistance = value}
                                    precision={3}
                                    allowNegative={false}
                                />
                            </Grid>

                            {/* Advanced Parameters */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>Advanced Parameters</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="Spindle Drift (degrees)"
                                    value={spindle.spindleDrift}
                                    onChange={(value) => spindle.spindleDrift = value}
                                    precision={2}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="SSV Cycle Time"
                                    value={spindle.ssvCycleTime}
                                    onChange={(value) => spindle.ssvCycleTime = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="SSV Amount (%)"
                                    value={spindle.ssvAmount}
                                    onChange={(value) => spindle.ssvAmount = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <NullableNumberInput
                                    fullWidth
                                    label="FRV Cycle Time"
                                    value={spindle.frvCycleTime}
                                    onChange={(value) => spindle.frvCycleTime = value}
                                    precision={1}
                                    allowNegative={false}
                                />
                            </Grid>

                            {/* M Functions */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, mt: 2 }}>M Functions for Tapping</Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    label="M Func Bottom Hole G84"
                                    value={spindle.mFuncBottomHoleG84 ?? ''}
                                    onChange={(e) => spindle.mFuncBottomHoleG84 = e.target.value || null}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    label="M Func Top Hole G74 Counter"
                                    value={spindle.mFuncTopHoleG74Counter ?? ''}
                                    onChange={(e) => spindle.mFuncTopHoleG74Counter = e.target.value || null}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    label="M Func Bottom Hole G74 Left Hand"
                                    value={spindle.mFuncBottomHoleG74LeftHand ?? ''}
                                    onChange={(e) => spindle.mFuncBottomHoleG74LeftHand = e.target.value || null}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    label="M Func Top Hole G84 Counter"
                                    value={spindle.mFuncTopHoleG84Counter ?? ''}
                                    onChange={(e) => spindle.mFuncTopHoleG84Counter = e.target.value || null}
                                />
                            </Grid>
                        </Grid>
                    </Box>
                )}
            />
        );
    };

    return (
        <ObserveState
            key="setup-tab"
            listenTo={MachineData.Instance}
            properties={['spindleConfig', 'secondSpindleConfig', 'secondSpindleEnabled']}
            control={() => {
                const machine = MachineData.Instance;

                return (
                    <Box sx={{ p: 3 }}>
                        <Typography variant="h6" sx={{ mb: 3 }}>Machine Setup</Typography>

                        {/* Spindle Configuration */}
                        <Accordion
                            expanded={expandedSections.spindle}
                            onChange={() => handleSectionToggle('spindle')}
                            sx={{ mb: 2 }}
                        >
                            <AccordionSummary expandIcon={<ExpandMore />}>
                                <Typography variant="h6">Spindle Configuration</Typography>
                            </AccordionSummary>
                            <AccordionDetails>
                                {renderSpindleSection(machine.spindleConfig, 'spindle')}
                            </AccordionDetails>
                        </Accordion>

                        {/* Second Spindle Configuration */}
                        <Accordion
                            expanded={expandedSections.secondSpindle}
                            onChange={() => handleSectionToggle('secondSpindle')}
                            sx={{ mb: 2 }}
                        >
                            <AccordionSummary expandIcon={<ExpandMore />}>
                                <Box sx={{ display: 'flex', alignItems: 'center', flex: 1 }}>
                                    <Typography variant="h6">Second Spindle Configuration</Typography>
                                    <FormControlLabel
                                        control={
                                            <Checkbox
                                                checked={machine.secondSpindleEnabled}
                                                onChange={(e) => {
                                                    e.stopPropagation();
                                                    machine.secondSpindleEnabled = e.target.checked;
                                                }}
                                                onClick={(e) => e.stopPropagation()}
                                            />
                                        }
                                        label="Enable Second Spindle"
                                        onClick={(e) => e.stopPropagation()}
                                        sx={{ ml: 'auto' }}
                                    />
                                </Box>
                            </AccordionSummary>
                            <AccordionDetails>
                                {machine.secondSpindleEnabled ? (
                                    renderSpindleSection(machine.secondSpindleConfig, 'second-spindle')
                                ) : (
                                    <Typography color="text.secondary" sx={{ p: 2 }}>
                                        Second spindle is disabled. Enable it using the checkbox above to configure.
                                    </Typography>
                                )}
                            </AccordionDetails>
                        </Accordion>
                    </Box>
                );
            }}
        />
    );
};
