import { Button, Grid, Typography } from '@mui/material';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function ManualToolChangeSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Manual Tool Change Location" />
            </Grid>

            {/* X Position */}
            <Grid item xs={12} md={4}>
                <ObserveState
                    key="manual-tool-change-x"
                    listenTo={machine}
                    properties={['manualToolChangeLocationFromMZX']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="X Position"
                                value={machine.manualToolChangeLocationFromMZX}
                                onChange={(value) => machine.manualToolChangeLocationFromMZX = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                X-axis position from Machine Zero
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            {/* Y Position */}
            <Grid item xs={12} md={4}>
                <ObserveState
                    key="manual-tool-change-y"
                    listenTo={machine}
                    properties={['manualToolChangeLocationFromMZY']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Y Position"
                                value={machine.manualToolChangeLocationFromMZY}
                                onChange={(value) => machine.manualToolChangeLocationFromMZY = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Y-axis position from Machine Zero
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            {/* Z Position */}
            <Grid item xs={12} md={4}>
                <ObserveState
                    key="manual-tool-change-z"
                    listenTo={machine}
                    properties={['manualToolChangeLocationFromMZZ']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Z Position"
                                value={machine.manualToolChangeLocationFromMZZ}
                                onChange={(value) => machine.manualToolChangeLocationFromMZZ = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Z-axis position from Machine Zero
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            {/* Capture Current Position Button */}
            <Grid item xs={12}>
                <Button
                    variant="outlined"
                    onClick={() => {
                        const currentPoint = ConfigurationState.Instance.currentMachinePoint;
                        machine.manualToolChangeLocationFromMZX = currentPoint.x;
                        machine.manualToolChangeLocationFromMZY = currentPoint.y;
                        machine.manualToolChangeLocationFromMZZ = currentPoint.z;
                    }}
                >
                    Capture Current Position
                </Button>
            </Grid>
        </Grid>
    );
}
