import { ContentCopy, ExpandMore, Search } from '@mui/icons-material';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Card,
  CardContent,
  Chip,
  Grid,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Tooltip,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { SystemIcons } from '../../../SystemIcons';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { LogCategory, Logger } from '../../../utils/Logger';

/**
 * Icon Inventory Tab - Comprehensive catalog of all icons used in the system
 * Designed to help designers understand current icon usage and create better replacements
 */
export function IconInventoryTab() {
  const colors = ConfigurationDataColors.Instance;
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedCategory, setExpandedCategory] = useState<string | false>(false);
  const [copiedIcon, setCopiedIcon] = useState<string | null>(null);

  const config = ConfigurationData.Instance;

  // Get all icons organized by category
  const iconCategories = SystemIcons.getAllIcons();
  const iconUsage: Record<string, string[]> = SystemIcons.getIconUsage();

  // Filter icons based on search term
  const filteredCategories = Object.entries(iconCategories).reduce((acc, [category, icons]) => {
    const filteredIcons = Object.entries(icons).filter(([iconName]) =>
      iconName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      category.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (filteredIcons.length > 0) {
      acc[category] = Object.fromEntries(filteredIcons);
    }

    return acc;
  }, {} as Record<string, Record<string, React.ReactElement>>);

  // Copy icon name to clipboard
  const handleCopyIconName = async (iconName: string) => {
    try {
      await navigator.clipboard.writeText(`SystemIcons.${iconName}`);
      setCopiedIcon(iconName);
      setTimeout(() => setCopiedIcon(null), 2000);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to copy icon name:', error);
    }
  };

  // Handle accordion expansion
  const handleAccordionChange = (category: string) => (event: React.SyntheticEvent, isExpanded: boolean) => {
    setExpandedCategory(isExpanded ? category : false);
  };

  // Get total icon count
  const totalIcons = Object.values(iconCategories).reduce((total, icons) => total + Object.keys(icons).length, 0);
  const filteredIconCount = Object.values(filteredCategories).reduce((total, icons) => total + Object.keys(icons).length, 0);

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 3 }}>
        <Typography variant="h4" gutterBottom sx={{ color: colors.primaryColor }}>
          Icon Inventory
        </Typography>
        <Typography variant="subtitle1" color="text.secondary" sx={{ mb: 2 }}>
          Comprehensive catalog of all icons used throughout the HavenCNC system
        </Typography>

        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="body2">
            This inventory catalogs all {totalIcons} icons currently used in the system.
            Each icon is shown with its usage context to help designers understand the application's visual language.
            All icons are managed through the <code>SystemIcons</code> class for easy replacement.
          </Typography>
        </Alert>
      </Box>

      {/* Search and Stats */}
      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              placeholder="Search icons by name or category..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />,
              }}
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
              <Chip
                label={`Total Icons: ${totalIcons}`}
                color="primary"
                variant="outlined"
              />
              {searchTerm && (
                <Chip
                  label={`Filtered: ${filteredIconCount}`}
                  color="secondary"
                  variant="outlined"
                />
              )}
              <Chip
                label={`Categories: ${Object.keys(filteredCategories).length}`}
                color="default"
                variant="outlined"
              />
            </Box>
          </Grid>
        </Grid>
      </Paper>

      {/* Icon Categories */}
      <Box>
        {Object.entries(filteredCategories).map(([category, icons]) => (
          <Accordion
            key={category}
            expanded={expandedCategory === category}
            onChange={handleAccordionChange(category)}
            sx={{ mb: 1 }}
          >
            <AccordionSummary
              expandIcon={<ExpandMore />}
              sx={{
                backgroundColor: colors.lightBackgroundColor,
                '&:hover': { backgroundColor: colors.borderColor }
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                <Typography variant="h6" sx={{ color: colors.primaryColor }}>
                  {category}
                </Typography>
                <Chip
                  label={`${Object.keys(icons).length} icons`}
                  size="small"
                  color="primary"
                  variant="outlined"
                />
              </Box>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={2}>
                {Object.entries(icons).map(([iconName, iconElement]) => (
                  <Grid item xs={12} sm={6} md={4} lg={3} key={iconName}>
                    <Card
                      sx={{
                        height: '100%',
                        transition: 'all 0.2s',
                        '&:hover': {
                          transform: 'translateY(-2px)',
                          boxShadow: 3,
                          borderColor: colors.primaryColor
                        }
                      }}
                    >
                      <CardContent sx={{ textAlign: 'center', pb: 1 }}>
                        {/* Icon Display */}
                        <Box
                          sx={{
                            p: 2,
                            mb: 2,
                            borderRadius: 1,
                            backgroundColor: colors.lightBackgroundColor,
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            minHeight: 60
                          }}
                        >
                          <Box sx={{ fontSize: '2rem', color: colors.primaryColor }}>
                            {iconElement}
                          </Box>
                        </Box>

                        {/* Icon Name */}
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                          <Typography variant="subtitle2" fontWeight="bold">
                            {iconName}
                          </Typography>
                          <Tooltip title={copiedIcon === iconName ? 'Copied!' : 'Copy SystemIcons.{name}'}>
                            <IconButton
                              size="small"
                              onClick={() => handleCopyIconName(iconName)}
                              sx={{ color: copiedIcon === iconName ? 'success.main' : 'text.secondary' }}
                            >
                              <ContentCopy fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>

                        {/* Usage Information */}
                        {iconUsage[iconName] && (
                          <Box sx={{ textAlign: 'left' }}>
                            <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                              Used in:
                            </Typography>
                            <Box sx={{ mt: 0.5 }}>
                              {iconUsage[iconName].map((usage: string, index: number) => (
                                <Chip
                                  key={index}
                                  label={usage}
                                  size="small"
                                  variant="outlined"
                                  sx={{
                                    m: 0.25,
                                    fontSize: '0.7rem',
                                    height: 20
                                  }}
                                />
                              ))}
                            </Box>
                          </Box>
                        )}

                        {/* Code Reference */}
                        <Box sx={{ mt: 1, textAlign: 'left' }}>
                          <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                            Code:
                          </Typography>
                          <Typography
                            variant="caption"
                            sx={{
                              fontFamily: 'monospace',
                              backgroundColor: colors.darkBackgroundColor,
                              color: colors.lightTextColor,
                              px: 1,
                              py: 0.5,
                              borderRadius: 0.5,
                              display: 'block',
                              mt: 0.5,
                              fontSize: '0.75rem'
                            }}
                          >
                            SystemIcons.{iconName}
                          </Typography>
                        </Box>
                      </CardContent>
                    </Card>
                  </Grid>
                ))}
              </Grid>
            </AccordionDetails>
          </Accordion>
        ))}
      </Box>

      {/* Usage Summary Table */}
      <Box sx={{ mt: 4 }}>
        <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor }}>
          Implementation Guide
        </Typography>

        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow sx={{ backgroundColor: colors.lightBackgroundColor }}>
                <TableCell><strong>Component Type</strong></TableCell>
                <TableCell><strong>Current Implementation</strong></TableCell>
                <TableCell><strong>New Implementation</strong></TableCell>
                <TableCell><strong>Benefits</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              <TableRow>
                <TableCell>Direct Import</TableCell>
                <TableCell>
                  <code>import {'{ Add }'} from '@mui/icons-material';</code>
                </TableCell>
                <TableCell>
                  <code>import {'{ SystemIcons }'} from '../SystemIcons';</code>
                </TableCell>
                <TableCell>Centralized management, easy replacement</TableCell>
              </TableRow>
              <TableRow>
                <TableCell>Icon Usage</TableCell>
                <TableCell>
                  <code>{'<Add />'}</code>
                </TableCell>
                <TableCell>
                  <code>{'{SystemIcons.add}'}</code>
                </TableCell>
                <TableCell>Consistent naming, single source of truth</TableCell>
              </TableRow>
              <TableRow>
                <TableCell>With Props</TableCell>
                <TableCell>
                  <code>{'<Add fontSize="large" color="primary" />'}</code>
                </TableCell>
                <TableCell>
                  <code>{'{SystemIcons.withProps(SystemIcons.add, { fontSize: "large" })}'}</code>
                </TableCell>
                <TableCell>Flexible customization while maintaining centralization</TableCell>
              </TableRow>
            </TableBody>
          </Table>
        </TableContainer>
      </Box>

      {/* Footer Notes */}
      <Alert severity="success" sx={{ mt: 3 }}>
        <Typography variant="body2">
          <strong>For Designers:</strong> Each icon shown above represents a specific function or concept in the CNC workflow.
          When creating replacement icons, consider the context and usage patterns described for each icon.
          The current icons use Material-UI's design language - new icons should maintain similar visual weight and style consistency.
        </Typography>
      </Alert>
    </Box>
  );
}
