import { Build as ToolIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineData } from '../../data/Machine/MachineData';
import { LogCategory, Logger } from '../Logger';
import { IUserAction } from './IUserAction';

/**
 * User action for measuring all tools in the ATC
 * Only available when machine has ATC configured
 */
export class MeasureAllToolsUserAction implements IUserAction {
    public readonly id = 'tool_management_measure_all_tools';
    public readonly category = 'Tool Management';

    public isAvailable(): boolean {
        // Only available if machine has ATC, is homed, and no job is running
        const config = ConfigurationState.Instance;
        return MachineData.Instance.hasATC && config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <ToolIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Measure All Tools
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <ToolIcon />
                    <Typography>Measure All Tools</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        try {
            const { MeasureAllToolsWizard } = await import('../../components/wizards/measurealltools/MeasureAllToolsWizard');
            MeasureAllToolsWizard.show();
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to start measure all tools wizard:', error);
        }
    }
}
