import { Box, Button, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { WizardStep } from '../../../Wizard/WizardStep';
import { AxisCalibrationWizard } from '../AxisCalibrationWizard';
import { ReviewAdjustmentStep } from './ReviewAdjustmentStep';

/**
 * Step to enter the actual measured distance
 */
export class MeasureActualStep extends WizardStep {
    getTitle(): string {
        const wizard = this.wizard as AxisCalibrationWizard;
        return `Measure ${wizard.state.selectedAxis} Axis Travel`;
    }

    nextStep(): WizardStep | null {
        return new ReviewAdjustmentStep(this.wizard as AxisCalibrationWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="measure-actual-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <MeasureActualStepComponent step={this} />}
            />
        );
    }
}

interface MeasureActualStepComponentProps {
    step: MeasureActualStep;
}

function MeasureActualStepComponent({ step }: MeasureActualStepComponentProps) {
    const wizard = step.wizard as AxisCalibrationWizard;
    const colors = ConfigurationDataColors.Instance;

    const [actualDistance, setActualDistance] = useState<string>(wizard.state.actualDistance?.toString() || '');
    const [isValid, setIsValid] = useState(false);

    const axisName = wizard.state.selectedAxis;
    const commandedDistance = wizard.state.commandedDistance || 0;

    const handleDistanceChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const value = event.target.value;
        setActualDistance(value);

        const numValue = parseFloat(value);
        setIsValid(!isNaN(numValue) && numValue > 0);
    };

    const handleContinue = () => {
        const numValue = parseFloat(actualDistance);
        if (!isNaN(numValue) && numValue > 0) {
            wizard.state = {
                ...wizard.state,
                actualDistance: numValue
            };
            wizard.advanceToNextStep();
        }
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Step 3: How Far Did You Move?
                </Typography>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Look at your measuring device and enter the distance you actually moved the {axisName} axis.
                </Typography>
            </Box>

            {/* Main content */}
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 3 }}>
                {/* Commanded distance display */}
                <Box sx={{
                    p: 3,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    border: `1px solid ${colors.borderColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.mutedTextColor, mb: 2 }}>
                        Machine Reported Movement:
                    </Typography>
                    <Typography variant="h4" sx={{ color: colors.primaryColor, fontWeight: 'bold', fontFamily: 'monospace' }}>
                        {commandedDistance.toFixed(4)} inches
                    </Typography>
                    <Typography variant="caption" sx={{ color: colors.mutedTextColor, mt: 1 }}>
                        (Distance based on machine coordinates)
                    </Typography>
                </Box>

                {/* Actual distance input */}
                <Box sx={{
                    p: 3,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    border: `1px solid ${colors.borderColor}`
                }}>
                    <Typography variant="subtitle1" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 2 }}>
                        Enter Actual Distance Measured
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <TextField
                            type="number"
                            value={actualDistance}
                            onChange={handleDistanceChange}
                            placeholder="0.0000"
                            autoFocus
                            inputProps={{
                                min: 0,
                                step: 0.0001,
                                style: {
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    textAlign: 'right'
                                }
                            }}
                            sx={{ flex: 1, maxWidth: '300px' }}
                        />
                        <Typography variant="h6" sx={{ color: colors.darkTextColor }}>
                            inches
                        </Typography>
                    </Box>
                </Box>

                {/* Instructions */}
                <Box sx={{
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Tips for Accurate Measurement:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        • Use the most precise measuring tool available (dial indicator preferred)
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        • Measure from a fixed reference point (not a moving part)
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        • Account for any backlash in the measurement
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        • Enter the value with as much precision as your tool provides
                    </Typography>
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleContinue}
                    disabled={!isValid}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    Continue
                </Button>
            </Box>
        </Box>
    );
}
