import { IStorable } from '../../../common/IStorable';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';

/**
 * Visibility enum for PLC declarations
 */
export enum Visibility {
    Hidden = 'Hidden',
    Visible = 'Visible',
    Block = 'Block'
}

/**
 * Data type enum for PLC declarations
 */
export enum DataType {
    Input = 'Input',
    Output = 'Output',
    MemoryBit = 'Memory Bit',
    Stage = 'Stage',
    FastStage = 'Fast Stage',
    Word = 'Word',
    DoubleWord = 'Double Word',
    FloatingPointWord = 'Floating-point Word',
    DoubleFloatingPointWord = 'Double-Floating-point Word',
    OneShot = 'One-Shot',
    Timer = 'Timer',
    M94M95Trigger = 'M94/M95 Trigger'
}

/**
 * Format a declaration name with the appropriate suffix based on its data type
 * @param baseName The base name entered by the user
 * @param dataType The data type of the declaration
 * @returns Formatted name with uppercase and type suffix
 */
export function formatDeclarationName(baseName: string, dataType: DataType): string {
    // Convert to uppercase and replace spaces with underscores
    const upperName = baseName.trim().toUpperCase().replace(/\s+/g, '_');

    // Remove existing suffix if present (to allow changing types)
    let cleanName = upperName;
    const suffixes = ['_DFW', '_FW', '_DW', '_M', '_W', '_PD', '_I', '_O', '_KB', '_T', '_MM'];
    for (const suffix of suffixes) {
        if (cleanName.endsWith(suffix)) {
            cleanName = cleanName.substring(0, cleanName.length - suffix.length);
            break;
        }
    }

    // Add appropriate suffix based on data type
    switch (dataType) {
        case DataType.MemoryBit:
            return cleanName + '_M';
        case DataType.Word:
            return cleanName + '_W';
        case DataType.DoubleWord:
            return cleanName + '_DW';
        case DataType.FloatingPointWord:
            return cleanName + '_FW';
        case DataType.DoubleFloatingPointWord:
            return cleanName + '_DFW';
        case DataType.OneShot:
            return cleanName + '_PD';
        case DataType.Input:
            return cleanName + '_I';
        case DataType.Output:
            return cleanName + '_O';
        case DataType.Timer:
            return cleanName + '_T';
        case DataType.M94M95Trigger:
            // For M94/M95, only add suffix if it's not just "M" followed by numbers
            // If it's like "M15" or "M94", leave it alone. If it's a custom name, add _MM
            if (/^M\d+$/.test(cleanName)) {
                return cleanName; // Leave M## format alone
            }
            return cleanName + '_MM';
        default:
            // For other types (Stage, FastStage, etc.), just return uppercase without suffix
            return cleanName;
    }
}

/**
 * Format a keybinding name with the appropriate suffix
 * @param baseName The base name entered by the user
 * @returns Formatted name with uppercase and _KB suffix
 */
export function formatKeybindingName(baseName: string): string {
    // Convert to uppercase and replace spaces with underscores
    const upperName = baseName.trim().toUpperCase().replace(/\s+/g, '_');

    // Remove existing _KB suffix if present
    let cleanName = upperName;
    if (cleanName.endsWith('_KB')) {
        cleanName = cleanName.substring(0, cleanName.length - 3);
    }

    return cleanName + '_KB';
}

/**
 * Format a stage name with the appropriate suffix
 * @param baseName The base name entered by the user
 * @returns Formatted name with uppercase and _S suffix
 */
export function formatStageName(baseName: string): string {
    // Convert to uppercase and replace spaces with underscores
    const upperName = baseName.trim().toUpperCase().replace(/\s+/g, '_');

    // Remove existing _S suffix if present
    let cleanName = upperName;
    if (cleanName.endsWith('_S')) {
        cleanName = cleanName.substring(0, cleanName.length - 2);
    }

    return cleanName + '_S';
}

/**
 * Declaration class for PLC editor
 * Represents a variable or constant declaration in the PLC program
 */
export class Declaration implements IStorable {
    private _name: string = '';
    private _displayName?: string;
    private _description: string = '';
    private _dataType: DataType = DataType.MemoryBit;
    private _category: string[] = [];
    private _visibility: Visibility = Visibility.Visible;
    private _readOnly: boolean = false;
    private _isSystem: boolean = false; // means we do not output it in plc.
    private _memoryLocation?: number;
    private _mappedToLocation?: string;
    private _isConstant: boolean = false;
    private _constantValue?: number;
    private _isSetText: string = 'Set';
    private _isResetText: string = 'Reset';

    constructor(name: string = '') {
        this._name = name;
    }

    /**
     * Name of the declaration
     */
    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
    }

    /**
     * Display name for the declaration
     * Returns name if displayName is not set
     */
    public get displayName(): string {
        return this._displayName || this._name;
    }

    public set displayName(value: string | undefined) {
        this._displayName = value;
        StateManager.propertyChanged(this, 'displayName');
    }

    /**
     * Description of the declaration
     */
    public get description(): string {
        return this._description;
    }

    public set description(value: string) {
        this._description = value;
        StateManager.propertyChanged(this, 'description');
    }

    /**
     * Data type of the declaration
     */
    public get dataType(): DataType {
        return this._dataType;
    }

    public set dataType(value: DataType) {
        this._dataType = value;
        StateManager.propertyChanged(this, 'dataType');
    }

    /**
     * Category tags for organizing declarations
     */
    public get category(): string[] {
        return [...this._category];
    }

    public set category(value: string[]) {
        this._category = [...value];
        StateManager.propertyChanged(this, 'category');
    }

    /**
     * Visibility setting for the declaration
     */
    public get visibility(): Visibility {
        return this._visibility;
    }

    public set visibility(value: Visibility) {
        this._visibility = value;
        StateManager.propertyChanged(this, 'visibility');
    }

    /**
     * Whether the declaration is read-only
     */
    public get readOnly(): boolean {
        return this._readOnly;
    }

    public set readOnly(value: boolean) {
        this._readOnly = value;
        StateManager.propertyChanged(this, 'readOnly');
    }

    /**
     * Whether this is a system-level declaration
     */
    public get isSystem(): boolean {
        return this._isSystem;
    }

    public set isSystem(value: boolean) {
        this._isSystem = value;
        StateManager.propertyChanged(this, 'isSystem');
    }

    /**
     * Optional memory location for the declaration
     */
    public get memoryLocation(): number | undefined {
        return this._memoryLocation;
    }

    public set memoryLocation(value: number | undefined) {
        this._memoryLocation = value;
        StateManager.propertyChanged(this, 'memoryLocation');
    }

    /**
     * Optional mapped-to location for the declaration
     */
    public get mappedToLocation(): string | undefined {
        return this._mappedToLocation;
    }

    public set mappedToLocation(value: string | undefined) {
        this._mappedToLocation = value;
        StateManager.propertyChanged(this, 'mappedToLocation');
    }

    /**
     * Whether this declaration is a constant
     */
    public get isConstant(): boolean {
        return this._isConstant;
    }

    public set isConstant(value: boolean) {
        this._isConstant = value;
        StateManager.propertyChanged(this, 'isConstant');
    }

    /**
     * Constant value (only applicable if isConstant is true)
     */
    public get constantValue(): number | undefined {
        return this._constantValue;
    }

    public set constantValue(value: number | undefined) {
        this._constantValue = value;
        StateManager.propertyChanged(this, 'constantValue');
    }

    /**
     * Text to display when the memory bit is set (true/active)
     */
    public get isSetText(): string {
        return this._isSetText;
    }

    public set isSetText(value: string) {
        this._isSetText = value;
        StateManager.propertyChanged(this, 'isSetText');
    }

    /**
     * Text to display when the memory bit is reset (false/inactive)
     */
    public get isResetText(): string {
        return this._isResetText;
    }

    public set isResetText(value: string) {
        this._isResetText = value;
        StateManager.propertyChanged(this, 'isResetText');
    }

    /**
     * Clone this declaration
     */
    public clone(): Declaration {
        const cloned = new Declaration();
        cloned.name = this.name;
        cloned.displayName = this._displayName; // Use private field to preserve undefined
        cloned.description = this.description;
        cloned.dataType = this.dataType;
        cloned.category = this.category;
        cloned.visibility = this.visibility;
        cloned.readOnly = this.readOnly;
        cloned.isSystem = this.isSystem;
        cloned.memoryLocation = this.memoryLocation;
        cloned.mappedToLocation = this.mappedToLocation;
        cloned.isConstant = this.isConstant;
        cloned.constantValue = this.constantValue;
        cloned.isSetText = this.isSetText;
        cloned.isResetText = this.isResetText;
        return cloned;
    }

    /**
     * Chainable method to set data type (useful for tests and initialization)
     */
    public setDataType(type: DataType): Declaration {
        this._dataType = type;
        return this;
    }

    /**
     * Serialize to JSON using generic DataUtilities approach
     */
    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    /**
     * Load from JSON using generic DataUtilities approach
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
