import { PLCProgram, PLCProgramSystem } from '../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../centroid/plc/data/PLCUtilities';
import { MachineData } from '../data/Machine/MachineData';
import { PLCInputName } from '../data/PLCIONames';
import { Machine } from '../machine/Machine';
import { PLCComparisonResult } from '../services/src/models/PLCComparisonResult';
import { PLCCompilationResult } from '../services/src/models/PLCCompilationResult';
import { PLCInstallationResult } from '../services/src/models/PLCInstallationResult';
import { LogCategory, Logger } from './Logger';

/**
 * Result of complete machine installation
 */
export interface MachineInstallationResult {
    plcInstallation: PLCInstallationResult;
    configurationApplied: boolean;
    success: boolean;
    message: string;
}

/**
 * Utility class for installing complete machine configuration
 * Handles PLC installation and machine configuration in a coordinated way
 */
export class MachineInstaller {
    /**
     * Compare current PLC program with installed version
     * @returns Comparison result indicating if they differ
     */
    public static async comparePLCWithInstalled(): Promise<PLCComparisonResult> {
        try {
            const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
            const plcCode = system.generateCompletePLCCode();
            const sourceLines = plcCode.split('\n');

            const machineInterface = Machine.getInstance();
            const result = await machineInterface.plc.ComparePLC(sourceLines);

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Failed to compare PLC:', error);
            throw error;
        }
    }

    /**
     * Get the currently installed PLC source code
     * @returns Array of source code lines, or null if no installed PLC exists
     */
    public static async getInstalledPLC(): Promise<string[] | null> {
        try {
            const machineInterface = Machine.getInstance();
            const sourceLines = await machineInterface.plc.GetInstalledPLC();

            return sourceLines;
        } catch (error) {
            return null;
        }
    }

    /**
     * Get the currently installed message file
     * @returns Array of message lines, or null if no installed messages exist
     */
    public static async getInstalledMessages(): Promise<string[] | null> {
        try {
            const machineInterface = Machine.getInstance();
            const messageLines = await machineInterface.plc.GetInstalledMessages();

            return messageLines;
        } catch (error) {
            return null;
        }
    }

    /**
     * Install PLC program with messages and estop configuration
     * @returns Installation result
     */
    public static async installPLC(): Promise<PLCInstallationResult> {
        try {
            const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
            const plcCode = system.generateCompletePLCCode();
            const messageFile = system.generateMessageFile();

            const sourceLines = plcCode.split('\n');
            const messageLines = messageFile.split('\n');

            // Get estop configuration from System PLC
            const estopInput = system.inputs.find(input =>
                input.centroidName === PLCInputName.EStopOk ||
                input.name?.toUpperCase() === PLCInputName.EStopOk
            );
            const estopInputNumber = estopInput?.number;
            const invertEstopInput = estopInput?.isInverted || false;

            // Build monitored I/O lists from all inputs and outputs in System PLC
            const inputsToMonitor = system.inputs
                .filter(input => input.number !== undefined && input.number !== null && input.number >= 0)
                .map(input => ({
                    number: input.number ?? undefined,  // Convert null to undefined
                    name: input.centroidName || input.name || `Input${input.number}`
                }));

            const outputsToMonitor = system.outputs
                .filter(output => output.number !== undefined && output.number !== null && output.number >= 0)
                .map(output => ({
                    number: output.number ?? undefined,  // Convert null to undefined
                    name: output.centroidName || output.name || `Output${output.number}`
                }));

            const machineInterface = Machine.getInstance();
            const result = await machineInterface.plc.CompileAndInstallPLC(
                sourceLines,
                messageLines,
                estopInputNumber ?? undefined,  // Convert null to undefined
                invertEstopInput,
                inputsToMonitor.length > 0 ? inputsToMonitor : [],
                outputsToMonitor.length > 0 ? outputsToMonitor : []
            );

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Failed to install PLC:', error);
            throw error;
        }
    }

    /**
     * Test compile PLC program without installing
     * @returns Compilation result
     */
    public static async testCompilePLC(): Promise<PLCCompilationResult> {
        try {
            const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
            const plcCode = system.generateCompletePLCCode();
            const sourceLines = plcCode.split('\n');

            const machineInterface = Machine.getInstance();
            const result = await machineInterface.plc.CompilePLC(sourceLines);

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'testCompilePLC: Error during compilation:', error);
            Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Failed to test compile PLC:', error);
            throw error;
        }
    }

    /**
     * Apply machine configuration to the CNC controller
     * Uses MachineData to generate configuration and applies it via setup interface
     * @returns True if configuration was applied successfully
     */
    public static async applyMachineConfiguration(): Promise<boolean> {
        try {
            const machineData = MachineData.Instance;
            const config = await machineData.toCompleteMachineConfiguration();

            const machineInterface = Machine.getInstance();
            const result = await machineInterface.setup.ConfigureCompleteMachine(config);

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Failed to apply machine configuration:', error);
            throw error;
        }
    }

    /**
     * Perform complete machine installation
     * Installs PLC program with messages and applies all machine configuration
     * @returns Complete installation result with details
     */
    public static async installCompleteMachine(): Promise<MachineInstallationResult> {
        try {
            // Step 1: Install PLC program
            const plcInstallation = await this.installPLC();

            if (!plcInstallation.installationSuccess || !plcInstallation.compilationResult?.success) {
                Logger.Instance.logError(LogCategory.System, 'MachineInstaller: PLC installation failed', plcInstallation);
                return {
                    plcInstallation,
                    configurationApplied: false,
                    success: false,
                    message: 'PLC installation failed: ' + (plcInstallation.message || 'Unknown error')
                };
            }

            // Step 2: Apply machine configuration
            try {
                const configurationApplied = await this.applyMachineConfiguration();

                if (!configurationApplied) {
                    Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Configuration application returned false');
                    return {
                        plcInstallation,
                        configurationApplied: false,
                        success: false,
                        message: 'PLC installed successfully, but machine configuration failed to apply'
                    };
                }
            } catch (configError) {
                Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Configuration application threw error:', configError);
                return {
                    plcInstallation,
                    configurationApplied: false,
                    success: false,
                    message: `PLC installed successfully, but machine configuration failed: ${configError instanceof Error ? configError.message : String(configError)}`
                };
            }

            // Success!
            return {
                plcInstallation,
                configurationApplied: true,
                success: true,
                message: 'Machine installation completed successfully'
            };

        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'MachineInstaller: Complete installation failed:', error);
            throw error;
        }
    }
}
