import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { WarmUpInstructionsStep } from "./steps/WarmUpInstructionsStep";

export interface WarmUpSpindleState {
  currentStage: number; // 0=not started, 1=moving to safe position, 2=40% warmup, 3=70% warmup, 4=90% warmup, 5=done
  stageStartTime: number;
  isWarmingUp: boolean;
  timeRemaining: number;
  isStopped: boolean;
  isComplete: boolean;
}

export class WarmUpSpindleWizard extends Wizard<WarmUpSpindleState> {
  constructor() {
    const initialState: WarmUpSpindleState = {
      currentStage: 0,
      stageStartTime: 0,
      isWarmingUp: false,
      timeRemaining: 120,
      isStopped: false,
      isComplete: false
    };

    super(
      null as any, // Temporary - will be set below
      initialState,
      true, // canClose
      false, // clickAwayClose - don't allow accidental closure during warm-up
      '80%', // width
      '85%'  // height
    );

    // Now create the step with proper wizard reference
    const firstStep = new WarmUpInstructionsStep(this, null);
    this.firstStep = firstStep;
    this.currentStep = firstStep;
  }

  // Override closeWizard to clean up any running timers
  closeWizard(): void {
    const intervalId = (this as any).intervalId;
    if (intervalId) {
      clearInterval(intervalId);
      (this as any).intervalId = null;
    }
    super.closeWizard();
  }

  static show(): void {
    const wizard = new WarmUpSpindleWizard();
    WizardManager.Instance.start(wizard);
  }
}
