import { Box } from '@react-three/drei';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';

export interface VerticalTableProps {
  simulatorView: SimulatorView;
}

export function VerticalTable({ simulatorView }: VerticalTableProps) {
  const machineData = MachineData.Instance;
  const machineState = MachineStateData.Instance;
  const colors = ConfigurationDataColors.Instance;

  // Don't render if vertical table is not enabled
  if (!machineData.hasVerticalTable) {
    return null;
  }

  return (
    <ObserveMultiProperties
      key="vertical-table-observer"
      listenTo={[
        { object: machineData, properties: ['verticalTableOffset', 'verticalTableAngle', 'hasVerticalTable'] },
        { object: colors, properties: ['verticalTableColor', 'verticalTableTransparency'] },
        { object: simulatorView, properties: ['verticalTable'] }
      ]}
      control={() => {
        // Use centralized vertical table box for dimensions
        const verticalTableBox = CoordinateUtil.getVerticalTableBox(machineState);

        if (!verticalTableBox) {
          return null;
        }

        // Convert box origin to simulator coordinates first
        const tableOriginSim = CoordinateUtil.toSimulator(verticalTableBox.origin);

        // Then calculate center position in simulator space by adding half dimensions
        const tablePosition = {
          x: tableOriginSim.x + verticalTableBox.width / 2,
          y: tableOriginSim.y + verticalTableBox.length / 2,
          z: tableOriginSim.z + verticalTableBox.height / 2
        };

        // Convert angle from degrees to radians
        const angleRadians = (machineData.verticalTableAngle * Math.PI) / 180;

        // Determine material properties based on ViewStyle
        const isTransparent = simulatorView.verticalTable === ViewStyle.SemiTransparent;
        const isWireframe = simulatorView.verticalTable === ViewStyle.Wireframe;
        const opacity = isTransparent ? (colors.verticalTableTransparency || 0.8) : 1.0;

        // Create unique key for React re-rendering when material properties change
        const renderKey = `vertical-table-${ViewStyle[simulatorView.verticalTable]}-${opacity}-${colors.verticalTableColor}-${Date.now()}`;

        return (
          <group>
            <Box
              key={renderKey}
              position={[tablePosition.x, tablePosition.y, tablePosition.z]}
              args={[verticalTableBox.width, verticalTableBox.length, verticalTableBox.height]}
              rotation={[angleRadians - Math.PI / 2, 0, 0]} // Rotate from horizontal (default) to specified angle
            >
              <meshPhongMaterial
                color={colors.verticalTableColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>
          </group>
        );
      }}
    />
  );
}
