import { Box, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ObserveState } from '../../utils/statemanager/ObserveState';

/**
 * Coordinate display component showing current machine position
 * Read-only X/Y/Z coordinates with formatted decimal precision
 */
export function CoordinateDisplay() {
    const colors = ConfigurationDataColors.Instance;

    return (
        <ObserveState
            key="coordinate-display"
            listenTo={ConfigurationState.Instance}
            properties={['currentMachinePoint']}
            control={() => {
                const pos = ConfigurationState.Instance.currentMachinePoint;
                return (
                    <Box sx={{
                        width: '100%',
                        p: 2,
                        borderRadius: 1,
                        backgroundColor: colors.lightBackgroundColor,
                        border: `1px solid ${colors.borderColor}`
                    }}>
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1, fontWeight: 'bold', textAlign: 'center' }}>
                            Current Position
                        </Typography>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography variant="body2" fontWeight="bold">X:</Typography>
                                <Typography variant="body2" fontFamily="monospace">{pos.x.toFixed(4)}</Typography>
                            </Box>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography variant="body2" fontWeight="bold">Y:</Typography>
                                <Typography variant="body2" fontFamily="monospace">{pos.y.toFixed(4)}</Typography>
                            </Box>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography variant="body2" fontWeight="bold">Z:</Typography>
                                <Typography variant="body2" fontFamily="monospace">{pos.z.toFixed(4)}</Typography>
                            </Box>
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
