import { Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControlLabel,
    IconButton,
    Switch,
    TextField
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { BasePLCStatement } from '../statements/BasePLCStatement';

interface StatementDialogProps {
    open: boolean;
    statement: BasePLCStatement;
    onClose: () => void;
    onSave: (description: string, enabled: boolean) => void;
}

/**
 * Dialog for editing a PLC statement's properties
 */
export function StatementDialog({ open, statement, onClose, onSave }: StatementDialogProps) {
    const [description, setDescription] = useState('');
    const [enabled, setEnabled] = useState(true);
    const colors = ConfigurationDataColors.Instance;

    // Initialize form when dialog opens or statement changes
    useEffect(() => {
        if (open && statement) {
            setDescription(statement.comment || '');
            setEnabled(statement.enabled);
        }
    }, [open, statement]);

    const handleSave = () => {
        onSave(description.trim(), enabled);
        onClose();
    };

    const handleCancel = () => {
        onClose();
    };

    return (
        <Dialog open={open} onClose={handleCancel} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Edit Statement
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                    {/* Description */}
                    <TextField
                        label="Description"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        placeholder="Optional description or comment"
                        multiline
                        rows={3}
                        fullWidth
                        autoFocus
                    />

                    {/* Enabled Toggle */}
                    <Box>
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={enabled}
                                    onChange={(e) => setEnabled(e.target.checked)}
                                    sx={{
                                        '& .MuiSwitch-switchBase.Mui-checked': {
                                            color: colors.primaryColor,
                                        },
                                        '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                                            backgroundColor: colors.primaryColor,
                                        },
                                    }}
                                />
                            }
                            label="Statement Enabled"
                        />
                    </Box>
                </Box>
            </DialogContent>

            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={handleCancel}>Cancel</Button>
                <Button
                    onClick={handleSave}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
}
