import React from 'react';
import { IStorable } from '../../../common/IStorable';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElementButton } from './DataElementButton';
import { DataType, Declaration, Visibility } from './Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode, PLCValidationIssue } from './IPLCElement';
import { IPLCSource, PLCProgramType, PLCSerializationHelper, PLCUtilities } from './PLCUtilities';

/**
 * DataElement class - Basic building block for PLC data
 * Either references an existing declaration by name or creates/stores a new declaration
 * Implements IPLCElement for rendering and code generation
 */
export class DataElement implements IStorable, IPLCElement {
    private _declarationName?: string;
    private _declaration?: Declaration;
    private _plcSource: IPLCSource | undefined;
    private _parentElement: IPLCElement | undefined;  // Parent statement that contains this data element
    private _allowNew: boolean = true;  // Whether to allow creating a new declaration
    private _requiresType?: DataType;   // Optional: Required declaration type
    private _needsWrite: boolean = false;  // Whether this element needs write access (excludes readonly declarations)
    private _cachedLookupDeclaration?: Declaration;  // Cache for looked-up declarations (not serialized)

    constructor(declarationName?: string) {
        this._plcSource = undefined;
        this._declarationName = declarationName;

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Name of the referenced declaration
     */
    public get declarationName(): string | undefined {
        return this._declarationName;
    }

    public set declarationName(value: string | undefined) {
        // Only clear cache if the name actually changed
        if (this._declarationName !== value) {
            this._declarationName = value;
            this._cachedLookupDeclaration = undefined; // Clear cache when name changes
            // Invalidate program cache since this might affect available declarations
            PLCUtilities.invalidateProgramCache();
        }
        StateManager.propertyChanged(this, 'declarationName');
    }

    /**
     * The declaration object (if created locally)
     */
    public get declaration(): Declaration | undefined {
        return this._declaration;
    }

    public set declaration(value: Declaration | undefined) {
        this._declaration = value;
        StateManager.propertyChanged(this, 'declaration');
    }

    public get plcSource(): IPLCSource | undefined {
        // Always resolve fresh - don't cache to avoid stale references
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    /**
     * Get the type of this PLC element
     */
    public getElementType(): 'other' {
        return 'other';
    }

    /**
     * Reset cached state before rendering or code generation
     * Default implementation does nothing
     */
    public preRenderReset(): void {
        // Default: no-op
    }

    /**
     * Get unique identifier for this data element
     */
    public getElementId(): string {
        return this._declarationName || (this._declaration ? this._declaration.name : 'unnamed-data-element');
    }

    /**
     * Get the parent element (statement) that contains this data element
     */
    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    /**
     * Set the parent element that contains this data element
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
    }

    /**
     * Whether to allow creating a new declaration
     */
    public get allowNew(): boolean {
        return this._allowNew;
    }

    public set allowNew(value: boolean) {
        this._allowNew = value;
        StateManager.propertyChanged(this, 'allowNew');
    }

    /**
     * Optional: Required declaration type
     */
    public get requiresType(): DataType | undefined {
        return this._requiresType;
    }

    public set requiresType(value: DataType | undefined) {
        this._requiresType = value;
        StateManager.propertyChanged(this, 'requiresType');
    }

    /**
     * Whether this element needs write access (excludes readonly declarations when true)
     */
    public get needsWrite(): boolean {
        return this._needsWrite;
    }

    public set needsWrite(value: boolean) {
        this._needsWrite = value;
        StateManager.propertyChanged(this, 'needsWrite');
    }

    /**
     * Whether this data element references an existing declaration by name
     */
    public get isReference(): boolean {
        return this._declarationName !== undefined && this._declaration === undefined;
    }

    /**
     * Get the PLCProgram that owns this data element by traversing parent chain
     * @returns The PLCProgram instance or undefined if not found
     */
    public getPLCProgram(): IPLCSource | undefined {
        // Try plcSource first (if set)
        if (this._plcSource) {
            return this._plcSource;
        }

        // Use centralized parent chain resolution
        return PLCUtilities.resolvePLCSource(this);
    }

    /**
     * Whether this data element defines a new declaration
     */
    public get isDefinition(): boolean {
        return this._declaration !== undefined;
    }

    /**
     * Get the effective name (from reference or declaration)
     */
    public get effectiveName(): string | undefined {
        if (this._declaration) {
            return this._declaration.name;
        }
        return this._declarationName;
    }

    /**
     * Create a new declaration for this data element
     */
    public createDeclaration(name: string, dataType: DataType = DataType.MemoryBit): Declaration {
        const decl = new Declaration(name);
        decl.dataType = dataType;
        decl.visibility = Visibility.Visible;
        this._declaration = decl;
        this._declarationName = undefined; // Clear reference when creating declaration
        StateManager.propertyChanged(this, 'declaration');
        // Invalidate program cache since a new declaration was created
        PLCUtilities.invalidateProgramCache();
        // Set up cache invalidation listener for this owned declaration
        PLCUtilities.setupCacheInvalidationListener(decl);
        return decl;
    }

    /**
     * Set a reference to an existing declaration by name
     */
    public setReference(declarationName: string): void {
        this._declarationName = declarationName;
        this._declaration = undefined; // Clear declaration when setting reference
        StateManager.propertyChanged(this, 'declarationName');
        // Invalidate program cache since declaration reference changed
        PLCUtilities.invalidateProgramCache();
    }

    /**
     * Render the data element to JSX for UI display
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <DataElementButton dataElement={this} renderMode={mode} />;
    }

    /**
     * Data elements themselves are never disabled - they're just references to declarations
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return false;
    }

    /**
     * Get declarations that are used/referenced by this data element
     * Returns the declaration whether it's embedded or looked up by name
     */
    public getUsedDeclarations(): Declaration[] {
        // If we have an embedded declaration, return it
        if (this._declaration) {
            return [this._declaration];
        }

        // If this is a reference by name, look it up and return it
        if (this._declarationName) {
            // Check cache first - this prevents redundant lookups
            if (this._cachedLookupDeclaration && this._cachedLookupDeclaration.name === this._declarationName) {
                return [this._cachedLookupDeclaration];
            }

            // Look up the declaration using PLCUtilities safe lookup
            // This searches system declarations AND program-defined declarations (inputs, outputs, stages, etc.)
            // without causing recursion
            const foundDecl = PLCUtilities.lookupDeclarationSafe(this._declarationName);

            if (foundDecl) {
                this._cachedLookupDeclaration = foundDecl;
                return [foundDecl];
            }

            // Declaration not found - return empty array
            // This will be flagged as a validation issue in getValidationIssues()
            this._cachedLookupDeclaration = undefined;
            return [];
        }

        // No declaration set at all
        return [];
    }

    /**
     * Get declarations that are added/defined by this data element
     * CRITICAL: Only return declaration if this is a NEW declaration
     * If _declarationName is set, this is a reference (not a new definition)
     */
    public getAddedDeclarations(): Declaration[] {
        // Only return as "added" if this is a NEW declaration (no declarationName reference)
        if (this._declaration && !this._declarationName) {
            return [this._declaration];
        }
        return [];
    }

    /**
     * Get the PLC logic code for this element
     */
    public getPLCLogic(): string[] {
        // Data elements don't generate logic by themselves
        // They are used by actions to generate logic
        return [];
    }

    /**
     * Get validation issues for this data element
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        // Must be either a reference or a definition, not both or neither
        if (this._declarationName && this._declaration) {
            issues.push(new PLCValidationIssue(this, 'Data element cannot be both a reference and a definition'));
        }

        if (!this._declarationName && !this._declaration) {
            issues.push(new PLCValidationIssue(this, 'Data element must specify either a reference or a definition'));
        }

        // Validate declaration if it exists
        if (this._declaration) {
            if (!this._declaration.name || this._declaration.name.trim() === '') {
                issues.push(new PLCValidationIssue(this, 'Declaration name is required'));
            }
        }

        // Validate reference if it exists
        if (this._declarationName) {
            if (this._declarationName.trim() === '') {
                issues.push(new PLCValidationIssue(this, 'Declaration reference name cannot be empty'));
            } else {
                // Check if the referenced declaration exists
                const foundDecl = PLCUtilities.lookupDeclarationSafe(this._declarationName);
                if (!foundDecl) {
                    issues.push(new PLCValidationIssue(this, `Declaration '${this._declarationName}' not found`));
                }
            }
        }

        return issues;
    }

    /**
     * Determine whether this data element should be output
     * @param outputType The type of output (Render or PLCCode)
     * @param availableDeclarations Optional array of available declaration names
     * @returns OutputState indicating how this data element should be handled
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    /**
     * Serialize to JSON
     * CRITICAL: Only serialize _declaration if this is a NEW declaration (no _declarationName)
     * When _declarationName is set, this is a reference - don't persist the cached declaration object
     * CRITICAL: Exclude _cachedLookupDeclaration - it's a runtime cache only, not persisted
     */
    public toJSON(): any {
        const data: any = PLCSerializationHelper.getStorageData(this, ['_declaration', '_cachedLookupDeclaration']);
        // Only serialize declaration if this is a NEW declaration (no declarationName reference)
        // This prevents duplicate declarations when referencing existing declarations
        if (this._declaration && !this._declarationName) {
            data.declaration = this._declaration.toJSON();
        }
        return data;
    }

    /**
     * Load from JSON
     * Loads both fields if both are present in JSON
     * CRITICAL: Exclude _cachedLookupDeclaration from loading - it's a runtime cache only
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_declaration', 'declaration', '_cachedLookupDeclaration']);
        // Load declaration if present - support both underscore and non-underscore formats for backward compatibility
        const declarationData = data.declaration || data._declaration;
        if (declarationData) {
            this._declaration = new Declaration();
            this._declaration.fromJSON(declarationData);
            // Set up cache invalidation listener for this owned declaration
            PLCUtilities.setupCacheInvalidationListener(this._declaration);
        }

    }
}
