import * as signalR from '@microsoft/signalr';
import {
    CNCMessage,
    DROEvent,
    JobCompletedEvent,
    JobInfoEvent,
    JobStartedEvent,
    MessageEvent,
    OutputStateChangedEvent,
    ServerStatusEvent,
    SignalREvent,
    StepExecutionEvent,
} from '../data/SignalR/SignalREventTypes';
import { SignalRStateData } from '../data/SignalRStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { LogCategory, Logger } from './Logger';
import { MachineInterfaceManager } from './MachineInterfaceManager';

/**
 * Event listener callback type for SignalR events
 */
export type SignalREventListener<T extends SignalREvent = SignalREvent> = (event: T) => void;

/**
 * Connection state enum
 */
export enum ConnectionState {
    Disconnected = 'Disconnected',
    Connecting = 'Connecting',
    Connected = 'Connected',
    Reconnecting = 'Reconnecting',
    Failed = 'Failed',
}

/**
 * SignalRManager - Manages SignalR connection and event distribution
 * Singleton class that connects to the CNC hub and allows components to subscribe to events
 */
export class SignalRManager {
    private static _instance: SignalRManager;
    private _connection: signalR.HubConnection | null = null;
    private _connectionState: ConnectionState = ConnectionState.Disconnected;
    private _listeners: Map<string, Set<SignalREventListener>> = new Map();
    private _serverUrl: string = '';
    private _autoReconnect: boolean = true;
    private _lastConnectionAttempt: number = 0;
    private _connectionFailureNotified: boolean = false;
    private _reconnectAttempts: number = 0;
    private _connectionHealthTimer: NodeJS.Timeout | null = null;
    private _lastMessageReceived: number = 0;
    private _isManualRetry: boolean = false;
    private _failureNotificationTimer: NodeJS.Timeout | null = null;
    private _lastEventTimestamp: string | null = null; // Track last event timestamp for ordering detection

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SignalRManager {
        if (!SignalRManager._instance) {
            SignalRManager._instance = new SignalRManager();
        }
        return SignalRManager._instance;
    }

    /**
     * Get the current connection state
     */
    public get connectionState(): ConnectionState {
        return this._connectionState;
    }

    /**
     * Check if currently connected
     */
    public get isConnected(): boolean {
        return this._connectionState === ConnectionState.Connected;
    }

    /**
     * Auto-initialize using MachineInterfaceManager configuration
     * This will only connect if a server URL is configured (Centroid mode)
     * Returns true if initialization was attempted, false if skipped (simulator mode)
     */
    public async autoInitialize(): Promise<boolean> {
        const manager = MachineInterfaceManager.Instance;
        const serverUrl = manager.getServerUrl();

        if (!serverUrl) {

            return false;
        }

        if (this._connection) {
            return false;
        }

        // Clean the URL the same way MachineInterfaceManager does
        let cleanedUrl = serverUrl.trim();

        try {
            const url = new URL(cleanedUrl);
            // Ensure no trailing slash in the base path (same as MachineInterfaceManager)
            cleanedUrl = url.origin + url.pathname.replace(/\/+$/, '');
        } catch (urlError) {
            Logger.Instance.logError(LogCategory.Network, '[SignalRManager] Invalid URL format:', urlError);
            Logger.Instance.logError(
                LogCategory.Network,
                `Invalid server URL for SignalR: "${serverUrl}"`,
                urlError
            );
            return false;
        }

        Logger.Instance.log(LogCategory.Network, `SignalR connecting to: ${cleanedUrl}`);

        try {
            await this.initialize(cleanedUrl, true);
            return true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, '[SignalRManager] Initialize failed:', error);
            Logger.Instance.logError(
                LogCategory.Network,
                'Failed to auto-initialize SignalR',
                error
            );
            return false;
        }
    }

    /**
     * Initialize the SignalR connection
     * @param serverUrl Base URL of the server (e.g., 'http://localhost:5000')
     * @param autoReconnect Whether to automatically reconnect on disconnect (default: true)
     */
    public async initialize(serverUrl: string, autoReconnect: boolean = true): Promise<void> {

        if (this._connection) {
            Logger.Instance.logError(LogCategory.Network, 'SignalR connection already initialized');
            return;
        }

        this._serverUrl = serverUrl;
        this._autoReconnect = autoReconnect;

        // Update state data
        SignalRStateData.Instance.serverUrl = serverUrl;

        // Build the hub URL
        const hubUrl = `${serverUrl}/cncHub`;

        // Create the connection with automatic reconnect and fast disconnection detection
        const builder = new signalR.HubConnectionBuilder()
            .withUrl(hubUrl)
            .withHubProtocol(new signalR.JsonHubProtocol())
            // Configure aggressive timeout settings to detect server disconnection quickly
            .withServerTimeout(5000)    // 5 seconds - server must respond within this time
            .withKeepAliveInterval(2000); // 2 seconds - send keep-alive every 2 seconds

        if (autoReconnect) {
            // Keep trying forever with fast reconnection (max 500ms delay)
            // Aggressive reconnection strategy for local CNC server
            builder.withAutomaticReconnect({
                nextRetryDelayInMilliseconds: (retryContext) => {
                    // Fast reconnection: 0ms, then 500ms forever
                    return retryContext.previousRetryCount === 0 ? 0 : 500;
                }
            });
        }

        this._connection = builder
            .configureLogging(signalR.LogLevel.Information)
            .build();

        // Set up event handlers
        this._connection.on('ReceiveCNCMessage', (message: CNCMessage) => {
            this._lastMessageReceived = Date.now(); // Track when we received a message
            SignalRStateData.Instance.lastMessageReceived = new Date(); // Update state data

            // Log ALL incoming messages to diagnose structure
            const eventType = message.EventType || message.eventType;
            // Only log non-ServerStatus messages to reduce noise
            // ServerStatus logging is handled by SignalRPositionUpdater when values change
            // DROEvent messages are logged at debug level to reduce noise
            if (eventType !== 'ServerStatus') {
                if (eventType === 'DROEvent') {
                    Logger.Instance.logDebug(
                        LogCategory.Network,
                        `📡 SignalRManager: Received message - EventType="${eventType}", keys=${Object.keys(message).join(', ')}`,
                        message
                    );
                } else {
                    Logger.Instance.log(
                        LogCategory.Network,
                        `📡 SignalRManager: Received message - EventType="${eventType}", keys=${Object.keys(message).join(', ')}`,
                        message
                    );
                }
            }

            // Reset failure notification flag if we're receiving messages consistently
            // This prevents showing "reconnected" messages after brief network hiccups
            if (this._connectionFailureNotified && this._connectionState === ConnectionState.Connected) {
                // If we've been connected and receiving messages for a while, clear the failure flag
                setTimeout(() => {
                    if (this._connectionState === ConnectionState.Connected) {
                        this._connectionFailureNotified = false;
                    }
                }, 5000); // 5 seconds of stability clears the flag
            }

            this._handleCNCMessage(message);
        });

        // Connection lifecycle handlers
        this._connection.onclose((error) => {
            const wasConnected = this._connectionState === ConnectionState.Connected;
            this._connectionState = ConnectionState.Disconnected;
            SignalRStateData.Instance.connectionState = ConnectionState.Disconnected;
            Logger.Instance.logError(LogCategory.Network, 'SignalR connection closed', error);


            // Stop health monitoring when connection closes
            this._stopConnectionHealthMonitoring();

            // If we were connected and this is an unexpected disconnection, start a timer
            // Only show failure message if reconnection doesn't succeed within reasonable time
            if (wasConnected && error && this._autoReconnect) {
                this._startFailureNotificationTimer();
            } else if (wasConnected && error && !this._autoReconnect) {
                // No auto-reconnect, show failure immediately
                this._notifyConnectionFailure('Unable to connect to CNC server');
            }
        });

        this._connection.onreconnecting((error) => {
            this._connectionState = ConnectionState.Reconnecting;
            this._reconnectAttempts++;
            SignalRStateData.Instance.connectionState = ConnectionState.Reconnecting;
            SignalRStateData.Instance.reconnectAttempts = this._reconnectAttempts;


            // Don't show any user messages during reconnection attempts
            // Let the system handle reconnections silently
        });

        this._connection.onreconnected((connectionId) => {
            this._connectionState = ConnectionState.Connected;
            const hadReconnectAttempts = this._reconnectAttempts > 0;
            const hadPreviousFailureNotification = this._connectionFailureNotified;
            this._reconnectAttempts = 0;
            this._connectionFailureNotified = false;
            this._lastMessageReceived = Date.now(); // Reset message timer

            // Update state data for reactive UI
            SignalRStateData.Instance.connectionState = ConnectionState.Connected;
            SignalRStateData.Instance.reconnectAttempts = 0;
            SignalRStateData.Instance.lastMessageReceived = new Date();

            Logger.Instance.log(LogCategory.Network, `SignalR reconnected: ${connectionId}`);


            // Cancel any pending failure notification since we reconnected
            this._cancelFailureNotificationTimer();

            // Start health monitoring for the new connection
            this._startConnectionHealthMonitoring();

            // Only show reconnection success message if we had previously shown a failure message to the user
            if (hadReconnectAttempts && hadPreviousFailureNotification) {
                UserMessageQueue.Instance.addMessage('✓ Reconnected to CNC server');
            }
        });

        // Start the connection
        try {
            await this.connect();
        } catch (error) {
            // Initial connection failed, but automatic reconnect will handle retries
            console.error('[SignalRManager.initialize] ❌ Initial connection failed:', error);
            Logger.Instance.logError(LogCategory.Network, 'Initial SignalR connection failed, automatic reconnect will retry', error);
        }
    }

    /**
     * Connect to the SignalR hub
     */
    public async connect(): Promise<void> {

        if (!this._connection) {
            Logger.Instance.logError(LogCategory.Network, 'SignalR connection not initialized. Call initialize() first.');
            return;
        }

        if (this._connectionState === ConnectionState.Connected ||
            this._connectionState === ConnectionState.Connecting) {
            return;
        }

        // Enforce minimum 1-second interval between connection attempts
        const now = Date.now();
        const timeSinceLastAttempt = now - this._lastConnectionAttempt;
        if (timeSinceLastAttempt < 1000) {
            const delay = 1000 - timeSinceLastAttempt;
            await new Promise(resolve => setTimeout(resolve, delay));
        }
        this._lastConnectionAttempt = Date.now();

        try {
            this._connectionState = ConnectionState.Connecting;
            SignalRStateData.Instance.connectionState = ConnectionState.Connecting;

            await this._connection.start();
            this._connectionState = ConnectionState.Connected;
            SignalRStateData.Instance.connectionState = ConnectionState.Connected;
            const hadPreviousFailure = this._connectionFailureNotified;
            this._connectionFailureNotified = false;
            this._reconnectAttempts = 0;
            this._lastMessageReceived = Date.now(); // Initialize message timer

            // Update state data for reactive UI
            SignalRStateData.Instance.reconnectAttempts = 0;
            SignalRStateData.Instance.lastMessageReceived = new Date();

            Logger.Instance.log(LogCategory.Network, 'SignalR connected');

            // Join the CNCClients group to receive server status and other broadcasts
            try {
                await this._connection.invoke('JoinCNCClients');
            } catch (groupError) {
                console.error('[SignalRManager.connect] ⚠ Failed to join CNCClients group:', groupError);
                Logger.Instance.logError(LogCategory.Network, 'Failed to join CNCClients group:', groupError);
            }

            // Start health monitoring for the new connection
            this._startConnectionHealthMonitoring();

            // Show connection success message if we had previously failed or this is a manual retry
            if (hadPreviousFailure || this._isManualRetry) {
                UserMessageQueue.Instance.addMessage('✓ Connected to CNC server');
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, '[SignalRManager.connect] Connection failed:', error);
            this._connectionState = ConnectionState.Failed;
            SignalRStateData.Instance.connectionState = ConnectionState.Failed;
            Logger.Instance.logError(LogCategory.Network, 'Failed to connect to SignalR hub', error);
            this._notifyConnectionFailure('Unable to connect to CNC server');
            throw error;
        }
    }

    /**
     * Helper method to notify user of connection failures (prevents duplicate notifications)
     */
    private _notifyConnectionFailure(message: string): void {
        if (!this._connectionFailureNotified) {
            UserMessageQueue.Instance.addMessage(`❌ ${message}`);
            this._connectionFailureNotified = true;
        }
    }

    /**
     * Get current reconnect attempt count
     */
    public get reconnectAttempts(): number {
        return this._reconnectAttempts;
    }

    /**
     * Manually retry connection (respects 1-second timing limit)
     */
    public async retryConnection(): Promise<void> {
        if (this._connectionState === ConnectionState.Connected) {

            return;
        }

        this._isManualRetry = true; // Flag to show success message
        try {
            await this.connect();
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, 'Manual connection retry failed', error);
            // Error handling and user notification already handled in connect()
        } finally {
            this._isManualRetry = false;
        }
    }

    /**
     * Disconnect from the SignalR hub
     */
    public async disconnect(): Promise<void> {
        this._stopConnectionHealthMonitoring();
        this._cancelFailureNotificationTimer();

        if (this._connection && this._connectionState !== ConnectionState.Disconnected) {
            try {
                await this._connection.stop();
                this._connectionState = ConnectionState.Disconnected;
                Logger.Instance.log(LogCategory.Network, 'SignalR disconnected');
            } catch (error) {
                Logger.Instance.logError(LogCategory.Network, 'Error disconnecting from SignalR', error);
            }
        }
    }

    /**
     * Start monitoring connection health - detects stale connections
     */
    private _startConnectionHealthMonitoring(): void {
        this._stopConnectionHealthMonitoring();

        // Check connection health every 3 seconds
        this._connectionHealthTimer = setInterval(() => {
            this._checkConnectionHealth();
        }, 3000);
    }

    /**
     * Stop connection health monitoring
     */
    private _stopConnectionHealthMonitoring(): void {
        if (this._connectionHealthTimer) {
            clearInterval(this._connectionHealthTimer);
            this._connectionHealthTimer = null;
            Logger.Instance.log(LogCategory.Network, 'Stopped SignalR connection health monitoring');
        }
    }

    /**
     * Check if connection is truly healthy
     */
    private _checkConnectionHealth(): void {
        if (!this._connection) return;

        const actualConnectionState = this._connection.state;

        // Check if SignalR internal state differs from our tracked state
        if (actualConnectionState === signalR.HubConnectionState.Disconnected &&
            this._connectionState === ConnectionState.Connected) {
            Logger.Instance.logError(LogCategory.Network, 'SignalR connection state mismatch detected - connection lost');
            this._connectionState = ConnectionState.Disconnected;
            SignalRStateData.Instance.connectionState = ConnectionState.Disconnected;
            // Only notify if we haven't already notified about connection issues
            if (!this._connectionFailureNotified) {
                this._notifyConnectionFailure('Connection to CNC server lost');
            }
        }

        // Health check complete - no routine logging needed
        // Extended connection issues will be detected by SignalR's reconnect logic
    }

    /**
     * Start timer to show failure notification if reconnection doesn't succeed
     */
    private _startFailureNotificationTimer(): void {
        this._cancelFailureNotificationTimer();

        // Wait 12 seconds (longer than our retry sequence) before showing failure message
        this._failureNotificationTimer = setTimeout(() => {
            if (this._connectionState !== ConnectionState.Connected) {
                this._notifyConnectionFailure('Unable to connect to CNC server');
            }
        }, 12000);

    }

    /**
     * Cancel the failure notification timer
     */
    private _cancelFailureNotificationTimer(): void {
        if (this._failureNotificationTimer) {
            clearTimeout(this._failureNotificationTimer);
            this._failureNotificationTimer = null;
        }
    }

    /**
     * Add a listener for a specific event type
     * @param eventType The type of event to listen for (e.g., 'DROEvent', 'MessageEvent')
     * @param listener Callback function to handle the event
     */
    public addEventListener<T extends SignalREvent>(
        eventType: string,
        listener: SignalREventListener<T>
    ): void {
        if (!this._listeners.has(eventType)) {
            this._listeners.set(eventType, new Set());
        }
        this._listeners.get(eventType)!.add(listener as SignalREventListener);

    }

    /**
     * Remove a listener for a specific event type
     * @param eventType The type of event
     * @param listener The callback function to remove
     */
    public removeEventListener<T extends SignalREvent>(
        eventType: string,
        listener: SignalREventListener<T>
    ): void {
        const listeners = this._listeners.get(eventType);
        if (listeners) {
            listeners.delete(listener as SignalREventListener);

            if (listeners.size === 0) {
                this._listeners.delete(eventType);
            }

            // Listener management is routine - no logging needed
        }
        // No need to log if event type doesn't exist
    }

    /**
     * Remove all listeners for a specific event type
     * @param eventType The type of event (omit to remove all listeners)
     */
    public removeAllListeners(eventType?: string): void {
        if (eventType) {
            this._listeners.delete(eventType);
        } else {
            this._listeners.clear();
        }
    }

    /**
     * Handle incoming CNC messages from SignalR
     */
    private _handleCNCMessage(message: CNCMessage): void {
        try {
            // Normalize PascalCase to camelCase
            const eventType = message.EventType || message.eventType;
            const timestamp = message.Timestamp || message.timestamp;

            // Validate message format
            if (!eventType || !timestamp) {
                Logger.Instance.logError(LogCategory.Network, `Invalid message format - missing EventType/eventType or Timestamp/timestamp:`, message);
                return;
            }

            // Check for out-of-order events by comparing timestamps
            if (this._lastEventTimestamp) {
                const lastTimestamp = new Date(this._lastEventTimestamp);
                const currentTimestamp = new Date(timestamp);

                if (currentTimestamp < lastTimestamp) {
                    const timeDiff = lastTimestamp.getTime() - currentTimestamp.getTime();
                    Logger.Instance.logError(
                        LogCategory.Network,
                        `⚠️ OUT-OF-ORDER EVENT DETECTED: ${eventType} is ${timeDiff}ms older than previous event`,
                        {
                            eventType: eventType,
                            currentTimestamp: timestamp,
                            previousTimestamp: this._lastEventTimestamp,
                            timeDifferenceMs: timeDiff
                        }
                    );
                }
            }

            // Update last timestamp
            this._lastEventTimestamp = timestamp;

            let event: SignalREvent;

            // Create the appropriate event object based on message type
            switch (eventType) {
                case 'DROEvent':
                    event = new DROEvent(message);
                    break;
                case 'MessageEvent':
                    event = new MessageEvent(message);
                    break;
                case 'JobInfoEvent':
                    event = new JobInfoEvent(message);
                    break;
                case 'JobStartedEvent':
                    event = new JobStartedEvent(message);
                    break;
                case 'JobCompletedEvent':
                    event = new JobCompletedEvent(message);
                    break;
                case 'StepExecutionEvent':
                    event = new StepExecutionEvent(message);
                    break;
                case 'ServerStatus':
                    event = new ServerStatusEvent(message);
                    break;
                case 'OutputStateChanged':
                    event = new OutputStateChangedEvent(message);
                    break;
                default:
                    Logger.Instance.logError(
                        LogCategory.Network,
                        `Unknown message type: ${eventType}`,
                        message
                    );
                    return;
            }

            // Notify all listeners for this event type
            this._notifyListeners(eventType, event);
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.Network,
                'Error handling CNC message',
                error,
                message
            );
        }
    }

    /**
     * Notify all listeners for a specific event type
     */
    private _notifyListeners(eventType: string, event: SignalREvent): void {
        const listeners = this._listeners.get(eventType);
        if (listeners) {
            // Notify all listeners - only log errors
            listeners.forEach((listener) => {
                try {
                    listener(event);
                } catch (error) {
                    Logger.Instance.logError(
                        LogCategory.Network,
                        `Error in SignalR event listener for ${eventType}`,
                        error
                    );
                }
            });
        }
        // No need to log when no listeners exist - this is normal for many event types
    }

    /**
     * Send a message to the hub (if needed for bidirectional communication)
     * @param methodName The hub method name to invoke
     * @param args Arguments to pass to the method
     */
    public async invoke(methodName: string, ...args: any[]): Promise<any> {
        if (!this._connection) {
            Logger.Instance.logError(LogCategory.Network, 'SignalR connection not initialized');
            throw new Error('SignalR connection not initialized');
        }

        if (this._connectionState !== ConnectionState.Connected) {
            Logger.Instance.logError(LogCategory.Network, 'SignalR not connected');
            throw new Error('SignalR not connected');
        }

        try {
            return await this._connection.invoke(methodName, ...args);
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.Network,
                `Error invoking ${methodName}`,
                error
            );
            throw error;
        }
    }



    /**
     * Test method to simulate receiving a message (for debugging)
     * Can be called from browser console: SignalRManager.Instance.testMessage()
     */
    public testMessage(): void {

        const testMessage: CNCMessage = {
            eventType: 'MessageEvent',
            timestamp: new Date().toISOString(),
            data: {
                timestamp: new Date().toISOString(),
                messageType: 'MessageEvent',
                message: 'Test message from SignalR debug',
                eventCode: 999,
                eventType: 'Info'
            }
        };

        this._handleCNCMessage(testMessage);
    }

    /**
     * Emit a local SignalR event (for simulator mode)
     * This allows the simulator to emit events that will be picked up by all listeners
     * just as if they came from the real SignalR connection
     */
    public emitLocalEvent(message: CNCMessage): void {
        this._handleCNCMessage(message);
    }
}
