import { PLCProgram } from '../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../centroid/plc/data/PLCUtilities';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { StateManager } from '../utils/statemanager/StateManager';
import { PLCInputName, PLCOutputName } from './PLCIONames';

/**
 * Full input definition with number and state
 */
export class InputWithState {
    private _number: number = 0;
    private _centroidName: string = '';
    private _name: string = '';
    private _activeText: string = 'Active';
    private _inactiveText: string = 'Inactive';
    private _isActive: boolean = false;
    private _isInverted: boolean = false;

    public get number(): number {
        return this._number;
    }

    public set number(value: number) {
        this._number = value;
        StateManager.propertyChanged(this, 'number');
    }

    public get centroidName(): string {
        return this._centroidName;
    }

    public set centroidName(value: string) {
        this._centroidName = value;
        StateManager.propertyChanged(this, 'centroidName');
    }

    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
    }

    public get activeText(): string {
        return this._activeText;
    }

    public set activeText(value: string) {
        this._activeText = value;
        StateManager.propertyChanged(this, 'activeText');
    }

    public get inactiveText(): string {
        return this._inactiveText;
    }

    public set inactiveText(value: string) {
        this._inactiveText = value;
        StateManager.propertyChanged(this, 'inactiveText');
    }

    public get isActive(): boolean {
        return this._isActive;
    }

    public set isActive(value: boolean) {
        this._isActive = value;
        StateManager.propertyChanged(this, 'isActive');
    }

    public get isInverted(): boolean {
        return this._isInverted;
    }

    public set isInverted(value: boolean) {
        this._isInverted = value;
        StateManager.propertyChanged(this, 'isInverted');
    }

    /**
     * Get the display state considering inversion
     * When inverted, the hardware state is flipped before display
     */
    public get displayState(): boolean {
        return this._isInverted ? !this._isActive : this._isActive;
    }

    /**
     * Generate G-code to wait for input to be ACTIVE (ON)
     */
    public getWaitForActiveGCode(): string {
        return `M101 /5${this.number.toString().padStart(4, '0')}`;
    }

    /**
     * Generate G-code to wait for input to be INACTIVE (OFF)
     */
    public getWaitForInactiveGCode(): string {
        return `M100 /5${this.number.toString().padStart(4, '0')}`;
    }
}

/**
 * Full output definition with number and state
 */
export class OutputWithState {
    private _number: number = 0;
    private _centroidName: string = '';
    private _name: string = '';
    private _activeText: string = 'Active';
    private _inactiveText: string = 'Inactive';
    private _isActive: boolean = false;
    private _isForced: boolean = false;
    private _onGCode?: string;
    private _offGCode?: string;

    public get number(): number {
        return this._number;
    }

    public set number(value: number) {
        this._number = value;
        StateManager.propertyChanged(this, 'number');
    }

    public get centroidName(): string {
        return this._centroidName;
    }

    public set centroidName(value: string) {
        this._centroidName = value;
        StateManager.propertyChanged(this, 'centroidName');
    }

    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
    }

    public get activeText(): string {
        return this._activeText;
    }

    public set activeText(value: string) {
        this._activeText = value;
        StateManager.propertyChanged(this, 'activeText');
    }

    public get inactiveText(): string {
        return this._inactiveText;
    }

    public set inactiveText(value: string) {
        this._inactiveText = value;
        StateManager.propertyChanged(this, 'inactiveText');
    }

    public get isActive(): boolean {
        return this._isActive;
    }

    public set isActive(value: boolean) {
        this._isActive = value;
        StateManager.propertyChanged(this, 'isActive');
    }

    public get isForced(): boolean {
        return this._isForced;
    }

    public set isForced(value: boolean) {
        this._isForced = value;
        StateManager.propertyChanged(this, 'isForced');
    }

    /**
     * Get G-code to turn output ON. Returns custom G-code if set, otherwise M94/[51 + output number]
     */
    public getOnGCode(): string {
        return this._onGCode ?? `M94/${51 + this.number}`;
    }

    /**
     * Set custom G-code to turn output ON. Pass undefined to use default M94/[51 + output number]
     */
    public setOnGCode(value?: string): void {
        this._onGCode = value;
    }

    /**
     * Get G-code to turn output OFF. Returns custom G-code if set, otherwise M95/[51 + output number]
     */
    public getOffGCode(): string {
        return this._offGCode ?? `M95/${51 + this.number}`;
    }

    /**
     * Set custom G-code to turn output OFF. Pass undefined to use default M95/[51 + output number]
     */
    public setOffGCode(value?: string): void {
        this._offGCode = value;
    }

    /**
     * Check if custom ON G-code has been explicitly set (not using default)
     */
    public hasCustomOnGCode(): boolean {
        return this._onGCode !== undefined;
    }

    /**
     * Check if custom OFF G-code has been explicitly set (not using default)
     */
    public hasCustomOffGCode(): boolean {
        return this._offGCode !== undefined;
    }
}

/**
 * Singleton class to manage I/O state
 * Combines API definitions, static metadata, and runtime state
 */
export class IOStateData {
    private static _instance: IOStateData;

    private _inputs: InputWithState[] = [];
    private _outputs: OutputWithState[] = [];
    private _isInitialized: boolean = false;

    private constructor() { }

    public static get Instance(): IOStateData {
        if (!IOStateData._instance) {
            IOStateData._instance = new IOStateData();
        }
        return IOStateData._instance;
    }

    public get inputs(): InputWithState[] {
        return this._inputs;
    }

    public get outputs(): OutputWithState[] {
        return this._outputs;
    }

    public get isInitialized(): boolean {
        return this._isInitialized;
    }

    /**
     * Initialize I/O state by fetching from API and combining with metadata from PLC
     */
    public async initialize(): Promise<void> {
        try {
            const machineInterface = MachineInterfaceManager.Instance.getMachineInterface();

            // Get inputs and outputs from System PLC program
            const systemPLC = PLCProgram.Instance(PLCProgramType.System);
            const plcInputs = systemPLC.inputs;
            const plcOutputs = systemPLC.outputs;

            // Extract output numbers that have been assigned
            const outputNumbers = plcOutputs
                .filter(output => output.number !== null)
                .map(output => output.number!);

            // Get defined I/O with states from CentroidCNCIO (which queries PLC + backend)
            const [definedInputs, definedOutputs, forcedOutputsDict] = await Promise.all([
                machineInterface.io.GetDefinedInputs(),
                machineInterface.io.GetDefinedOutputs(),
                outputNumbers.length > 0 ? machineInterface.io.GetForcedOutputs(outputNumbers) : Promise.resolve({})
            ]);

            // Convert to lookup maps
            const inputStates: Record<number, boolean> = {};
            definedInputs.forEach(input => {
                if (input.number !== undefined) {
                    inputStates[input.number] = input.state ?? false;
                }
            });

            const outputStates: Record<number, boolean> = {};
            definedOutputs.forEach(output => {
                if (output.number !== undefined) {
                    outputStates[output.number] = output.state ?? false;
                }
            });

            // Build inputs with state
            this._inputs = plcInputs
                .filter(plcInput => plcInput.number !== null)
                .map(plcInput => {
                    const input = new InputWithState();
                    input.number = plcInput.number!;
                    input.centroidName = plcInput.centroidName;
                    input.name = plcInput.name;
                    input.activeText = plcInput.activeText;
                    input.inactiveText = plcInput.inactiveText;
                    input.isInverted = plcInput.isInverted;
                    input.isActive = inputStates[plcInput.number!] ?? false;
                    return input;
                });

            // Build outputs with state
            this._outputs = plcOutputs
                .filter(plcOutput => plcOutput.number !== null)
                .map(plcOutput => {
                    const output = new OutputWithState();
                    output.number = plcOutput.number!;
                    output.centroidName = plcOutput.centroidName;
                    output.name = plcOutput.name;
                    output.activeText = plcOutput.activeText;
                    output.inactiveText = plcOutput.inactiveText;
                    output.isActive = outputStates[plcOutput.number!] ?? false;
                    // Set custom G-code commands from PLCOutput
                    output.setOnGCode(plcOutput.getOnGCode());
                    output.setOffGCode(plcOutput.getOffGCode());
                    return output;
                });

            // Set forced state for outputs
            this.updateForcedOutputs(forcedOutputsDict);

            this._isInitialized = true;

            StateManager.propertyChanged(this, 'inputs');
            StateManager.propertyChanged(this, 'outputs');
            StateManager.propertyChanged(this, 'isInitialized');
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'IOStateData: Failed to initialize I/O state:', error);
            throw error;
        }
    }

    /**
     * Update state of a specific input
     */
    public updateInputState(number: number, isActive: boolean): void {
        const input = this._inputs.find(i => i.number === number);
        if (input) {
            input.isActive = isActive; // Setter automatically calls StateManager.propertyChanged(input, 'isActive')
        }
    }

    /**
     * Update state of a specific output
     */
    public updateOutputState(number: number, isActive: boolean): void {
        const output = this._outputs.find(o => o.number === number);
        if (output) {
            output.isActive = isActive; // Setter automatically calls StateManager.propertyChanged(output, 'isActive')
        }
    }

    /**
     * Update all input states at once
     */
    public updateAllInputStates(states: Record<number, boolean>): void {
        this._inputs.forEach(input => {
            if (states[input.number] !== undefined) {
                input.isActive = states[input.number];
            }
        });
        this._inputs = [...this._inputs];
        StateManager.propertyChanged(this, 'inputs');
    }

    /**
     * Update all output states at once
     */
    public updateAllOutputStates(states: Record<number, boolean>): void {
        this._outputs.forEach(output => {
            if (states[output.number] !== undefined) {
                output.isActive = states[output.number];
            }
        });
        this._outputs = [...this._outputs];
        StateManager.propertyChanged(this, 'outputs');
    }

    /**
     * Get input by number
     */
    public getInputByNumber(number: number): InputWithState | undefined {
        return this._inputs.find(i => i.number === number);
    }

    /**
     * Get output by number
     */
    public getOutputByNumber(number: number): OutputWithState | undefined {
        return this._outputs.find(o => o.number === number);
    }

    /**
     * Get input by centroid name
     */
    public getInputByCentroidName(centroidName: string): InputWithState | undefined {
        return this._inputs.find(i => i.centroidName === centroidName);
    }

    /**
     * Get output by centroid name
     */
    public getOutputByCentroidName(centroidName: string): OutputWithState | undefined {
        return this._outputs.find(o => o.centroidName === centroidName);
    }

    /**
     * Get input by PLC name enum
     * Returns undefined if input is not configured in the PLC
     */
    public getInputByName(name: PLCInputName): InputWithState | undefined {
        return this._inputs.find(i => i.centroidName === name);
    }

    /**
     * Get output by PLC name enum
     * Returns undefined if output is not configured in the PLC
     */
    public getOutputByName(name: PLCOutputName): OutputWithState | undefined {
        return this._outputs.find(o => o.centroidName === name);
    }

    /**
     * Update forced state for a specific output
     */
    public updateOutputForcedState(number: number, forceState: string, isActive: boolean): void {
        const output = this._outputs.find(o => o.number === number);
        if (output) {
            output.isForced = forceState !== 'NotForced';
            output.isActive = isActive;
            this._outputs = [...this._outputs];
            StateManager.propertyChanged(this, 'outputs');
        }
    }

    /**
     * Update forced outputs from API response
     */
    public updateForcedOutputs(forcedOutputs: Record<number, string>): void {
        // First, clear all forced states
        this._outputs.forEach(output => {
            output.isForced = false;
        });

        // Then set forced state for outputs in the dictionary
        Object.entries(forcedOutputs).forEach(([numStr, forceState]) => {
            const number = parseInt(numStr, 10);
            if (!isNaN(number)) {
                const output = this._outputs.find(o => o.number === number);
                if (output) {
                    output.isForced = forceState !== 'NotForced';
                }
            }
        });

        this._outputs = [...this._outputs];

        StateManager.propertyChanged(this, 'outputs');
    }
}
