import { Box } from '@mui/material';
import React from 'react';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';
import { ToggleStagePredicate } from '../predicates/ToggleStagePredicate';
import { BasePLCStatement } from './BasePLCStatement';

/**
 * Toggle stage statement - a simple statement that controls stage activation
 * Renders as: IF 1==1 THEN [stage toggle]
 */
export class ToggleStageStatement extends BasePLCStatement {
    private _predicate: ToggleStagePredicate;

    constructor() {
        super();
        this._predicate = new ToggleStagePredicate();
        this._predicate.setParentElement(this);

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Get the toggle stage predicate
     */
    public get predicate(): ToggleStagePredicate {
        return this._predicate;
    }

    /**
     * Set the toggle stage predicate
     */
    public set predicate(value: ToggleStagePredicate) {
        this._predicate = value;
        this._predicate.setParentElement(this);
        StateManager.propertyChanged(this, 'predicate');
    }

    /**
     * Get a short, single-line description for display in tree views
     * Delegates to the predicate
     * @returns A human-readable summary of the stage toggle
     */
    public getShortDescription(): string {
        return this._predicate.getShortDescription();
    }

    /**
     * Get all data elements used by this statement
     */
    public getDataElements(): DataElement[] {
        return this._predicate.getDataElements();
    }

    /**
     * Render the statement to JSX
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <ToggleStageStatementRenderer statement={this} renderMode={mode} targetProgramType={targetProgramType} />;
    }

    /**
     * Get declarations that are used/referenced by this statement
     */
    public getUsedDeclarations(): Declaration[] {
        return this._predicate.getUsedDeclarations();
    }

    /**
     * Get declarations that are added/defined by this statement
     */
    public getAddedDeclarations(): Declaration[] {
        return this._predicate.getAddedDeclarations();
    }

    /**
     * Get the PLC logic code for this statement
     */
    public getPLCLogic(): string[] {
        if (this.isDisabled(PLCRenderMode.Edit, PLCProgramType.System)) {
            return [];
        }
        const predicateLogic = this._predicate.getPLCLogic();

        if (predicateLogic.length === 0) {
            return ['IF 1==1 THEN ; Toggle stage not configured'];
        }

        // Get comment from predicate
        const comment = this._predicate.getComment();
        const commentPart = comment ? `    ; ${comment}` : '';

        // All actions produce single line output: IF 1==1 THEN <action>
        // SET Stage_X, RST Stage_X, or JMP StageName
        return [`IF 1==1 THEN ${predicateLogic[0]}${commentPart}`];
    }

    /**
     * Get validation issues for this statement
     */
    public getValidationIssues(): PLCValidationIssue[] {
        if (this.isDisabled(PLCRenderMode.Edit, PLCProgramType.System)) {
            return [];
        }
        return this._predicate.getValidationIssues();
    }

    /**
     * Validate the statement (implements BasePLCStatement)
     */
    public validate(): string | undefined {
        return this._predicate.validate();
    }

    /**
     * Clone the statement (implements BasePLCStatement)
     */
    public clone(): ToggleStageStatement {
        const cloned = new ToggleStageStatement();
        cloned.predicate = this._predicate.clone();
        cloned.enabled = this.enabled;
        cloned.comment = this.comment;
        return cloned;
    }

    /**
     * Override setParentElement to cascade to predicate
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        if (this._predicate) {
            this._predicate.setParentElement(this);
        }
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_predicate']);
        return {
            type: 'ToggleStageStatement',
            ...baseData,
            predicate: this._predicate.toJSON()
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // Load predicate - support both old (_predicate) and new (predicate) property names
        const predicateData = data._predicate || data.predicate;
        if (predicateData) {
            this._predicate = new ToggleStagePredicate();
            this._predicate.fromJSON(predicateData);
            this._predicate.setParentElement(this);
        }

        // Load remaining properties - exclude both old and new property names
        DataUtilities.loadStorageData(this, data, ['_predicate', 'predicate']);
    }
}

/**
 * Functional component for rendering ToggleStageStatement
 */
function ToggleStageStatementRenderer({ statement, renderMode, targetProgramType }: { statement: ToggleStageStatement; renderMode?: PLCRenderMode; targetProgramType: PLCProgramType }) {
    const effectiveRenderMode = renderMode || PLCRenderMode.Edit;
    const effectiveMode = effectiveRenderMode === PLCRenderMode.Edit && statement.isDisabled(effectiveRenderMode, targetProgramType)
        ? PLCRenderMode.Disabled
        : effectiveRenderMode;

    return (
        <ObserveState
            key="toggle-stage-statement" profilerName="ToggleStageStatement-render" listenTo={statement}
            properties={['enabled']}

            control={() => {

                return (
                    <Box
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 1,
                            opacity: effectiveMode === PLCRenderMode.Disabled ? 0.6 : 1,
                            textDecoration: effectiveMode === PLCRenderMode.Disabled ? 'line-through' : 'none'
                        }}
                    >
                        <ObserveState
                            key="toggle-stage-statement-predicate" profilerName="ToggleStageStatement-predicate" listenTo={statement.predicate}
                            properties={['stageName', 'action']}

                            control={() => statement.predicate.render(effectiveMode, targetProgramType)}
                        />
                    </Box>
                );
            }}
        />
    );
}
