import {
  Box,
  Button,
  ToggleButton,
  ToggleButtonGroup,
  Tooltip,
  Typography
} from '@mui/material';
import { useEffect } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineData } from '../../data/Machine/MachineData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { JogDirection, Machine } from '../../machine/Machine';
import { JogRenewalManager } from '../../utils/JogRenewalManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { AxisCoordinateDisplay } from './AxisCoordinateDisplay';
import { SafeModeControl } from './SafeModeControl';

export function ZJogControls() {
  const configState = ConfigurationState.Instance;

  useEffect(() => {
    // Cleanup jog renewal manager when component unmounts
    return () => {
      JogRenewalManager.Instance.cleanup();
    };
  }, []);

  const handleJogStart = async (direction: JogDirection) => {
    try {
      // Use JogRenewalManager to handle jog with automatic renewal
      await JogRenewalManager.Instance.startJog(direction);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to start Z jog:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to start Z jog movement');
    }
  };

  const handleJogStop = () => {
    // Stop all jog movements using renewal manager
    JogRenewalManager.Instance.stopAll();
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 3 }}>
      <Typography variant="body2" sx={{ mb: 2 }}>
        Z-Axis Jog Controls
      </Typography>

      <ObserveMultiProperties
        key="z-jog-speed-observer"
        listenTo={[
          { object: configState, properties: ['jogContinuousMode', 'jogFastMode', 'jogIncrementSpeed'] },
          { object: MachineData.Instance, properties: ['linearJogIncrement'] }
        ]}
        control={() => (
          <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, width: '100%' }}>
            {/* Top Row: Z Coordinate Display and Up/Down Buttons */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
              {/* Z Coordinate Display */}
              <Box sx={{ flex: 1 }}>
                <AxisCoordinateDisplay axes={['Z']} showSetButton={false} showCoordinateTypeToggle={true} reserveButtonSpace={true} />
              </Box>

              {/* Z Jog Buttons */}
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <Button
                  variant="contained"
                  color="primary"
                  sx={{ minWidth: 80, minHeight: 50, fontSize: '1.5rem', mb: 1 }}
                  onMouseDown={() => handleJogStart(JogDirection.ZPlus)}
                  onMouseUp={handleJogStop}
                  onMouseLeave={handleJogStop}
                >
                  ▲
                </Button>
                <Button
                  variant="contained"
                  color="primary"
                  sx={{ minWidth: 80, minHeight: 50, fontSize: '1.5rem' }}
                  onMouseDown={() => handleJogStart(JogDirection.ZMinus)}
                  onMouseUp={handleJogStop}
                  onMouseLeave={handleJogStop}
                >
                  ▼
                </Button>
              </Box>
            </Box>

            {/* Bottom Row: Speed Toggle Buttons and Mode Controls */}
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1, width: '100%' }}>
              {/* Speed Toggle Buttons */}
              <ToggleButtonGroup
                value={configState.jogIncrementSpeed}
                exclusive
                onChange={async (e, value) => {
                  if (value !== null) {
                    try {
                      await Machine.getInstance().movement.SetJogIncrementSpeed(value);
                    } catch (error) {
                      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set jog increment speed:', error);
                      UserMessageQueue.Instance.addMessage('❌ Failed to set jog speed');
                    }
                  }
                }}
                size="small"
                sx={{
                  '& .MuiToggleButton-root.Mui-selected': {
                    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                    color: ConfigurationDataColors.Instance.lightTextColor,
                    '&:hover': {
                      backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                      opacity: 0.9
                    }
                  }
                }}
              >
                <ToggleButton value={'X1'} sx={{ minWidth: '56px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                  {parseFloat(ConfigurationData.Instance.jogIncrement1x.toFixed(4))}
                </ToggleButton>
                <ToggleButton value={'X10'} sx={{ minWidth: '56px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                  {parseFloat((ConfigurationData.Instance.jogIncrement1x * 10).toFixed(3))}
                </ToggleButton>
                <ToggleButton value={'X100'} sx={{ minWidth: '56px', fontWeight: 'bold', fontSize: '0.75rem', padding: '4px 8px' }}>
                  {parseFloat((ConfigurationData.Instance.jogIncrement1x * 100).toFixed(2))}
                </ToggleButton>
              </ToggleButtonGroup>

              {/* Continuous/Incremental Toggle Button */}
              <Tooltip title={configState.jogContinuousMode ? 'Click to switch to Incremental Mode' : 'Click to switch to Continuous Mode'} arrow>
                <ToggleButton
                  value="continuous"
                  selected={configState.jogContinuousMode}
                  onChange={async () => {
                    try {
                      const newMode = !configState.jogContinuousMode;
                      configState.jogContinuousMode = newMode;
                      await Machine.getInstance().movement.SetContinuousJog(newMode);
                    } catch (error) {
                      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set continuous jog mode:', error);
                      UserMessageQueue.Instance.addMessage('❌ Failed to set jog mode');
                    }
                  }}
                  sx={{
                    minWidth: '90px',
                    fontWeight: 'bold',
                    fontSize: '0.75rem',
                    padding: '4px 8px',
                    backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                    color: ConfigurationDataColors.Instance.lightTextColor,
                    border: 'none',
                    '&:hover': {
                      backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                      opacity: 0.85
                    },
                    '&.Mui-selected': {
                      backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                      color: ConfigurationDataColors.Instance.lightTextColor,
                      '&:hover': {
                        backgroundColor: configState.jogContinuousMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                        opacity: 0.85
                      }
                    }
                  }}
                >
                  {configState.jogContinuousMode ? 'CONTINUOUS' : 'INCREMENTAL'}
                </ToggleButton>
              </Tooltip>

              {/* Fast/Slow Jog Toggle Button */}
              <Tooltip title={configState.jogFastMode ? 'Click to switch to Slow Jog' : 'Click to switch to Fast Jog'} arrow>
                <ToggleButton
                  value="fast"
                  selected={configState.jogFastMode}
                  onChange={async () => {
                    try {
                      const newMode = !configState.jogFastMode;
                      configState.jogFastMode = newMode;
                      await Machine.getInstance().movement.SetFastJog(newMode);
                    } catch (error) {
                      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set fast jog mode:', error);
                      UserMessageQueue.Instance.addMessage('❌ Failed to set fast jog speed');
                    }
                  }}
                  sx={{
                    minWidth: '60px',
                    fontWeight: 'bold',
                    fontSize: '0.75rem',
                    padding: '4px 8px',
                    backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                    color: ConfigurationDataColors.Instance.lightTextColor,
                    border: 'none',
                    '&:hover': {
                      backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                      opacity: 0.85
                    },
                    '&.Mui-selected': {
                      backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                      color: ConfigurationDataColors.Instance.lightTextColor,
                      '&:hover': {
                        backgroundColor: configState.jogFastMode ? ConfigurationDataColors.Instance.primaryColor : ConfigurationDataColors.Instance.secondaryColor,
                        opacity: 0.85
                      }
                    }
                  }}
                >
                  {configState.jogFastMode ? 'FAST' : 'SLOW'}
                </ToggleButton>
              </Tooltip>
            </Box>

            {/* Safe Mode section */}
            <Box sx={{ mt: 1, pt: 1, borderTop: `1px solid ${ConfigurationDataColors.Instance.borderColor}`, width: '100%' }}>
              <SafeModeControl variant="compact" />
            </Box>
          </Box>
        )}
      />
    </Box>
  );
}
