import { Close as CloseIcon, ContentCopy as CopyIcon } from '@mui/icons-material';
import { Box, Dialog, DialogContent, DialogTitle, IconButton, Paper, Tab, Tabs, Tooltip, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { PLCProgram, PLCProgramSystem } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';

interface PLCViewerDialogProps {
    open: boolean;
    onClose: () => void;
}

/**
 * Dialog for viewing generated PLC code
 * Generates complete PLC program combining System Default and System programs
 */
export function PLCViewerDialog({ open, onClose }: PLCViewerDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [activeTab, setActiveTab] = useState(0);

    // Only generate code when dialog is actually open to avoid premature validation
    const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
    const generatedCode = open ? system.generateCompletePLCCode() : '';
    const messageFile = open ? system.generateMessageFile() : '';

    const handleCopyToClipboard = async () => {
        try {
            const contentToCopy = activeTab === 0 ? generatedCode : messageFile;
            await navigator.clipboard.writeText(contentToCopy);
        } catch (error) {
            UserMessageQueue.Instance.addMessage('❌ Failed to copy to clipboard');
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="lg"
            fullWidth
            PaperProps={{
                sx: {
                    height: '90vh',
                    maxHeight: '90vh'
                }
            }}
        >
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2
                }}
            >
                <Typography variant="h6">View PLC Code</Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Tooltip title="Copy to Clipboard" arrow>
                        <IconButton
                            onClick={handleCopyToClipboard}
                            sx={{
                                color: colors.lightTextColor,
                                '&:hover': {
                                    backgroundColor: `${colors.lightTextColor}1A`
                                }
                            }}
                        >
                            <CopyIcon />
                        </IconButton>
                    </Tooltip>
                    <IconButton
                        onClick={onClose}
                        sx={{
                            color: colors.lightTextColor,
                            '&:hover': {
                                backgroundColor: `${colors.lightTextColor}1A`
                            }
                        }}
                    >
                        <CloseIcon />
                    </IconButton>
                </Box>
            </DialogTitle>
            <DialogContent sx={{ p: 0, display: 'flex', flexDirection: 'column' }}>
                {/* Tabs for Source Code and Message File */}
                <Box sx={{ borderBottom: 1, borderColor: 'divider', px: 3, pt: 2 }}>
                    <Tabs
                        value={activeTab}
                        onChange={(_, newValue) => setActiveTab(newValue)}
                        sx={{
                            '& .MuiTab-root': {
                                color: colors.darkTextColor
                            },
                            '& .Mui-selected': {
                                color: colors.primaryColor
                            },
                            '& .MuiTabs-indicator': {
                                backgroundColor: colors.primaryColor
                            }
                        }}
                    >
                        <Tab label="Source Code" />
                        <Tab label="Message File" />
                    </Tabs>
                </Box>

                <Paper
                    sx={{
                        flex: 1,
                        m: 2,
                        p: 2,
                        backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                        overflow: 'auto',
                        fontFamily: 'Consolas, Monaco, "Courier New", monospace',
                        fontSize: '13px',
                        lineHeight: 1.5
                    }}
                >
                    <pre
                        style={{
                            margin: 0,
                            color: ConfigurationDataColors.Instance.lightTextColor,
                            whiteSpace: 'pre',
                            wordWrap: 'normal'
                        }}
                    >
                        {activeTab === 0 ? generatedCode : messageFile}
                    </pre>
                </Paper>
            </DialogContent>
        </Dialog>
    );
}
