import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { AxisType } from './AxisType';
import { MachineData } from './MachineData';

/**
 * Axis configuration class
 * Contains all the configuration settings for a single machine axis
 */



export class AxisConfig implements IStorable {
    private _axisType: AxisType;
    private _axisNumber: number;

    // Motion parameters
    private _stepsPerRevolution: number = 1600;
    private _overallTurnsRatio: number = 5;
    private _lashCompensation: number = 0; // in inches or mm
    private _accelDecel: number = 0.5; // seconds
    private _directionReversal: boolean = false; // true = reversed, false = normal

    // Advanced settings (speed settings now in ConfigurationData, only signal inversions remain here)
    private _stepSignalInverted: boolean = false;
    private _directionSignalInverted: boolean = false;
    private _enableSignalInverted: boolean = false;

    constructor(axisType: AxisType, axisNumber: number) {
        this._axisType = axisType;
        this._axisNumber = axisNumber;
    }

    // Axis identification
    public get axisType(): AxisType {
        return this._axisType;
    }

    public set axisType(value: AxisType) {
        this._axisType = value;
        StateManager.propertyChanged(this, 'axisType');
        // Also notify MachineData that axis configurations have changed
        // so other axis dropdowns can update their available options
        StateManager.propertyChanged(MachineData.Instance, 'axisConfigurations');
    }

    public get axisNumber(): number {
        return this._axisNumber;
    }

    public set axisNumber(value: number) {
        this._axisNumber = value;
        StateManager.propertyChanged(this, 'axisNumber');
    }

    // Motion parameters
    public get stepsPerRevolution(): number {
        return this._stepsPerRevolution;
    }

    public set stepsPerRevolution(value: number) {
        this._stepsPerRevolution = value;
        StateManager.propertyChanged(this, 'stepsPerRevolution');
    }

    public get overallTurnsRatio(): number {
        return this._overallTurnsRatio;
    }

    public set overallTurnsRatio(value: number) {
        this._overallTurnsRatio = value;
        StateManager.propertyChanged(this, 'overallTurnsRatio');
    }

    public get lashCompensation(): number {
        return this._lashCompensation;
    }

    public set lashCompensation(value: number) {
        this._lashCompensation = value;
        StateManager.propertyChanged(this, 'lashCompensation');
    }

    public get accelDecel(): number {
        return this._accelDecel;
    }

    public set accelDecel(value: number) {
        this._accelDecel = value;
        StateManager.propertyChanged(this, 'accelDecel');
    }

    public get directionReversal(): boolean {
        return this._directionReversal;
    }

    public set directionReversal(value: boolean) {
        this._directionReversal = value;
        StateManager.propertyChanged(this, 'directionReversal');
    }

    // Advanced settings
    public get stepSignalInverted(): boolean {
        return this._stepSignalInverted;
    }

    public set stepSignalInverted(value: boolean) {
        this._stepSignalInverted = value;
        StateManager.propertyChanged(this, 'stepSignalInverted');
    }

    public get directionSignalInverted(): boolean {
        return this._directionSignalInverted;
    }

    public set directionSignalInverted(value: boolean) {
        this._directionSignalInverted = value;
        StateManager.propertyChanged(this, 'directionSignalInverted');
    }

    public get enableSignalInverted(): boolean {
        return this._enableSignalInverted;
    }

    public set enableSignalInverted(value: boolean) {
        this._enableSignalInverted = value;
        StateManager.propertyChanged(this, 'enableSignalInverted');
    }

    // IStorable implementation
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
