import React, { useMemo, forwardRef } from 'react';
import { ViewStyle } from '../../../data/Common/ViewStyle';

export interface BoxProps {
  position: [number, number, number];
  size: [number, number, number];
  color: string;
  viewStyle: ViewStyle;
  opacity?: number;
  onClick?: (event: any) => void;
  onPointerDown?: (event: any) => void;
  onPointerUp?: (event: any) => void;
  onPointerMove?: (event: any) => void;
  onPointerOver?: (event: any) => void;
  onPointerOut?: (event: any) => void;
}

export const Box = forwardRef<any, BoxProps>((props, ref) => {
  const {
    position,
    size,
    color,
    viewStyle,
    opacity = 1,
    onClick,
    onPointerDown,
    onPointerUp,
    onPointerMove,
    onPointerOver,
    onPointerOut
  } = props;

  const material = useMemo(() => {
    const baseProps = {
      metalness: 0.2,  // Slight metallic look for machine parts
      roughness: 0.4,  // Not too shiny, not too rough
    };
    
    switch (viewStyle) {
      case ViewStyle.Hide:
        return { visible: false };
      case ViewStyle.Wireframe:
        return {
          ...baseProps,
          wireframe: true,
          color,
          transparent: false,
          opacity: 1
        };
      case ViewStyle.SemiTransparent:
        return {
          ...baseProps,
          color,
          transparent: true,
          opacity: opacity // Use the passed opacity prop instead of hardcoded 0.5
        };
      case ViewStyle.Show:
      default:
        return {
          ...baseProps,
          color,
          transparent: opacity < 1,
          opacity
        };
    }
  }, [color, viewStyle, opacity]);

  if (viewStyle === ViewStyle.Hide) {
    return null;
  }

  // Create unique key for React re-rendering when material properties change
  const renderKey = `box-${ViewStyle[viewStyle]}-${opacity}-${color}-${Date.now()}`;

  return (
    <mesh 
      key={renderKey}
      ref={ref}
      position={position}
      onClick={onClick}
      onPointerDown={onPointerDown}
      onPointerUp={onPointerUp}
      onPointerMove={onPointerMove}
      onPointerOver={onPointerOver}
      onPointerOut={onPointerOut}
    >
      <boxGeometry args={size} />
      <meshStandardMaterial {...material} />
    </mesh>
  );
});